window.__D("text/torat-shmuel/c013",{"p":[[2000510452,"כי יש כבש וכשב<sup data-n=\"1507\">21</sup>, כבש הוא ע\"פ סדר השתלשלות כסדר המדרגות כ\"ף רומז לבחי' כתר, בי\"ת הוא בחי' חכ', שי\"ן ג' מדות חג\"ת, אבל כשב הנה קדם השי\"ן לבי\"ת להורות על בחי' המדות שלמעלה מן השכל, והיינו בחי' חג\"ת דא\"א, וכשאמר והניף הכהן אותם כו' על שני כבשים הכוונה להגביה אותם למעלה מבחי' כבש, והיינו לבחי' כשב אשר שם גם חמץ יוכל להתעלות, וע\"ד שלע\"ל שיהיו גילוי' עוד יותר עליונים עתיד גם חזיר ליטהר כו', והיינו כי בשבועות הוא מ\"ת. והנה בתורה יש בחי' טל תורה, ע' בכתובות דקי\"ב ב', ובילקוט ע\"פ כי טל אורות טלך בישעי' רמז רח\"ץ כל המשתמש בטל תורה טל תורה מחייהו, ע' בסש\"ב ס\"פ ל\"ו<sup data-n=\"1508\">22</sup>, והיינו כי יש אור תורה וטל תורה<sup data-n=\"1509\">23</sup>, אור הוא כמו שפי' רש\"י בפסחים דס\"ח א' ע\"פ שבעתים כאור שבעת הימים, אור ז' הימים הוא ז' פעמים מ\"ט ושבעתים הם שמ\"ג והיינו בחי' אור תורה שהוא בחי' גשם שבתורה שהגשם הוא בחי' שבא באתעדל\"ת שהוא בחי' ואד יעלה מן הארץ כמ\"ש במ\"א<sup data-n=\"1510\">24</sup>. אבל טל תורה הוא בחי' טלא דנטיף מעתיקא, והוא בחי' טל שעתיד להחיות בו את המתים, ולכן כשפרחה נשמתן בעת מ\"ת החי' אותם ע\"י בחי' טל הזה, ולכן המשתמש בטל תורה טל תורה מחייהו גם בהיותו חי בגוף ג\"כ כמ\"ש מזה במ\"א<sup data-n=\"1511\">25</sup>, ובחי' זו הי' בחגה\"ש בעת מ\"ת, ועי\"ז יכול גם החמץ להתעלות שה\"ז מעין לע\"ל שגם חזיר עתיד ליטהר.\n<b></b>[פא)] ובזה יובן מאמרם ז\"ל בענין יו\"ד דברים<sup data-n=\"1512\">26</sup> שנבראו בערב שבת בין השמשות וי\"א אף קברו של משה, והיינו כי מה שנבראו בין השמשות הוא שמחמת עוצם מעלת דברים אלו א\"א שיבואו בבחי' הבריאה בזמן ממש, להיות כי שרשם הוא מע\"ס דאצי' או ע\"ס הגנוזות, ולהיות כן כשבאו בבריאה, להורות שהגם שנבראו מ\"מ הם פלאי, נבראו בין השמשות שא\"א לידע אם הוא יום או לילה, והיינו שאינו זמן ממש, להורות על הפלאתם גם כשנבראו כמו פי הארץ והבאר כו'. וגם קברו של משה שהוא בחי' שער החמשים שלכן לעליונים נדמה להם למטה ולתחתונים נדמה למעלה, וגם משה בחייו לא השיג שער הנו\"ן שזש\"ה ותחסרהו כו', ובשעת הסתלקותו עלה לבחי' זו, ושרשו הוא בחי' רדל\"א שהוא לא ידע ולא אתיידע, ומ\"מ הוא נמנה בכלל רישא, והיינו מפני כי נתינת התורה הי' ע\"י משה ובתורה יש בחי' אור וטל כנ\"ל. אמנם האיך יכול הנברא להתעלות כ\"כ זהו שאמרו",[["1507","21","<b>כי יש כבש וכשב</b>: ראה בארוכה לקו\"ת אמור לז, ב ואילך. לח, סע\"ד ואילך."],["1508","22","<b>טל תורה. . ע' בסש\"ב ספל\"ו</b>: שם (מו, ב) הובאה הגירסא טל תורה\". [וראה בהנסמן בהע' שלאח\"ז]. וראה גם סה\"מ תרל\"ב ח\"ב ס\"ע תקעד."],["1509","23","<b>יש אור תורה וטל תורה</b>: ראה בארוכה סה\"מ תרכ\"ט ע' תז ואילך [ובהנסמן שם בתחילת המאמר]. סה\"מ תרל\"ב ח\"א ע' קעא. ועוד."],["1510","24","<b>שהגשם. . באתעלד\"ת. . ואד יעלה מן הארץ כמ\"ש במ\"א</b>: ראה לקו\"ת האזינו עג, א ואילך. עד, ב. עה, ד. עטרת ראש מד, א. סה\"מ תרכ\"ז ע' תסב ואילך. וש\"נ. תרכ\"ט ע' תד ואילך. וש\"נ."],["1511","25","<b>טל תורה מחייהו גם בהיותו חי בגוף ג\"כ כמ\"ש מזה במ\"א</b>: ראה סה\"מ תרכ\"ז שם ס\"ע תסד-ה."],["1512","26","<b>ובזה יובן מאמרם ז\"ל בענין יו\"ד דברים</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת וירא וביאוה\"ז להצ\"צ שם."]]],[2000510453,"ז\"ל משה מוטל בכנפי שכינה, והיינו כי מצד חוק הנברא א\"א להתעלות כ\"כ אמנם מחיק הבורא יחיד מי מונע. וי\"א משה לא מת, היינו שעלה למקום שלמעלה מבחי' שבירה ותיקון היינו למעלה מתהו ותיקון, וכמו שבחייו הי' מ' יום עם ה' לחם כו' הם בחי' ד' יודי\"ן דשם ע\"ב, ששם ע\"ב למעלה מתהו ע' בד\"ה ראה אנכי<sup data-n=\"1513\">27</sup> בענין אזרח, והיינו כי התורה היא בחי' בירור ניצוצות דתהו, אמנם באמת תהו ותיקון שניהם רק עולמות, וע\"י הבירור דתהו יורש אורות דתהו וגם עולה למעלה מבחי' התהו, ולכן משה כשבירר חלקו אמרו עליו לא מת כו'.\n<b></b>[פב)] וזהו שאמר לע\"ל והחרים ה' את לשון ים מצרים והניף ידו על הנהר בעים רוחו והכהו לז' נחלים, והענין הוא כי מצרים נת' בת\"א בפ' בשלח בביאור המתחיל וה' הולך לפניהם<sup data-n=\"1514\">28</sup> יומם, שכל ג' עולמות בי\"ע נק' מצרים שהם מצרים וגבולים, והיינו בחי' בי\"ע שעד רום המעלות, ובכלליות הרי גם א\"ק נק' אדם דבריאה, וים הוא בחי' ים המעלים אורות דאצי' כדי שיוכל להיות התהוות בי\"ע, וכמו שהוא בפרטיות כן הוא בכלליות, וע\"ז אמר לע\"ל והחרים הוי' את לשון ים מצרים, כ\"מ שנוכל לומר עליו לשון ים גם בכלליות, את כ\"ז יחרים ה' ע\"ד כל חרם לה' שלמעלה מסדר השתלשלות, ולא עוד אלא שאז יניף ידו על הנהר ג\"כ והכהו לז' נחלים, והיינו כי נהר הוא ג\"כ רק בחי' השגה והבנה שז\"ע בחי' רחובות הנהר, משא\"כ חכ' הוא בחי' ברק המבריק לבד, ולכן החכ' דוקא בחי' כח מ\"ה ביטול, ולא בינה, להיות כי החכ' היא רק בחי' ברק, והבינה נק' בשם יש להיותה בבחי' רחובות הנהר כו', וכענין שר\"ז צם מאה תעניתא<sup data-n=\"1515\">29</sup> כי היכי דלשכח תלמוד בבלי, והיינו כי כל רב מבבל וכל רבי מא\"י שבה מאיר בחי' יו\"ד חכ'<sup data-n=\"1516\">30</sup>, ולכן אמרו אין תורה כתורת א\"י, ובכדי שלא יבלבל לו השגת תלמוד בבלי צם מאה תעניתא כי היכא דלשכח כדי שלא יבלבל לו ההשגה, וכענין הטבילה בנהר דינור בין כל ג\"ע בכדי לבטל את כח הזוכר<sup data-n=\"1517\">31</sup> מג\"ע שלמטה הימנו, כמו\"כ לגבי העלי' שיתעלו נש\"י לע\"ל יניף ידו על הנהר הוא בחי' ההשגה ויבטל אותה, בכדי שלא יבלבל ההשגה את בחי' עוצם הגילוי שיהי' מבחי' א\"ס שעכשיו הוא למעלה מהשגה, וההנפה יהי' בידו הוא בחי' ימינך ב' פעמים, דלית שמאלא בהאי עתיקא. וזהו ההפרש בין קרי\"ס שהי' ע\"י מטה ובין לע\"ל שיהי' ע\"י הנפת היד לבד בלא מטה, והיינו כי בקרי\"ס הי' לרדות בו את פרעה ומה דרכו של כלב לרדות במקל, כך הקב\"ה רודה את הרשעים במקל, אבל",[["1513","27","<b>בד\"ה ראה אנכי</b>: לקו\"ת ראה יח, א. סה\"מ תרכ\"ו ע' רח."],["1514","28","<b>בת\"א בפ' בשלח בביאור המתחיל וה' הולך לפניהם</b>: דף סה, סע\"ג-ד."],["1515","29","<b>וכענין שר\"ז צם מאה תעניתא</b>: ראה תו\"א יתרו סט, ג. מאמרי אדה\"ז תקס\"ו ע' רטו. מאמרי אדהאמ\"צ במדבר ח\"ב ע' תמא. וש\"נ. סה\"מ תרל\"ג ח\"ב ע' תכא. ועוד."],["1516","30","<b>כל רב מבבל וכל רבי מא\"י. . יו\"ד חכ'</b>: ראה בארוכה הוספות לתו\"א קיז, ד. מאמרי אדה\"ז תקס\"ח ח\"א ע' צד ואילך. סה\"מ תרל\"ג שם ע' תכז."],["1517","31","<b>וכענין הטבילה בנהר דינור. . לבטל את כח הזוכר</b>: ראה תו\"א מקץ לא, א. לב, ד. מג\"א צו, א. [ובהנסמן לעיל הערה ד\"ה: וכענין שר\"ז]."]]],[2000510454,"לע\"ל שיהי' ואת רוח הטומאה אעביר כו' לא יצטרך למקל כ\"א והניף ידו, ומ\"ש מטה עוזך פי' מטה הוא ל' ממשלה.\n<b></b>[פג)] ובזה יובן ג\"כ מה שבים נא' והחרים ובנהר והניף, ומדוע לא נאמר לשון חרם גם בנהר או ל' הנפה גם בים, והיינו כי ים שהוא מעלים אור האצי' שפועל התהוות בי\"ע יחרימו ה' לע\"ל מכל וכל, בכדי שיוכלו לבוא לגילוי אור האצי', שבכלל אבא מקננא באצי', אמנם זהו דרך מעבר הבינה בחי' השגה, לכן יניף ידו על הנהר לבטל את בחי' השגה זו בכדי לבוא לבחי' אוא\"ס שלמעלה מהשגה, ומ\"מ מפני שגם מה שעכשיו למעלה מהשגה ישיגו זה ע\"ד ברק המבריק דעכשיו, ולכן יניף על השגה דעכשיו ולא להחרים מכל וכל לגמרי. ויכהו לז' נחלים ז' בקעי' ובאמצע ישארו המים, להורות שמה שעד עכשיו הי' למעלה מהשגה יבוא לע\"ל בהשגה, אמנם ההשגה תהי' ע\"ד השגת החכ' ולא הבינה, ולכן לא יהי' הנהר ע\"ד רחובות הנהר וכציור נהר הנפסק<sup data-n=\"1518\">32</sup> לחלקים כו'. וזהו שא' במד\"ר הבל הבלים<sup data-n=\"1519\">33</sup> על ז' ימי בראשית, בשלישי יקוו המים ולע\"ל והחרים, והיינו כי ז' ימי בראשית הם הבל, פי' ששרשם מבחי' הבל שהם מילוי שם ס\"ג שעולה מספרו הבל, אמנם לע\"ל שיתעלו לבחי' ע\"ב שהוא בחי' אזרח שלמעלה מתהו ותיקון כמ\"ש בהגהו' לד\"ה ראה אנכי דתרך\"ב<sup data-n=\"1520\">34</sup>, ולכן והחרים כו'. ומה שיהי' מספר ז' נחלים לע\"ל הוא ע\"ד שאה\"כ והי' מספר בנ\"י אשר לא יספר וכענין שנת' בד\"ה ועמדו רגליו<sup data-n=\"1521\">35</sup> ובד\"ה ויצוום<sup data-n=\"1522\">36</sup> שיש בחי' אותיות אשר אם היו באים לגילוי הי' נעשה מהם מספר רב כו', אמנם הנה הם עדיין קודם התגלותם בבחי' בלי מספר, ושרש ענין מספר ז' כי קרי\"ס הי' לי\"ב קרעים נגד י\"ב בקר, להיות כי ע\"י הים עלו שבטי ישראל מבחי' י\"ב בקר דבריאה לבחי' י\"ב גבולי אלכסון דז\"א, אמנם לע\"ל ע\"י הנפת הנהר יתבקע העלם דאימא שהיא אם הבנים ז' מדות, ויבואו לשרשן ז' תחתונות דעתיקא והוא מה שז\"א בעתיקא אחיד ותליא. ואיך יהי' הגילוי אם שיתגלה ז' תחתונות דע\"ק בז\"א או ז\"א יתעלה בע\"ק, זהו הפלוגתא בין הת\"י לרש\"י, וכפלוגתא של הזהר עם האריז\"ל. ופי' והדריך בנעלים, פי' שנש\"י יצטרכו לנעלים ע\"ד שעכשיו יש בחי' מלאכים שנק' בשם נעל דשכינתא, ע' בלק\"ת בד\"ה מה יפו פעמיך<sup data-n=\"1523\">37</sup>, כן לע\"ל כשיתעלו ישראל כ\"כ ידריכו בנעלים, פי' שההילוך שלהם יהי' ע\"י נעלים המסתירים עוצם מעלת נש\"י בכדי שיוכלו הנבראי' שלמטה מהם לקבל מהם, וכענין עתידים צדיקי' שיאמרו לפניהם קדוש ונודע כי קדוש אומרים השרפי' דבריאה שמתהוים ע\"י נעל דשכינתא דאצי', כן יהי' לע\"ל בישראל. וביאור הענין בכלליות דג' בחי' אדם הם ג' עולמות בי\"ע, ובזהר הרקיע כ' שיש כדוגמת עתיק לעילא מגלגלתא דא\"ק, שזהו אצי'",[["1518","32","<b>וכציור נהר הנפסק</b>: אוצ\"ל: אלא כציור נהר הנפסק."],["1519","33","<b>הבל הבלים</b>: הוא רישומי דברים בקצרה להמשך והחרים תרל\"א ושייך להמאמרים: ד\"ה והחרים, ד\"ה אם בחוקותי, ד\"ה ויאמר גו' מחר חודש, וסד\"ה וביום הביכורים.\nב' פיסקאות הראשונות נת' בארוכה לעיל ד\"ה והחרים ע' רנט ואילך. וראה ד\"ה והחרים באוה\"ת נ\"ך (כרך א) ע' קצא-ב."],["1520","34","<b>בהגהות לד\"ה ראה אנכי דתרכ\"ב</b>: אוה\"ת ראה ע' תרלו. וראה גם סה\"מ תרכ\"ו ע' רח."],["1521","35","<b>שנת' בד\"ה ועמדו רגליו</b>: מאמרי אדה\"ז תקע\"א ע' נז ואילך. נביאים ע' רנח ואילך. ד\"ה זה בסה\"מ תר\"ל ס\"ע שכא ואילך."],["1522","36","<b>ובד\"ה ויצוום</b>: סה\"מ תרכ\"ז ס\"ע ק ואילך."],["1523","37","<b>בלק\"ת בד\"ה מה יפו פעמיך</b>: שה\"ש מג, ג ואילך. וראה גם לקו\"ת חוקת סד, ב. שה\"ש כה, א."]]],[2000510455,"דכלליות, ומאחר שנופל שם אצי' שייך שם ענין ים ונהר, ולע\"ל יחרים הים ויניף הנהר ובנ\"י יתעלו במדריגה עליונה כזו, ולכן ידריכו בנעלים ועי\"ז יהי' מסילה לשאר עמו. ועפ\"ז יובן דקדוק רש\"י שפי' ע\"פ והי' ביום ההוא יוסיף וגו' מאשור ומפתרוס שאינו כ\"א ז' גליות, והיינו שע\"י הבירור דז' גליות ז' מדות הרעות שורש ע' לשון בזה\"ג, עי\"ז נזכה להגילוי העצום דלע\"ל בבחי' ז' נחלים כו'."],[2000510456,"<h3>הבל הבלים</h3>\n<b></b><b>[רישומי דברים להמשך והחרים]</b>\n[לד\"ה והחרים]\nהבל הבלי' בשלישי יקוו המים והחרים, והחרים ל' יובש ול' חרם, והיינו שנחרב מהנודר. לז' נחלים ת\"י נחלין ורש\"י גזרים, והמכלול מקום אשר נגרים המים יקרא נחל, וי\"ל דפליגי בפי' הזהר וכהאריז\"ל בענין קי\"ס<sup data-n=\"1524\">1</sup> או מלמטלמ\"ע או מלמעלמ\"ט, וזהו נחל מלמעלמ\"ט שיתגלה העליון כמוצא הנחל, וגזרי' מלמטלמ\"ע בכדי שיתעלה התחתון, וכמו פלוגתם בקרי\"ס כן פליגי הת\"י ורש\"י בבקיעת הנהר דלע\"ל.\n<b>ולהבין</b> זה צ\"ל ענין קרי\"ס שהי' ביצ\"מ למה הי' צריכים, והלא באותו צד עלו. וצל\"ת שורש ענין יצ\"מ, מצרי' ל' מיצר וגבול, וכמו שהי' בשעבוד בסבלות ודחקות והנוגשי' אצים, כן ברוחניות בנה\"א מחמת דוחק והסתר הגוף והדוחק שצריך לכ\"ד ובלא זה נדמה לו שלא יוכל לחיות, וכל התאוות הם מצד הפעולה הגשמי' ששופט במיצר שכלו והבנתו שטוב לו, או יקרא שתאוות לבו גדלה מהשגת שכלו, אמנם כל זה הוא ממיצר הגוף שהגם שמתבונן מ\"מ אינו פועל כלל שיתגלה בנפשו במדות שבלב. וענין יצ\"מ הוא לצאת ממיצר הגוף כמו שיצאו ממצרים בפו\"מ משעבוד לגאולה, והוא ג\"כ ענין עיבור ולידה שהגלות נק' בחי' עיבור והגאולה לידה כו', ולא די בזה שיצאו ממיצר זה שהרי עדיין המוחין אינם מאירים מחמת מיצר הגרון, ורק בגשמיות לבד נגאלו, לזה הי' צריך להיות קרי\"ס לקרוע המסך כו' כי י\"ם הוא בחי' סוכ\"ד שבו מסתיים כל ההמשכות.",[["1524","1","<b>דפליגי בפי' הזהר וכהאריז\"ל בענין קי\"ס</b>: ראה סידור עם דא\"ח רפט, ד ואילך. מאמרי אדה\"ז על פרשיות ח\"א ע' רנח ואילך. מאמרי אדהאמ\"צ ויקרא ח\"א ע' ריב ואילך. רנ ואילך. שער האמונה לאדהאמ\"צ פנ\"ד (פו, ב ואילך). ובכ\"מ."]]],[2000510457,"<b>וביאור</b> הענין כתי' פלג אלקי'<sup data-n=\"1525\">2</sup>, אלקים מי אל\"ה, ב' הפכי', וע\"י גילוי מי בבחי' אלה עי\"ז נעשה מלא מים, הפך ים ליבשה, עלדאתכ\"ס וכל מה שיש ביבשה יש בים.\n<b>וז\"ע</b> פקדת הארץ<sup data-n=\"1526\">3</sup> ותשוקקיה, ארץ נש\"י ופקידת הארץ זהו ע'י מים שאז תוציא צמחה אהבה מוסתרת שתצא לגילוי. וזהו שורש ענין קרי\"ס שיתגלה בחי' עלדאתכ\"ס בעדאת\"ג, ובזה פליגי, דלדעת כתהאריז\"ל נתגלה האצי' בבריאה, ולפי' הזהר נתעלה בי\"ע באצי'.\n<b>וכך</b> יובן לע\"ל<sup data-n=\"1527\">4</sup> דכתי' והחרים את לשון ים מצרים, פי' לשון ים מצרים למה כינה הים למצרים להיות כי כל המצרים וגבולים שורש התהוותם הוא מהים, שמסיום האתכסיא נעשה אתגלי', ונמצא כי מצרים הם כל מה שנברא בשי\"ב. ולכן מפרש המד\"ר הבל דקהלת שז\"ע והחרים, והיינו כי נהר נילוס הוא מד' נהרות דמשם יפרד, שהוא שורש הפירוד. ולע\"ל (כשיהי' וחד חרוב) יתבטלו כל שורש ענין הפירוד. וזהו והחרים ל' חרם כענין קדש להוי', קדש מילה בגרמי', ראשית הע\"ס, מקור דמקור לע\"מ, ואז והניף כו' על הנהר הוא בחי' צמצום השכל דהבנה, והכהו לז' נחלים ז\"ת דע\"י, אך גם בזה יש ב\"ד אם מלמטלמ\"ע או מלמעלמ\"ט, ולפי' רש\"י יתעלו ז\"ת דאצי' בז\"ת דע\"י, ולפי' הת\"י יהי' ז' נחלין ז' נחלים פי' גילוי' מז\"ת דע\"י לז\"ת דאצי', וכמו כל ענין דלע\"ל שיהי' הגילוי למטה כמו למעלה וזהו ביום ההוא יהי', ונמצא מובן מה שה\"צ להחרי' תחלה לשון הים.\n<b>והניף</b> כו' על הנהר. . צמצום השכל דהבנה: בצידי הגליון נרשם בגוכי\"ק: קרי\"ס בכדי להיות מ\"ת, מ\"ט פנים טהור ומ\"ט פנים טמא, צ\"ל קרי\"ס סודכ\"ד, וכמו\"כ לע\"ל בכדי להיות גילוי טל תורה זהו ע\"י הכאת הנהר בינה השגה דעכשיו, כענין ר\"ז צם מאה תעניתא, כל רב מבבל, סמוכים הארת משה, וכענין הטבילה בנהר דינור.",[["1525","2","<b>וביאור הענין כתי' פלג אלקי'</b>: הבא לקמן נמצא תוכנו בארוכה לעיל המשך והחרים ד\"ה אם בחוקותי ע' שלד."],["1526","3","<b>וז\"ע פקדת הארץ ותשוקקי'</b>: בהבא לקמן ראה בארוכה לעיל המשך והחרים סד\"ה ויאמר גו' מחר חודש ע' שמב."],["1527","4","<b>וכך יובן לע\"ל</b>: בהבא לקמן עד סיום הרשימה ראה בארוכה לעיל בסיום המשך והחרים סד\"ה וביום הביכורים ע' שסב ואילך."]]],[2000510458,"<h3>אחור וקדם צרתני</h3>\n<b></b><b>[רישומי דברים מד\"ה הים ראה וינוס]</b>\n[לד\"ה הים ראה]\nאחור וקדם צרתני<sup data-n=\"1528\">1</sup>, זכה אדם כל העולם כולו לא נברא אלא לצוות לזה<sup data-n=\"1529\">2</sup>, גם כדי שימצא הכל מוכן, לא זכה אומרים לו אפי' יתוש קדמך, פי' קדמך לבד הקדימה במה שנוצרה תחלה, ולבד מה שהיא לא חטא, גם שרשה הוא מבחי' התהו שקדם לתיקון. אמנם הנה כ\"ז הוא כשהאדם לא זכה, אבל כשזכה הגם כי תהו קדם לתיקון, אמנם הנה נודע כי תהו הוא בחי' סותר ע\"מ לבנות, וכשאדם דתיקון מתקן חלקו בבחי' התהו אז כל העולם לא נברא אלא לצוות לזה, להיות כי כל העולם גוף גדול הוא בשבילו עולם קטן, וגם תהו בכלל, וכל התיקון הוא בשביל לתקן התהו א\"כ אחר הבירור הרי התיקון גדול, להיות כי יורש גם אורות דתהו, וזהו בבטן עקב את אחיו בחי' התהו שקדם לתיקון.\n<b>ויובן</b> ביאור הענין מקרבנות<sup data-n=\"1530\">3</sup>, שלכאורה אדם חטא מביאין בהמה לכפר עליו, מדבר חי. אך הענין דשורש הבהמה הוא מפני שור, וע\"י העלאת הבהמה מעלי' חיות הנושאי' את הכסא עם האדם שעל הכסא לבחי' כי לא אדם הוא, ומ\"מ צריך אדם להביא את הבהמה ולהקדישה, וע\"י הקידוש ממשיך או\"מ<sup data-n=\"1531\">4</sup> עלי', ולסמוך, ואח\"כ יוכל הכהן להעלותה.\n<b>וכמו\"כ</b> יובן בעבודה שבלב אין אדם כו' אא\"כ נכנס בו רוח שטות המכסה על האמת כמו שמכסה על השכל, עושה שטותי', לכן צריך קרבן, והקרבן מכם הוא בחי' נה\"ב ששרשה ג\"כ מבחי' התהו, וצריך להקדישה תחילה זהו בחי' סידור שבחו של מקום[ednref_73_טז], וסיפור ביטול המלאכים, ובכלליות השנה זהו ספה\"ע, ובד\"פ בכ\"י ברכות ק\"ש, ובכלל סולם זה צלותא, דא כבש המבח, שמעלים עלי' נה\"ב זובח את יצרו, וע\"י העלאת נה\"ב מתעלה הנה\"א ביתר שאת, וכמשל הרוכב על הבהמה שיוכל להעלותו למקום שבעצמו א\"י לעלות, וגם בכל היום צ\"ל בבחי' אתכפיא מכל רצונות זרות, וה\"ז מס\"נ כי מה לי קטלא כולא או קטלא פלגא כו'.",[["1528","1","<b>אחור וקדם צרתני</b>: הוא רישומי דברים בקצרה מהמשך והחרים ד\"ה הים ראה וינוס לעיל ע' רעז ואילך."],["1529","2","<b>אחור וקדם צרתני. . אלא לצוות לזה</b>: בהבא לקמן ראה תו\"א בראשית ג, ד ואילך. מאמרי אדה\"ז תקס\"ז ע' רפט ואילך. סה\"מ תרל\"ג ח\"א ע' רעא ואילך. ח\"ב ע' שצד ואילך. ועוד."],["1530","3","<b>ויובן ביאור הענין מקרבנות</b>: בהבא לקמן ראה גם לקו\"ת נשא כח, ב ואילך. סה\"מ תרכ\"ז ע' קלד ואילך. וש\"נ. תרכ\"ט ע' סט ואילך. וש\"נ."],["1531","4","<b>וע\"י הקידוש ממשיך או\"מ</b>: ראה לקו\"ת מטות פב, סע\"ב. פג, ב. מאמרי אדה\"ז תקס\"ז שם ס\"ע רצא-ב.\n\n[edn_73_טז] <b>וצריך להקדישה תחילה זהו בחי' סידור שבחו של מקום</b>: בצידי הגליון נרשם בגוכי\"ק: ועוי\"ל ההקדשה הוא קבלת מצות ואהבת לריעך כי תהו ותיקון ריעי' הם."]]],[2000510459,"<b>וזהו</b> הים ראה וינוס ארונו של יוסף<sup data-n=\"1532\">5</sup> שפטפט ביצרו ועמד בנסיון אשת פוטיפר וע\"י נטירת הברית זכה למלוך, וכשראה הים וינס מפניו להיות כי זבח את יצרו שזהו תכלית המכוון מבריאת יש מאין, לכן הים אם כי נברא בשלישי, מ\"מ יוסף זכה והרי כל העולם לא נברא אלא לצוות לזה. והנה כתי' אלה תולדות יעקב יוסף שיוסף הוא בחי' תולדות גילוי דיעקב<sup data-n=\"1533\">6</sup>, ואיתא משה מלגו ויעקב מלבר א\"כ משה גבוה יותר מבחי' יוסף, והיינו כי ים בחי' מל' י\"ס סודכ\"ד, ויוסף יסוד ז\"א, ולכן כשהים ראה ארונו שהוא ג\"כ יסוד כנודע מענין ארון הברית, נס מפניו ע\"ד הכלה הופכת פני', אמנם בכדי להיות הבריאה זהו ע\"י בחי' רוח קדים מבחי' קדמונו ש\"ע זהו ע\"י משה ואתה הרם את מטך שזהו ע\"י הרמת היד הגבהת ידיו של משה למעלה מהראש הוא בחי' מוחין ע\"ד כש\"ב השי\"ן חג\"ת קודם לבי\"ת חו\"ב<sup data-n=\"1534\">7</sup>, והיינו בכדי להגיע לבחי' כ\"ף בחי' כתר ע\"ד שאו ידיכם קדש, ומשם נמשך להיות ויט ידו כו' ועי\"ז ויולך ה' ברוח קדים, ונבקע הים לי\"ב גזרים לפי הת\"י להיות ששם עלו שבטים שבטי י\"ה י\"ב ג\"א דז\"א, מי\"ב בקר כו', וזהו בוקע ים לפני משה גם משה מלגאו מ\"מ שורש הבקיעה הוא לפני משה, וגם מתורץ שהגם שהים ראה ארונו ולזה נס, ומ\"מ צריך להיות ואתה הרם, בוקע ים לפני משה, ולפי' רש\"י שנחלקו כל המימות זהו לפרסומי מילתא.",[["1532","5","<b>וזהו הים ראה וינוס ארונו של יוסף</b>: בהבא לקמן ראה יהל אור לתהלים ע' תמא ואילך. אוה\"ת ויקהל ע' ב'רכ."],["1533","6","<b>והנה כתי' אלה תולדות יעקב יוסף שיוסף. . גילוי דיעקב</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרעז ואילך. תרפד ואילך. אוה\"ת ויחי שפה, ב ואילך. שפח, א ואילך. שצה, א ואילך. תד, ב ואילך. שם (כרך ו) תתשמז, ב ואילך. וראה לעיל ע' רפה. וש\"נ."],["1534","7","<b>כש\"ב השי\"ן חג\"ת קודם לבי\"ת חו\"ב</b>: ראה בארוכה לקו\"ת אמור לז, ב. לח, סע\"ד ואילך. ועוד."]]],[2000510460,"<h3>ולהבין כו' ענין כל הנחלים</h3>\n<b></b><b>[רישומי דברים לד\"ה משכיל לאיתן האזרחי]</b>\n[לד\"ה משכיל לאיתן]\nולהבין בתוס' ביאור<sup data-n=\"1535\">1</sup> ענין כל הנחלים בענין והאיתנים, צ\"ל ענין רשב\"י, ששיבחו אותו מאד, בזהר בא מאן פני האדון ה' צבאות דא רשב\"י<sup data-n=\"1536\">2</sup>, דלכאורה האיך יאמרו על אדם נברא.\n<b>ויובן</b> בהקדם ענין לעולם יסדר שבחו ש\"מ<sup data-n=\"1537\">3</sup>, פי' וענין השבחים כענין הללוי' בהילו נרו, כטבע החסדן מתעורר ע\"י השבח, וכן ע\"י דבר חדש פונה לב המלך, כן",[["1535","1","<b>ולהבין בתוס' ביאור</b>: הוא רישומי דברים בקצרה מד\"ה משכיל לאיתן האזרחי שנדפס לעיל ע' שיח ואילך."],["1536","2","<b>בזהר מאן פני האדון ה' צבאות דא רשב\"י</b>: בזח\"ב לח, א הובא הפסוק (תשא לד, כג) יראה כל זכורך את פני האדון ה'\" (ועד\"ז במשפטים כג, יז), בלא תי' צבאות\". [ובישעי' י, לג: הנה האדון ה' צבאות\" הובא לעיל ע' שכב]. נת' במאמרי אדה\"ז תקס\"ד ע' קו. או\"ת ויחי שנח, ב. סה\"מ תרל\"ב ח\"א ע' לח. וש\"נ. וע' ר ואילך."],["1537","3","<b>ויובן בהקדם ענין. . שבחו ש\"מ [ של מקום]</b>: בהבא לקמן ראה הוספות לתו\"א ויחי קב, א. קג, ג ואילך. מאמרי אדה\"ז תקס\"ח ח\"א ע' שע ואילך. ח\"ב ע' תש ואילך. אוה\"ת חנוכה (כרך ה) תתקלה, א ואילך. דרמ\"צ קמח, א ואילך. ועוד."]]],[2000510461,"ע\"י השבחים מעוררי' העלאות החכמה לבחי' משכיל שיומשך מבחי' משכיל לשכל, שזה\"ע משכיל לאיתן האזרחי.\n<b>וביאור</b> הענין דהנה בורא קדושים ישתבח שמך<sup data-n=\"1538\">4</sup>, שגם החכ' היא בריאה יש מאין כמ\"ש והחכמה מאין, ע\"ד מציאה, בראשית ברא, בחי' ב' ראשית ח\"ע וח\"ת ברא אלקים דכתר, וכנ\"ל דיתבא על כורסי' דשביבין, לאכפי' להון י\"ל ע\"י הבירור דתהו שמתברר מבי\"ע, שא\"א כ\"א ע\"י ברה\"ע, שהיא ב' בחי' חכ', ולכן ישתבח שמך בעילוי אחר עילוי, וקדושים חכ' בכ\"י יהללוך סלה ע\"ד עליות עד אין קץ דג\"ע, צדיקים אין מנוחה כו', וכן קדושים כו', וכ\"ז הוא בבחי' שמך לפי שאין ערוך לך כלל, וההילול הוא רק לשמך, ובכדי שיומשך מבחי' שמך צריך להיות ממוצע.\n<b>וז\"ע</b> רשב\"י בדורו, ולכן ע\"י לימוד התורה פעל גשם כמ\"ש בזח\"ג<sup data-n=\"1539\">5</sup> אחרי דנ\"ט, כמו משה בדורו, שנה עליו פרק אחד, וזהו שביקש משה לכנוס לארץ ע\"ד מלמעלמ\"ט<sup data-n=\"1540\">6</sup>, כי הגם שכתו' ב\"פ לך ה' הגדולה ביטול בתפלה ה\"ע העלאת נחלי' ז\"א בחו\"ב, מ\"מ מי יעלה כו' שצ\"ל ע\"י התבוננות בינה בן י\"ה, שהוא כבד מאד, אך ע\"י התורה וכל בניך למודי הוי', א\"ת בניך אלא בוניך תורה, נק' ורב שלום לפי שמבררת גם טורי דפרודא, וגם לפי שע\"י התורה בנקל יותר והכל יכולים אפי' אם אינו מזוכך עדיין, כענין מ\"ת לגבי תחה\"מ, ולכן רצה משה שיהי' כן בכ\"י ע\"ד שנה עליו פרק א' ועי\"ז יומשך גשמיות ג\"כ, אך לא פעל כ\"א ביח\"ס תורתן אומנתן רשב\"י, ולכן הוא הי' הממוצע.\n<b>וענין</b> השבח לעורר שיומשך מבחי' משכיל לבחי' איתן, להיותו הממוצע, ובו יש ב' בחי' זנב לאריות ארי' דכתר ארי' שאג, וראש לשועלים השפעה לתלמידים, ובכדי שיומשך ממשכיל לאיתן זהו ע\"י השבח, וכענין הללוי' שיומשך מבחי' כתר בבחי' העליונה דממוצע.\n<b>ולכן</b> מאן פני האדון, רשב\"י, כי כשם שה' צבאות ש' שמאיר בבריאה, כן רשב\"י האיר לתלמידים בדורו, כמ\"ש בזהר ואי לעידן דתסתלק חשכת עלמא. וענין ל\"ג בעומר הוד שבהוד<sup data-n=\"1541\">7</sup> ע\"ד האופן בתוך האופן, בחי' הודאה שזהו לעצמותו",[["1538","4","<b>וביאור הענין דהנה בורא קדושים ישתבח שמך</b>: בהבא לקמן בפיסקא זו ראה בארוכה לקו\"ת בהר מא, ב ואילך."],["1539","5","<b>וז\"ע רשב\"י. . ע\"י לימוד התורה פעל גשם כמ\"ש בזח\"ג</b>: נת' בארוכה בסה\"מ תרכ\"ז ע' רצא ואילך. וש\"נ."],["1540","6","<b>וזהו שביקש משה לכנוס לארץ ע\"ד מלמעלמ\"ט</b>: ראה בארוכה לקו\"ת ואתחנן ב, סע\"ג ואילך. ג, ג ואילך. סה\"מ תרל\"ג ח\"ב ע' תכג. [ובהנסמן שם בתחילת המאמר]."],["1541","7","<b>וענין ל\"ג בעומר הוד שבהוד</b>: ראה בכ\"ז בארוכה סידור עם דא\"ח דש, א ואילך. שו, ג ואילך. אוה\"ת ויקרא (כרך ד) ע' א'קיט. ועוד."]]],[2000510462,"שלמעלה מבחי' שמך הנ\"ל, ולכן אז נסתלק רשב\"י כי הוא הי' הממוצע, ובהסתלקו האיר שורש דשורש נשמתו בחי' שמך ולכן זהו בהוד להיותו מודה לעצמותו, ע\"ד נהורא תתאה קארי תדיר.\n<b>וזהו</b> כל הנחלים הוא כל התנאים שקיבלו ע\"י הממוצע דרשב\"י, והאיתנים מוסדי ארץ, ורשב\"י הוא משכיל לאיתן, וענין האזרחי כמו בקרי\"ס הי' גילוי עדאת\"כ כן רשב\"י נוני ימא ע' בלק\"ת שמיני ד\"ה לויתן כו' בכתב שנדפס משם<sup data-n=\"1542\">8</sup>, ע\"ד משה כי מן המים משיתהו, וזהו האזרחי מה שעתיד לזרוח, כי משה ג\"ר וגו\"א<sup data-n=\"1543\">9</sup>, ולכן מה שהאזרחי זהו עכשיו משכיל לאיתן רשב\"י בעלייתו בהוד שבהוד.",[["1542","8","<b>ע' בלק\"ת שמיני ד\"ה לויתן כו' בכתב שנדפס משם</b>: בלקו\"ת שמיני יח, א: כי יש ב' מיני צדיקים, הא' אותן שעבודתם ברוחניות פי' בכוונת הלב לייחד יחודים עליונים ובבחי' עליות, וכגון רשב\"י כשהי' במערה י\"ג שנה כו' וכן האריז\"ל הי' ג\"כ בבחי' זו. ובהגהות כ\"ק אדמו\"ר מהורש\"ב ללקו\"ת מעיר שב לקו\"ת כי\"ק\" נוסף: וכן הבעש\"ט\". ובנו\"א בס' מאמרי אדה\"ז תקע\"א ע' קסד: ומהם הי' האריז\"ל בדורו (פי' שהי' בו גם מבחי' זו, ולא זו בלבד) והבעש\"ט ז\"ל בדורו\". ובנו\"ב בס' מאמרי אדה\"ז על מארז\"ל ע' קמד: (וכמו האריז\"ל וחביריו בדורו, והבעש\"ט ז\"ל וחביריו בדורו, וכך בכל דור ודור)\". הובא בסה\"מ תשי\"א-י\"ג ע' 75."],["1543","9","<b>משה ג\"ר וגו\"א</b>: גואל ראשון וגואל אחרון."]]],[2000510463,"<h3>והנה כמו כו' המשכת החכ' הנק' איתן</h3>\n<b></b><b>[רישומי דברים לד\"ה אם בחוקותי]</b>\n[לד\"ה אם בחוקותי[\nוהנה כמו<sup data-n=\"1544\">1</sup> שכדי שיומשך המשכת החכ' הנק' איתן (שהוא כמשמעו קשה בחי' מ\"ה דחכ' כדפרי' בפרד\"ס להיותו טרוד למיבלע לא פליט) למדות בחי' איתנים זהו ע\"י ממוצע דרשב\"י, כן בכדי שיתהוה אצי' מהמאציל זהו ע\"י ממוצע, והוא בחי' כתר.\n<b>והענין</b> אצי' ל' הפרשת הארה, ויאצל<sup data-n=\"1545\">2</sup>, כמדליק נר לא חסר, כן אצי' גילוי הארה, ומהיות כי נק' ש' חכמ' אינו סבין, מוגבל<sup data-n=\"1546\">3</sup>, לכן אין ערוך לך, ויותר אין ערוך כמו עשי' גבי אצי', וזהו בורא קדושי', וקדושי' עליות בכ\"י עד אין קץ, וכ\"ז בבחי' שמות א\"ת שמות, ז' שמות שאין נמחקין, וראשיתן ה' בחכ' כתי' בראשית ב' ראשית ברא אלקי' דכתר, שהרי נק' ארי' שאג דיבור אנכי ה' אלקיך וה\"ז יש מאין",[["1544","1","<b>והנה כמו. . המשכת החכ'</b>: הוא רישומי דברים בקצרה מד\"ה אם בחוקתי תלכו הנדפס לעיל ע' שכו ואילך."],["1545","2","<b>אצי' ל' הפרשת הארה ויאצל</b>: ראה תו\"א בראשית ג, א. וירא יד, א. מאמרי אדה\"ז תקס\"ג ח\"א ע' רצב. אוה\"ת ואתחנן ע' קפו ואילך. לעיל ע' קלח. וש\"נ."],["1546","3","<b>סבין מוגבל</b>: תיבות אלו אינן ברורות כ\"כ בגוכי\"ק."]]],[2000510464,"שאין ערוך לכן זה ע\"י ממוצע דכתר, ב' בחי' ע\"י וא\"א, ע\"י המתנשא, המעתיק הרי', המעתיק מספר, וא\"א ראשית הנאצלים ב' בחי' שבממוצע, ים וארץ, ים המעלים, וזהו עד שלנבה\"ע האצי' כמ\"ש בעה\"ק<sup data-n=\"1547\">4</sup>, הי' הוא ושמו כתר, אין דיש דחכ', אך באמת עוד גבוה יותר אצי' אדם דעשי', וכתר יצי', א\"ק בריאה, ובין בריאה לאצי' דכלליות הוא כדוגמת עתיק שנת' בזהר\"ק, וכמו מל' דאצי' דפרטי ממוצע, כן בכלליות כו'.\n<b>ובד\"כ</b> הממוצע בחי' מל' דא\"ס ויש בו ב' בחי' ים וארץ<sup data-n=\"1548\">5</sup>, כי הק\"ו זהו ממכ\"ע, והצמצום הוא להעלים את אצי' דכלליות וזהו ענין ים סודכ\"ד מעלים בחי' יש האמיתי, ונמצא כי גם לפני הצמצום יש ים וארץ, היינו מקור המעלי' ומקור המגלה, ש' הוי' ש' העצם, שמו בלבד ג\"כ הוי', וכתי' לה' הנראה, וכתי' להוי' המסתיר ב' בחי' ים וארץ, והיינו כי כל ענין א\"ק דלכאו' ש' זה הוא ב' הפכי'<sup data-n=\"1549\">6</sup>, אדם הרי זה נברא, וקדמון היותו קדום, ואיך הוא, צ\"ל ענין מח' ודבור, דבור גילוי לזולתו מח' לגבי עצמו, וכשעלה ברצונו, הנה הרצון הוא התהוות, אך ענין גילוי הרצון שהוא בחי' מח' היותה מגלה העלם העצמי לגבי עצמו זו א\"ק, מילה מורכבת פי' היותו אדם לפי שזהו מקור שיומשך אח\"כ מזה גם אדם דעשי', ומ\"מ ה\"ז קדמון כי הן אמת שהמח' ה\"ה נברא אמנם כ\"ז באדם אבל אצלו ית' כשם שהוא קדום כן מח' קדומה ולכן בחי' ציור אדם דא\"ק להיותו גילוי העלם העצמי לגבי עצמו עדיין אין זה בגדר קריאת ש' אדם כ\"א אדם קדמון להורות על ידיעתו, ולכן להיות א\"ק זהו ע\"י צמצום, כי לגבי עצמו' כבריאה יחשב, ויש עדיין בחי' אצי' שבעצמו' כנ\"ל ע\"ד בריאה גילוי גבי עצמו כן יש אצי' שהוא שורש הפרשת הארה כו', וביניהם ממוצע, כמו בחי' מל' שבאצי' דפרטי, וכמו\"כ יש מה ששיער עצמו בכח, יש שם ג\"כ כל בחי' אלו. ונמצא כי יש ים וארץ לפני הצמצום בפועל.\n<b>וזהו</b> פלג אלקים מלא מים, מי אלה ב' הפכי' אותי' אלקי' וע\"י גילוי מי באלה ע\"י נעשה מלא מים הוא בחי' ים בכ\"מ ואז נמשך אח\"כ גילוי הארץ ע\"י העלם, ונמצא כי ענין קרי\"ס הוא עד רום המעלות, וזהו ולכן קרי\"ס הי' ע\"י ג' פסוקי' ג' אבות, ויט יעקב<sup data-n=\"1550\">7</sup>, אויר קדמון בחי' רוח קדים, ועי'ז נמשך להיות פקדת ארץ ותשוקקי', נש\"י ארץ, קדמו לכ\"ד אפי' לתורה כמ\"ש בתד\"א, ולכן יעקב מקור יב\"ש<sup data-n=\"1551\">8</sup> אויר קדמון, הוא המעורר בשורש שרשם להיות גילוי מי דהעלם באלה דהעלם ולכן ע\"י פקידה זו מתמלאת תשוקת הארץ דוקא להיות כי הם המעוררים.",[["1547","4","<b>עד שלנבה\"ע [ שלא נברא העולם] האצי' כמ\"ש בעה\"ק</b>: ראה גם סה\"מ תרל\"ב ח\"א ע' כ. וש\"נ. תרמ\"ד (הוצאת תשס\"ג) ע' שמו. וש\"נ."],["1548","5","<b>ובד\"כ הממוצע. . מל' דא\"ס. . ב' בחי' ים וארץ</b>: בהבא לקמן ראה אוה\"ת בשלח ע' תקעב-ג. סה\"מ תרכ\"ח ע' קמא. תרל\"ב ח\"א ע' קלז."],["1549","6","<b>א\"ק דלכאו'. . ב' הפכי'</b>: בהבא לקמן ראה סה\"מ תרכ\"ח ע' צד ואילך. וע' קסו ואילך. תרל\"ג ח\"ב ע' תקט ואילך."],["1550","7","<b>קרי\"ס הי' ע\"י ג' פסוקי'. . ויט יעקב</b>: בכ\"ז ראה אוה\"ת בשלח ע' תקעה."],["1551","8","<b>יב\"ש</b>: י\"ב שבטים."]]],[2000510465,"<b>וזהו</b> אם בחוקותי תלכו אם תהיו עמלים בתורה כמארז\"ל נתאוה שיהי' עמלים, ע\"ד נתאוה דירה, ואז ונתתי גשמיכם גשם שמ\"ג אזה\"י<sup data-n=\"1552\">9</sup> ושורש הגשמיות קדי' סוב\"ת גם אם אין גשמים אין אדם ישראל שקדמו כמ\"ש בתד\"א ואז ונתתי גשמיכם כו' פריו ועצו שוין, הגשמי' הוא משרש שרש הקדום ומה קרי\"ס הקדמה למ\"ת כ\"ש ע\"י התורה.",[["1552","9","<b>וזהו אם בחוקותי. . אזה\"י [ אור ז' הימים]</b>: ראה בכ\"ז אוה\"ת ויקרא (כרך ב) ע' קצה-ו. סה\"מ תרכ\"ו ע' ק-קא. תר\"ל ע' קמה-ו. קנג-ד."]]],[2000510466,"<h3>וביאור ענין פקדת הארץ</h3>\n<b></b><b>[רישומי דברים לד\"ה ויאמר גו' מחר חודש]</b>\n[לד\"ה ויאמר גו' מחר חודש]\nוביאור ענין פקדת ארץ<sup data-n=\"1553\">1</sup>, צ\"ל מ\"ש מחר חדש ונפקדת, תענית ד\"ח ע\"ב נא' פקידה באשה ופקידה בארץ, ועד\"ז יפקד מושביך, מושב דוד מל', ולכאו' פקידה דאשה וגשמי' אינם שוים. בני חיי מזונא במזלא תליא, פקידת הארץ, נהר פלגיו ישמחו עיר אלקי', נהר בינה, פלגיו ז' מדות, גם הלא נת' ענין כל הנחלים ז' מדות הולכים, ומהו ענין ישמחו, הנה הגם כי בנין המל' בר\"ה מ\"מ בכל חדש מקבלת הארה, יחוד שמשא, זה הוי' קוינו החדש הזה יב\"צ<sup data-n=\"1554\">2</sup> ונודע כי בחכ' בכדי להיות המשכה מחכ' צ\"ל השורש מלמעלה מהחכ' כן בכדי להיות יחוד שו\"ס צ\"ל שרש ההמשכה מבחי' ע\"ק, ומה גם כי שורש דז\"א בעת\"י<sup data-n=\"1555\">3</sup>, ולכאורה הלא בינה אם הבני', אך שניהם אמת לידת המדות מבינה ומ\"מ שורש ז\"א בעת\"י, וכמו\"כ במל' בנין המל' מבחי' מל' דע\"ס כל הנחלים, ויחוד המל' זהו מלמעלה מסדר השתשלות ומ\"מ נמשך דרך חו\"ב ז\"א, וזהו נהר פלגיו.\n<b>וביאור</b> הענין הנה לידת המדות<sup data-n=\"1556\">4</sup> אהוי\"ר ע\"י התבוננות שמע ואהבת, ציווי והבטחה<sup data-n=\"1557\">5</sup>, והוא על התבוננות ואזי מוליד אהוי\"ר, וגם סופך, בד\"ה וירא ישראל<sup data-n=\"1558\">6</sup>, וכמו שבכנ\"י דלתתא כן בכנס\"י דלעילא כו' היחוד ע\"י י\"ב ג\"א דז\"א נמשך בכל חודש המשכה חדשה, ושורש ההמשכה מע\"ק, ולכן בר\"ה נפקדה שרה וחנה, כי אז זמן המל' והבנין בשביל היחוד, וכמו באדה\"ר ויקח, ויבן, כן בבחי' מל'. ומפני",[["1553","1","<b>וביאור ענין פקדת ארץ</b>: הוא רישומי דברים בקצרה מד\"ה ויאמר גו' מחר חודש שבהמשך והחרים תרל\"א שנדפס לעיל ע' שלו ואילך."],["1554","2","<b>הוי'. . יב\"צ [ י\"ב צירופים]</b>: ראה לעיל ע' שלח. וש\"נ."],["1555","3","<b>שורש דז\"א בעת\"י</b>: ראה בארוכה תו\"א יתרו עג, א. לקו\"ת שמיני יט, ב. חוקת נח, ב. מאמרי אדה\"ז תקס\"ז ע' שסד. תקס\"ח ח\"א ע' א. וע' ד ואילך. ענינים ע' תיח ואילך. סה\"מ תרל\"ב ח\"א ע' יז. [ובהנסמן שם בתחילת המאמר]. ועוד."],["1556","4","<b>וביאור הענין הנה לידת המדות</b>: בהבא לקמן ראה סה\"מ תר\"ל ע' קכא-ב. תרל\"ב ח\"א קלט-מ."],["1557","5","<b>שמע ואהבת, ציווי והבטחה</b>: ראה תו\"א תשא פו, ג. סה\"מ תרל\"ב ח\"א ע' צה. המשך וככה תרל\"ז ע' קעג ואילך. ועוד."],["1558","6","<b>בד\"ה וירא ישראל</b>: ראה ד\"ה זה בסה\"מ תרכ\"ז ע' רמז ואילך. [וש\"נ]."]]],[2000510467,"שבר\"ה הבנין לכן אז הפקידה, וה' פקד הוא וב\"ד, להעלות לבחי' מזלא, ומשם יופסק הדבר, ומ\"מ צ\"ל זכות דאל\"כ אין מעלי', וכן יובן בענין הגשם, כשחפץ לשלוח ברכתו אזי שותה ממ\"ע, גשם שמ\"ג ז' פעמים אור ז' הימים, אך זהו ע\"י ואיד יעלה בחי' אתעדל\"ת אם בחוקתי תלכו, שתהיו עמלים בתורה, ועי\"ז נמשך פקדת ארץ, נש\"י להיות תשוקתה לבוא לשורשה לך לך, לכי לך.\n<b>וזהו</b> ויאמר יהונתן יה\"ו נתן אל דוד ה' אחרונה<sup data-n=\"1559\">7</sup>, ש' הוי', מחר חדש יהי' יחוד דשו\"ס, ואז ונפקדת ע\"ד פקידת האשה ופקדת ארץ, ע\"י המשכה ושלשת לבוא לבחי' סגולתא<sup data-n=\"1560\">8</sup>, בחי' קהק\"ד כח\"ב סגולתא ג' ראשי ראשים וכמו סגולה למעלה מן הטעם כן לבוא לבחי' מלמעלה מהשתלשלות, היינו להיות התשוקה לבחי' א\"ס ועמך לא חפצתי יה\"ו נתן ת\"ק ה' בריבוע, דוד הוא ג\"כ ה' מל', י\"ל ב' בחי' מל' ים וארץ, ויאמר לו יהונתן הוא כמו קרי\"ס הפך ים ליבשה, דוד יבשה האזין וקיבל דברי יהונתן חודש י\"ב ג\"א דז\"א ועי\"ז ונפקדת כענין זכרונות ותוליד. ושלשת לבוא לבחי' סגולתא וזהו עד דוד הגדיל ולכן המטה משה הי' ביד דוד ועתיד להיות עוד אצל מה\"מ מב\"ד<sup data-n=\"1561\">9</sup> דוקא מטה עוזך כו'.",[["1559","7","<b>יה\"ו נתן אל דוד ה' אחרונה</b>: ראה מאמרי אדה\"ז תקס\"ז ע' נה. תקס\"ח ח\"א ע' תקלד. נביאים ע' יג. אוה\"ת בראשית יא, א. ברכה ע' א'תתצב."],["1560","8","<b>ושלשת לבוא לבחי' סגולתא</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ז שם ע' סב ואילך. מאמרי אדהאמ\"צ במדבר ח\"א ע' קנב ואילך. אוה\"ת בראשית שם יב, סע\"א ואילך."],["1561","9","<b>מה\"מ מב\"ד</b>: מלך המשיח משיח בן דוד."]]],[2000510468,"<h3>עדות ביהוסיף</h3>\n<b></b><b>[רישומי דברים לד\"ה כמראה הקשת]</b>\n[לד\"ה כמראה הקשת]\nעדות ביהוסף<sup data-n=\"1562\">1</sup>, ה' נוסף<sup data-n=\"1563\">2</sup>, ומזה ידע ע' לשון במאו\"א יו\"ד מ\"ב, ע' בביאור מה יפו דתקס\"ג<sup data-n=\"1564\">3</sup> שזהו הכח לע' שרים שינקו מיסוד דקדושה, והיינו כי המברר בהכרח שיתלבש בלבוש המתברר, ולכן במצרי' דוקא ניתוסף. והענין בר\"ה יצא יוסף<sup data-n=\"1565\">4</sup>, כי ענין הגלות שק\"נ מכסה על היסוד, לכן הוא בבית האסורים כלא, ובר\"ה פקידת עקרות להיות כלה כלתה נפשי היפך כלא, ולכן יצא יוסף יסוד ז\"א ועי\"ז",[["1562","1","<b>עדות ביהוסף</b>: הוא רישומי דברים בקצרה מד\"ה כמראה הקשת שבהמשך והחרים תרל\"א הנדפס לעיל ע' שדמ ואילך."],["1563","2","<b>עדות ביהוסף, ה' נוסף</b>: ראה בכ\"ז יהל אור לתהלים ע' רפה-ו. אוה\"ת בראשית יז, א. לך לך (כרך ד) תשכד, א."],["1564","3","<b>ע' בביאור מה יפו דתקס\"ג</b>: מאמרי אדה\"ז תקס\"ג ח\"א ע' רנא. ונו\"א שם ע' רסו. ובארוכה מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' צו. אוה\"ת שה\"ש (כרך ג) ע' תתקעו."],["1565","4","<b>והענין בר\"ה יצא יוסף</b>: בכ\"ז ראה גם אוה\"ת וארא ע' קפט. רלט."]]],[2000510469,"ניתוסף ה' בעטרה שעטרה לו אמו. וביאור הענין כי סגולה מכל העמי' ע\"ש, זמ\"ק<sup data-n=\"1566\">5</sup> מדעת עד יסוד, כי מל' אתבטלת ולא שבירה, שעמד בנסיון נתחבר בשכינתי' כמ\"ש בזח\"ג דרי\"ג ב'.\n<b>וכן</b> יהונתן ודוד חיבור ו\"ה עי\"ז ה' עילאה, ביום חתונתו מ\"ת תורה כלה מאורסה נש\"י חתן, ביום החמשים שער הנו\"ן המחבר חו\"ב, ל\"א נתיבות נתי' הל\"ב לא ידעו, למעלה מהדעת, פנימיות אבא, ובמ\"א נת' פנימיות או\"א<sup data-n=\"1567\">6</sup> כי גם שער הנו\"ן אינו מושג לעליונים כו' לתחתונים נדמה למעלה, ולכן י\"א אף בית קבורתו דמשה, בהש\"מ<sup data-n=\"1568\">7</sup> מחבר יום ולילה ע\"ד קרן, ביטול ומזה נמשך שיהי' כי קרן אור, ע' בד\"ה אר\"י יהא חלקי<sup data-n=\"1569\">8</sup>, ולכן איל כי זוכר עקידת יצחק לכפר כי אם צדקת, פי האתון שינוי הטבע, הבאר מטה ומן.\n<b>וענין</b> יהונתן ודוד י\"ל תפלה ותורה, דוד מל' ב' דלתי\"ן<sup data-n=\"1570\">9</sup> דל, ודלו עיני למרום, מל' קודם היחוד נק' דל, דלו עיני שכינתא עילאה ושכינתא תתאה, והמחבר וא\"ו, וא\"ו דיהונתן ועי\"ז ניתוסף ה' דבינה ע' בת\"א בד\"ה לך לך<sup data-n=\"1571\">10</sup>, בחי' עתיק, וז\"ע תפילה דדוד לעולם יכנס אדם שיעור שני פתחים, ב' דלתי\"ן לשקוד על דלתותי, פתח משקוף ושתי המזוזות נו\"ה ות\"ת פתח הפנימי חו\"ג ודעת שנחלק. חו\"ב וכתר ג' ראשי ראשין וכ\"ז מלמטלמ\"ע, אך יהונתן מלמעלמ\"ט, ע\"ד יוסף צדיק עליון ביהוסף הוספת ה' בינה עלמא דחירו ע\"י שעמד ביצרו יחוד חו\"ב, משכן העדות לא תעשה, כמו\"כ יהונתן עמד בנפשו על דוד, וע\"י חיבורם זכה להתברך וכנ\"ל בענין הצדיק אבד, ולכן עד שכרת ברית עם דוד נא' יונתן, וע\"י הכריתות ברית שלמעלה מהטעם ניתוסף ה' התגלות עתיק ע\"ד עדות ביהוסף, ולכן במ\"ת נא' קול גדול, בינה ע\"ד שופר גדול, במד\"ר שנחלק לע' לשון קולות בירור דע' שרים, והמברר במקום המתברר זהו שנתלבשו בדברים גשמי', ולע\"ל כתי' ויז נצחם כדרך הנלחמים ע' בד\"ה ולאחותו הבתולה<sup data-n=\"1572\">11</sup>, ועי\"ז סגולה, סגולתא כנ\"ל ג' ראשי ראשין, גם ע\"י סגול נקודה התחתונה ביטול עי\"ז סגולתא כי ומתחת זרועות עולם סוכ\"ע הכללי, ג' גווני הקשת ג' בני נח, שמהם נפוצו לע' לשון וכשיתחזו בגווני' נהירין זה מורה על הבירור אז תצפה לרגלי משיח.",[["1566","5","<b>ע\"ש, זמ\"ק</b>: ע' שרים, ז' מלכין קדמאין."],["1567","6","<b>פנימיות אבא ובמ\"א נת' פנימיות או\"א</b>: ראה המשך וככה תרל\"ז פי\"א (ע' יד): וראיתי בדרוש א' כתי\"ק אאמו\"ר שכשם שפנימיות אבא הוא פנימיות עתיק כן גם בחי' פנימיות בינה הוא ג\"כ פנימיות עתיק. וכ\"כ בסה\"מ עטר\"ת ע' שנה. הש\"ת ע' 50. ובסה\"מ הש\"ת שם מעיר ע\"ז כ\"ק אדמו\"ר זי\"ע: בהמשך וככה תרל\"ז פי\"א מביא זה מדרוש כתי\"ק הצ\"צ. ולע\"ע מצאתיו בסד\"ה ויסב אלקים אשר בספר שמות להצ\"צ [אוה\"ת בשלח ע' שפ וז\"ל: כי פנימיות בינה פנימיות עת\"י]. ואולי המקור לזה הוא הגהת הרנ\"ש לאוצרות חיים ש' עתיק פ\"ד\"."],["1568","7","<b>בהש\"מ</b>: בין השמשות."],["1569","8","<b>ע' בד\"ה אר\"י יהא חלקי</b>: סה\"מ תרכ\"ט ע' לח. וש\"נ."],["1570","9","<b>וענין יהונתן ודוד. . ב' דלתי\"ן</b>: בהבא לקמן ראה אוה\"ת בראשית שם יז, א."],["1571","10","<b>ע' בת\"א בד\"ה לך לך</b>: ר\"פ לך לך יא, סע\"ב."],["1572","11","<b>ע' בד\"ה ולאחותו הבתולה</b>: סה\"מ תרכ\"ז ע' רעז ואילך. תרכ\"ט ע' קצ ואילך."]]],[2000510470,"<b>ולכן</b> יהונתן נתן לדוד בחי' מל' סימן זה<sup data-n=\"1573\">12</sup> כי כשיהי' החיצים דקשת ממך והנה זה יורה על גמר הבירור ע\"ד מאן דקטיל לחויא, אמנם זה הי' כשהי' שאול מחרים עמלק, ג' מצות נצטוו להכרית כסדר דוקא, אבל כשנשאר שחמל, אזי החיצים ממך והלאה שצ\"ל עוד בירורים, עד לבוא לבחי' קשת בגווני' נהירין זהו בחי' ושלשת, נגד ג' גווני הקשת, וזהו ג\"כ שלשת החיצים דוקא, ובכדי לבוא לזה זהו ע\"י תרד מאד כענין ירידת הנשמה בגוף, וע\"י ההסתר בא לבחי' בכל מאדך, כן ע\"י תרד יהי' כמראה הקשת בגוונים נהירין, הוא מראה דמות כו' שיתגלה בחי' כבוד ה' וראו כל בשר, וזהו ע\"י עסק התורה ועבודה וגמ\"ח דעכשיו שהעולם עומד ל' קיום כמו מעמיד, וביחזקאל נא' ואפול, כי לא יכול לקבל, אבל לע\"ל ע\"י עבודה בג' דברים הנ\"ל נוכל לקבל וכמ\"ש ונגלה כבוד ה' וראו כל בשר.",[["1573","12","<b>ולכן יהונתן נתן לדוד. . סימן זה</b>: בהבא לקמן ראה אוה\"ת בראשית כא, ב ואילך."]]],[2000510471,"<h3>בענין והניף ידו על הנהר</h3>\n<b></b><b>[רישומי דברים לד\"ה וביום הבכורים]</b>\n[לד\"ה וביום הביכורים]\nבענין והניף ידו<sup data-n=\"1574\">1</sup> על הנהר י\"ל כי חגה\"ש מ\"ת ביום החמשים, קבורתו של משה נברא בהש\"מ<sup data-n=\"1575\">2</sup> (באבות) וי\"א אף קבורתו פי' בהש\"מ ממוצע בין יום ולילה, והיינו שער הנו\"ן ממוצע בין חו\"ב, והוא כלול מים החכ', ולכן חלקת מחוקק ספון פי' מחוקק רמ\"ח כמ\"ש במד\"ר והם ספון ע\"ד ספינה שמהלכין בו בים.\n<b>וזהו</b> שקרי\"ס הקדמה למ\"ת שיוכלו לילך בכל עת בים ע\"י ספינות של המצות שנק' ארבין ע' בבה\"ז פ' בשלח<sup data-n=\"1576\">3</sup>, ומשה שהי' הגואל, קרי\"ס מכלל הגאולה ומ\"ת, הי' קבור בחלקו של גד כמ\"ש בגמ' סוטה די\"ג ב', שנא' וירא ראשית לו חלקת מחוקק ספון, וצ\"ע מהר נבו שהי' בחלקו של ראובן, ולהיות כי מעשה המצות נתלבשו בגשמי' שגם הגשמיות מתעלה לריח ניחוח כמו הקרבן שהרי עכשיו ונשלמה פרים שפתינו, והעולים ויורדים בסולם זהו מעשה המצות, ובד\"ה כי ביום הזה יכפר דיוהכ\"פ<sup data-n=\"1577\">4</sup> ובמדרש תנחומא, ומאחר שגם הגשמיות מתעלה הנה גם החמץ יכול להתקרב, וזהו בשבועות דוקא כי שבועות הוא אחר ז' שבועות מפסח שנק' שבת, ובע\"ש מתעלים כל העשי', כן בעש\"ב<sup data-n=\"1578\">5</sup> מתעלה גם הטוב שבחמץ, ולכן יכול",[["1574","1","<b>בענין והניף ידו</b>: הוא רישומי דברים בקצרה מד\"ה וביום הביכורים (שבסיום המשך והחרים תרל\"א) הנדפס לעיל ע' שנו ואילך."],["1575","2","<b>בהש\"מ</b>: בין השמשות."],["1576","3","<b>ע' בבה\"ז פ' בשלח</b>: ביאוה\"ז לאדהאמ\"צ מא, סע\"ג ואילך."],["1577","4","<b>ובד\"ה כי ביום הזה יכפר דיוהכ\"פ</b>: לקו\"ת אחרי כו, ב. וראה גם לקו\"ת דרושים ליוהכ\"פ סט, ג."],["1578","5","<b>בעש\"ב</b>: ובערב שבועות."]]],[2000510472,"להקריב בשבועות בחלת תודה ושתי הלחם. צ\"ע ששבועות אחר ז' שבועות ושבת יום השביעי. וי\"ל שזהו ע\"ד תורה חדשה דלע\"ל שיש מקצת ממנה במ\"ת, דאל\"כ מאין יהי' חדשות, הלא אין כל חדש תחת השמש, וזה יהי' בביאת משיח במהרה בימינו, שאז עדיין יהיה השמש אלא שמקצתה הי' בעת מ\"ת, וגם י\"ל שלעתיד יהי' הבינה עיקר ולכן עבודה בבכורות שיחוסם אחר האם דבינה, לכן שבועות אחר ז' ביום המתחלת שבוע שמינית. ושבועות ביום הוא\"ו, והכל מודים שמ\"ת הי' בשבת להורות שגם חול נתעלה ע\"ד שבת ולכן חמץ קרב בשתי הלחם ותודה, וזהו והניף שתי וגו' על שתי הכבשים להגיע הכבש לכשב שי\"ן חג\"ת דאריך שקודם לחו\"ב<sup data-n=\"1579\">6</sup>.\n<b>אכן</b> כ\"ז הי' במ\"ת, אבל לע\"ל והחרים לשון ים כ\"מ שנוכל לומר לשון ים, מצרים בי\"ע ע' בת\"א<sup data-n=\"1580\">7</sup> בי\"ע מצרים בי\"ע דכלליות, ולכן אז יניף ידו ולא מטה על הנהר השגה, והכהו לז' נחלי' ז\"ת דעתיקא דכלליות כדוגמת עתיק לעילא מגלגלתא דא\"ק, ומספר ז' ע\"ד והי' מספר אשר לא יספר, והדריך בנעלים ע\"ד הגילוי מבחי' נעל דשכינתא, רק שישראל ילכו בנעלים, ע\"ד מה יפו פעמיך בנעלים, ואז והחרים בחי' שם הוי' שמקור להשתלשלות עד שיניף ידו על הנהר דהשגה הנ\"ל והכהו לז' שורש נש\"י דז\"א בעתיקא. שני דברים קדמו תורה וישראל וישראל קדמו לתורה שהרי בתורה נא' צו את בנ\"י, והדריך בנעלים ע\"ד ואלה מסעיהם למוצאיהם, מלמטלמ\"ע זהו הגילוי לע\"ל ע\"י הזיכוך דעכשיו ולכן על הנהר דוקא, מי ברא אלה, אלקים דבינה, ולע\"ל והחרים ה' דז\"א עד שיניף על הנהר דבינה והכהו לז\"נ ז\"ת דעתיקא והדריך בנעלים מבחי' מסעיהם לבחי' מוצאיהם שקדמו לכ\"ד אפילו לתורה כו'.\n<b></b>",[["1579","6","<b>להגיע הכבש לכשב שי\"ן חג\"ת. . שקודם לחו\"ב</b>: ראה בארוכה לקו\"ת אמור לז, ב ואילך. לח, סע\"ד ואילך."],["1580","7","<b>מצרים בי\"ע ע' בת\"א</b>: תו\"א בשלח סה, סע\"ג-ד."]]],[2000510473,"<h3>בזוה\"ק כו' ר' יוסי פתח מה ידידות</h3>\n<b>בס\"ד.</b>\n<b>בזוה\"ק</b><sup data-n=\"1581\">1</sup> פ' לך לך דע\"ז ע\"א. ר' יוסי פתח מה ידידות משכנותיך ה' צבאות כמה אית לון לבני נשא כו' לא ידעי ולא מסתכלי על מה קאים עלמא ואינון על מה קיימין דכד ברא קוב\"ה עלמא עביד שמיא מאש וממים מתערבין כחדא ולא הוי גלדי ולבתר אגלידי וקיימי ברוחא עילאה ומתמן שתל עלמא לקיימא על סמכין ואינון סמכין לא קיימין אלא בההיא רוחא, ובשעתא דרוחא אסתלק כולהו מרפפן וזעין ועלמא אירתת הה\"ד המרגיז ארץ ממקומה ועמודי' יתפלצון וכולא קאים על אורייתא דכד משתדלי באורייתא קאים עלמא כו' ועד\"ז איתא בגמ' חגיגה די\"ב ב' בשם ר' יוסי הנ\"ל אוי לבריות שרואי' ואינם יודעין כו' הארץ עומדת על עמודים ועמודי' על המים ומים על ההרים והרים על הרוח כו' ע\"ש. וצ\"ל מאמר זהר הנ\"ל וגם מהו שייכות להפסוק דמה ידידות כו', וגם מהו שייכות כל הפ' הנ\"ל על פ' דלך לך.\n<b>הענין</b> הוא דשמיא עביד מאש וממיא הוא בחי' חו\"ג, מים יורדי' מגבוה לנמוך הוא בחי' חסד השפעה, ואש טבעו לעלות הוא מדת הגבורה כי התהוות העולם הוא ע\"י ב' המדות דוקא חו\"ג כמ\"ש כי אמרתי עולם חסד יבנה אמנם לא יוכל להיות קיום עולם ע\"י מדת החסד לבד כמו שאנו רואים במלכותא דארעא שהנהגת מלוכה א\"א כ\"א גם ע\"י דין ומשפט כמ\"ש מלך במשפט יעמיד ארץ שצריך להיות דין ומשפט ובלא זה א\"א להיות התנהגות המלוכה כלל, וכך למעלה התהוות העולמות לא הי' יכול להיות ע\"י מדת החסד בלבד והי' צריך להיות התכללות חו\"ג דוקא היינו אש ומים. והנה אש ומים הם ב' הפכים בטבעם והרוח הוא ת\"ת מחבר אותם כמ\"ש עושה שלום במרומיו בין מיכאל וגבריאל שאין מכבין זא\"ז והוא ע\"י בחי' היותר גבוה משניהם<sup data-n=\"1582\">2</sup> ולכן נק' הקב\"ה שלמה מלך שהשלום שלו שמחבר ב' הבחי' חו\"ג ע\"י גילוי אלקות בעצמו, וכמו\"כ הרוח הוא ג\"כ מחבר אש למים וזהו בחי' התיקון שנמשך מכח מ\"ה כלי להשראת אוא\"ס ב\"ה אשר לאו מכל אינון מדות איהו כלל, ועי\"ז הוא התכללות המדות חו\"ג.",[["1581","1","<b>בזוה\"ק. . ר' יוסי פתח מה ידידות</b>: מאמר זה הוא הנחה ממאמר כ\"ק אדמו\"ר הצ\"צ, אשר עליו מיוסדים המאמרים ד\"ה ויאמר גו' לך לך תרל\"א שנדפסו לעיל ע' כ ואילך וע' לד ואילך. — מאמר זה נמצא בכת\"י מעתיק בבוך גוכי\"ק של תרל\"א (מס. 1061 יג, א) לפני המאמרים ד\"ה ויאמר גו' לך לך הנ\"ל. ונמצא גם בס' בש\"ו כת\"י 1063 כה, א ואילך [כת\"י זה כולל הנחות הרה\"ח ר' בערל קאליסקער ממאמרי אדמו\"ר הצ\"צ].\nהמאמר מיוסד על ד\"ה זה בס' ביאוה\"ז לאדהאמ\"צ ח, ג ואילך. מאמרי אדה\"ז תקס\"ג ח\"א ע' נא ואילך. וראה ד\"ה ויאמר גו' לך לך באוה\"ת לך לך (כרך ד) תרעו, ב ואילך."],["1582","2","<b>עושה שלום במרומיו. . ע\"י בחי' היותר גבוה משניהם</b>: הובא בשם הה\"מ ממעזריטש בביאוה\"ז לאדהאמ\"צ שם ח, ג. ומאמרי אדה\"ז תקס\"ג שם ע' נב. וראה גם אגה\"ק סי\"ב (קיז, א). לקו\"ת תזריע כג, רע\"ג. מאמרי אדה\"ז אתהלך לאזניא ע' יב. תקס\"ב ח\"ב ע' תמ. סה\"מ תרל\"ג ח\"ב ע' תקד. תר\"ם ח\"א ע' רלא-ב. וש\"נ."]]],[2000510474,"<b>וז\"ש</b> בס\"י שלש אמות אמ\"ש<sup data-n=\"1583\">3</sup> הוא אויר מים אש שהאויר מחבר מים לאש כי אויר גבוה יותר כמו שרואים למטה שהאש נתפס בחוש הראות והמים נתפסים גם בחוש המישוש, אבל האויר הוא בדקות יותר שאינו נתפס בחושי' הנ\"ל, ולכן האויר הוא המחבר אש ומים, וז\"ש בזוהר דמתחלה לא הוו גלדי ולבתר אגלידו וקיימו ברוחא עילאה דע\"י הרוח אגלידו המים ור\"ל שנקרשו המים ונעשו גלד וקרח, כי המים כשהולכי' הולכים בחוזק והם בבחי' יש כמ\"ש כקול מים רבים אבל כשהם נגלדים ע\"י רוח צפונית שמנשבת בהם בתוקף ובקרירות גדול ונעשה קרח וגלד הוא ביטול ממהותם ועומדים על בחי' א', וקרח אותיות חרק<sup data-n=\"1584\">4</sup> כמו החירק הוא רק נקודה א' בחי' ביטול, וז\"ש ברבות בראשית על מאמר יהי רקיע בתוך המים, והרי נברא שמים ממאמר דבראשית אלא מתחילה לא הוו קרשי ולבתר אתקרישו, והיינו ע\"י רוחא עילאה נמשך בהם בחי' ביטול באש ומים ונתגלדו כחדא.\n<b>ואח\"כ</b> איתא בזהר וכולא קאים על אורייתא, כי אורייתא מחכ' נפקת ובחכ' שורה אוא\"ס ב\"ה ולכן מזה נמשך התכללות המדות והוא ע\"י קול התורה כי הקול מורכב ג\"כ מג' יסודות אש מים רוח כי הקול יוצא מהבל הלב הוא יסוד האש והריאה מרחפת על הלב הוא יסוד המים וע\"י התחברות הקנה והלב והריאה יוצא הקול ולכן רואי' כשיש באדם התגברות יסוד א' יש שינוי בקול כו', וע\"י קלא דתורה דאורייתא מחכ' נפקת עי\"ז הי' קיום העולמות והתכללות המדות חג\"ת כי לגבי בחי' דלאו מכל מדות כלל נעשה ביטול בהמדות ונכללין כא', וכ\"ז הוא בבריאת שמים.\n<b>ואח\"כ</b> כ' בזהר ומתמן שתיל עלמא לקיימא על סמכין ואינון סמכין לא קיימין אלא בההוא רוחא ובלשון הגמ' דחגיגה הוא לשון עמודים, כי הנה כתי' כי גבהו שמים מארץ, שמים הוא בחי' התכללות ע\"ס דאצי'<sup data-n=\"1585\">5</sup> אשר שם איהו וחיוהי חד, והארץ הוא מקור ההשתלשלו' נבראי' בע\"ג וכמשנ\"ת דקיום שמים הוא ע\"י רוחא עילאה והוא להתכלל חג\"ת כו', כמ\"כ ארץ הוא בחי' נה\"י והתכללותם הוא ג\"כ ע\"י רוחא עילאה המחברם, ובחי' נה\"י בלשון קבלה נק' בשם כליות יועצות דהיינו בחי' עצה איך להמשיך אלקו' למטה בנבראי' ועולמות דבי\"ע כמו עד\"מ בגשמיות האדם מייעץ בעצמו איך להמשיך שכל לחבירו, והתכללות ג' בחי' דנה\"י הוא ג\"כ ע\"י אורייתא דהיינו ע\"י קיום תומ\"צ כמ\"ש במחוקק במשענותם, במחוקק הוא אותיות החקיקה דתורה, במשענותם הוא מצות<sup data-n=\"1586\">6</sup> כי מצות נק' תמכין. וזהו בחי' תמכין שבזהר ועמודי' שבגמ' שע\"י תומ\"צ דנש\"י הוא קיום כל הנבראים ועולמות כו'. והיוצא מכל",[["1583","3","<b>וז\"ש בס\"י שלש אמות אמ\"ש</b>: ראה גם לקו\"ת שה\"ש מט, ג."],["1584","4","<b>וקרח אותיות חרק כמו החיריק</b>: ראה לקו\"ת דרושים לשמע\"צ פז, ב (בשם הרה\"ק ר' אברהם בן הה\"מ). מאמרי אדה\"ז על מארז\"ל ע' תב. וראה גם לקו\"ת שה\"ש כו, ב. מאמרי אדה\"ז תקס\"ה ח\"א ע' תנב. תקס\"ז ע' קעו. ביאוה\"ז לאדהאמ\"צ מה, ג. אוה\"ת שה\"ש (כרך ב) ס\"ע שצט-ק. סה\"מ תרכ\"ז ע' תכז. תרס\"ג ח\"א ע' קנו. קנח."],["1585","5","<b>שמים הוא בחי' התכללות ע\"ס דאצי'</b>: ראה ביאוה\"ז לאדהאמ\"צ מה, א."],["1586","6","<b>במחוקק. . אותיות החקיקה דתורה במשענותם. . מצות</b>: ראה לקו\"ת חוקת סג, ד. סד, סע\"ב-ג."]]],[2000510475,"הנ\"ל שקיום שמו\"א הוא ע\"י רוחא עילאה היינו התחברות חג\"ת מדות עליונות ונה\"י וכולא ע\"י תורה דאורייתא מחכ' נפקת כח מ\"ה אשר שם שורה אוא\"ס ב\"ה כו'.\n<b>והנה</b> שייכות מאמר זהר זה ע\"פ דמה ידידות משכנותיך הוא כי ידידות הוא התקשרות אהבה עזה בפנימי' הנמשך בנש\"י ע\"ד שארז\"ל מפרשיתו של אותו רשע למדנו שלשה דברים חשיקה חפיצה דביקה ור\"ל אהבה פנימי', ומצינו שנשתבחו נש\"י בג' בחי' הנ\"ל כמ\"ש כי תהיו אתם ארץ חפץ, ולדבקה בו, בכם חשק ה', כי הנה בהשתלשלות חיות אלקות בעולמות יש ב' בחי' כי התחדשות חיות אלקות שנמשך תמיד בכ\"י להחיות כל העולמות כמ\"ש לעולם ה' דברך נצב בשמים<sup data-n=\"1587\">7</sup> המחדש בטובו בכל יום תמיד מע\"ב, הנה הגם שמהווה ומחדש תמיד אור אלקי הנמשך בעולמות אבל הוא בבחי' העלם והסתר אלקות כי עולם הוא לשון העלם, אבל יש עוד בחי' גבוה מזה והוא תוס' אורות עליונים שבא לפרקים וזה הוא עיקר שיתגלה תוס' אורות כמ\"ש אור חדש על ציון תאיר<sup data-n=\"1588\">8</sup>, ובחי' זו נק' ג\"כ ידידות פנימית אלקות כמשארז\"ל צמצם שכינתו בין ב' בדי הארון<sup data-n=\"1589\">9</sup>, כי בענן אראה כו' ונועדתי כו', ולכאורה הרי מכה\"כ ולית אתר פנוי מיני' ומה החידוש במשכן, אלא שבמשכן הי' התגלות והשראת השכינה בפנימית ממש, משא\"כ בעולם הוא העלם והסתר.\n<b>וזהו</b> שמסיים בזהר אח\"כ בשעתא דרוחא דכל רוחין ארום בסימו דנשמתא כו', כי ענין רוחא ורוחא דכל רוחין הוא כמו ב' בחי' הנ\"ל בחי' חיות אלקות שמחי' תמיד ובחי' אור חדש הנ\"ל, כי רוחא הוא החיות אלקות שנמשך תמיד ומחבר אש ומים חו\"ג וזהו קיום וחיות העולמות תמיד, אבל הוא בחי' העלם והסתר כו', ורוחא דכל רוחין הוא גילוי תוס' אורות עליונים ונק' בחי' נשמה, וכמו למשל למטה יש ד' בחי' דצח\"מ, דומם הוא בחי' אחרונה ובו חיות מועט, ולמעלה ממנו הוא צומח שיש בו נפש הצומחת, והצומח מקבל חיות משרשו אין לך עשב כו', ולמעלה ממנו הוא בחי' חי שיש בו חיות רוח חיים כו'. אבל כל הג' בחי' אינם בערך המדבר שהוא בחי' יותר גבוה שאין בערך כלל ויש בו נפש המשכלת ושכל להשכיל כו' רק נפש המשכלת שבמדבר הוא רק להשכיל שכל גשמי, ולמעלה נק' בחי' תוס' אורות הנ\"ל ג\"כ בשם נשמה עדמ\"ש נשמת שדי תבינם. וז\"ש אם ישים אליו לבו רוחו ונשמתו אליו יאסוף דהיינו רוחו ונשמתו שלמעלה שהוא בחי' גבוה ואז ארום בסימו דנשמתא, בסימו הוא המתקת הדינים לשון מתיקות ותענוג שנמשך אור חדש מלמעלה, ומתמן נפיק קלא דקלא, כי יש חיצונית הקול ופנימית הקול, וע\"י גילוי רוחא דכל רוחין בסימו דנשמתא עי\"ז מתגלה בחי' קלא פנימאה. וז\"ש קול דודי מדלג על ההרים כו'.",[["1587","7","<b>חיות אלקות שנמשך תמיד. . לעולם ה' דברך נצב בשמים</b>: ראה בכ\"ז שעהיוה\"א פ\"א."],["1588","8","<b>כמ\"ש אור חדש על ציון תאיר</b>: סיום ברכת ”יוצר המאורות\" ע\"פ נוסח אשכנז. הובא גם בלקו\"ת שה\"ש ט, ב. כ, ב. סידור עם דא\"ח סח, רע\"ב. מאמרי אדה\"ז תקס\"ב ח\"א ע' קצב. מאמרי אדהאמ\"צ במדבר ח\"א ע' קמו. אוה\"ת לך לך (כרך ד) תרצז, רע\"א. שה\"ש (כרך ג) ע' תתלד. סה\"מ תרכ\"ט ע' קט וע' קצו. תרל\"ג ח\"א ע' כ. פר\"ת ע' קמה. ועוד."],["1589","9","<b>כמשארז\"ל צמצם שכינתו בין ב' בדי הארון</b>: ראה בכ\"ז לקו\"ת אמור לד, ב. בלק עג, ב."]]],[2000510476,"<b>והנה</b> שייכות פי' מאמר זה ע\"פ מה ידידות לפרשת לך לך הוא, כי הנה אברהם נק' ג\"כ ידיד ה' כמשארז\"ל במנחות דנ\"ג ע\"א יבא ידיד זה שלמה שנק' ידידיה בן ידיד זה אברהם ויבנה ידיד זה בהמ\"ק לידיד זה הקב\"ה כו' ע\"ש, כי אברהם הי' לו אהבה בידידות לאלקות ורצה להמשיך שם ה' בעולם כמ\"ש ויקרא בשם ה' כו' ולכן אמר לו ה' לך לך מארצך. ולהבין זה וגם מהו ב\"פ לך לך, הענין הוא דפי' לך לך היינו שיתגלה בו בחי' שרש נשמתו שהיא גבוה מאד כי הנה ישראל עלו במח' וארז\"ל מחשבתן של ישראל קדמה לכולם, וענין מח' שלמעלה הוא בחי' גבוה כמ\"ש כי לא מחשבותי מחשבותיכם<sup data-n=\"1590\">10</sup> כו', ולהבין מהו דוקא במחשבה נשתבח הקב\"ה שאינו שוה מחשבה שלמעלה למחשבת האדם ולא בשארי מדות, הענין הוא דבמח' הוא ניכר יותר החילוק, כי באדם הנה ממחשבתו אין נעשה דבר ואפי' יחשוב האדם כמה, רק אח\"כ ע\"י דיבור ומעשה כו', ולמעלה הוא להיפוך ממש במח' אחת ברא הקב\"ה את כל העולמות כו', אפי' תה\"מ, הכל היו כלולי' במח' או כמ\"ש בדבר ה' שמים נעשו ענין עשרה מאמרות<sup data-n=\"1591\">11</sup> הוא מפני שממחשבתו לא הי' יכול להתהוות עולמות ונבראים בבחי' יש נפרד והי' רק בחי' עלמין סתימין, ומהדבור נעשה עוה\"ז הגשמי וכל הנבראי' גשמי' כו', והנה ישראל עלו במח' והיינו ששרש נש\"י נמשכו מבחי' מח' ונק' מזל בחי' ונוזלים מן לבנון וכמארז\"ל מזלייהו חזי, אבל הנשמה המלובשת בגוף היא בחי' אחרונה של הנשמה וירדה ע\"י ד' מדרגות טהורה בראת יצרת נפחת כו'.\n<b>וזהו</b> שאמר הקב\"ה לאברהם לך לך דהיינו שיתגלה בו שרש נשמתו שהוא בחי' גבוה מאד כמבואר בכתבי האריז\"ל שגילוי זה דשרש נשמתו הוא גבוה אפי' מהשגת רוה\"ק וגילוי אלי'<sup data-n=\"1592\">12</sup>, ולכן ב' לך לך דהיינו לעצמך לשרש נשמתך, וענין הב' כפין דלך לך הוא בחי' ב' כתרים שבמ\"ת שקשר להם שני כתרים, כי כתר הוא מחבר אא\"ס עם העולמות ושני כתרים הוא מלמעלמ\"ט ומלמטלמ\"ע, מארצך וממולדתך כו' כי בחו\"ל הוא השפעת ע' שרים שיניקתם ממל' דעשי' שנתלבש בו מל' דיצי' לא יותר וכדי שיזכה אברהם לגילוי זה דשרש נשמתו הוצרך לעלות מחו\"ל לא\"י שבא\"י הוא גילוי מל' דבריאה כו'.\n<b>וזהו</b> ענין שייכות מאמר הזהר דרוחא דכל רוחין ע\"פ דמה ידידות וזהו שייכות לפ' לך לך, כי ענין רוחא ורוחא דכל רוחין הוא כמו בחי' גילוי אלקות שבעולם בתמידיות ובחי' גילוי אלקות שהי' במשכן שהי' גילוי פנימי' אלקות, ואברהם הי' לו ג\"כ גילוי פנימי' אלקות ולכן נק' ידיד ג\"כ, וזהו ג\"כ ענין לך לך שיתגלה כל שרש נשמתו שהוא גבוה מאד.\n<b></b>",[["1590","10","<b>וענין מח' שלמעלה. . כי לא מחשבותי מחשבותיכם</b>: בהבא לקמן ראה בארוכה לקו\"ת שה\"ש יז, סע\"ג ואילך. וראה גם לקו\"ת ואתחנן ב, ב. סה\"מ תרל\"ד ע' רמ. ובכ\"מ."],["1591","11","<b>במח' אחת ברא. . ענין עשרה מאמרות</b>: ראה בארוכה סה\"מ תרכ\"ז ע' רפב ואילך. [ובהנסמן שם בתחילת המאמר]."],["1592","12","<b>שגילוי זה דשרש נשמתו הוא גבוה אפי' מהשגת רוה\"ק וגילוי אלי'</b>: ראה בהנסמן ע\"ז לעיל ע' מב."]]],[2000510477,"<h3>וביום הביכורים</h3>\n<b></b><b>בס\"ד. חג השבועות תרל\"א.</b>\n[הנחת השומעים]\n[חג השבועות]\nהנחת ר\"א ז\"ס.\n<b>וביום</b> הביכורים<sup data-n=\"1593\">1</sup> בהקריבכם מנחה חדשה לה' בשבועותיכם מקרא קדש יהי' לכם, ופי' רש\"י חג השבועות קרוי בכורי קציר חטים ע\"ש שתי הלחם. וצ\"ל מפני מה בכל הקרבנות כתיב כל שאור וכל דבש לא תקטירו כו', ובשתי הלחם הי' דוקא חמץ כמ\"ש חמץ תאפינה, ומוכרח לומר שמפני הגילוי הגדול שמאיר ומתגלה בחג השבועות יוכל גם החמץ להתעלות.\n<b>והענין</b> כי חג השבועות הוא יום החמשים מפסח, כי הנו\"ן יום הם כנגד נו\"ן שערי בינה<sup data-n=\"1594\">2</sup>, ובכל יום מתגלה שער אחד, ובחה\"ש מתגלה השער הנו\"ן, ולכן אין סופרין ספה\"ע כ\"א מ\"ט יום כי השער הנו\"ן א\"א להמשיכו אלא הוא מתגלה מאיליו וממילא אחר ספירת מ\"ט יום.\n<b>והענין</b> דהנה ארז\"ל עשרה דברים נבראו ערב שבת בין השמשות<sup data-n=\"1595\">3</sup>, וי\"א אף קברו של משה, ופי' הה\"מ זצ\"ל<sup data-n=\"1596\">4</sup> כי יום ולילה הוא חסד וגבורה, והמחבר אותם הוא האין דחכמה כמ\"ש והחכמה מאין תמצא, כי כדי שיתחברו חו\"ג שהם שני הפכים הוא ע\"י בחי' הגבוה מהם שהוא ע\"י האין דוקא וזהו בין השמשות כמשנ\"ת בדרוש הקודם<sup data-n=\"1597\">5</sup> שזהו שאר\"י שבין השמשות הוא כהרף עין. אך צ\"ל מדוע המספר דוקא עשרה דברים. אך הענין דהנה ביו\"ד מאמרות נברא העולם נגד יו\"ד ספירות, אך זהו היו\"ד ספירות שבמל'<sup data-n=\"1598\">6</sup>, וכדי שיוכלו לבוא אלו היו\"ד דברים לידי בריאה שכל אלו הדברים הם יוצאים מדרכי הטבע כמשי\"ת זהו ע\"י יו\"ד ספי' דאצילות או ע\"ס הגנוזות במאצילן כשלהבת הקשורה בגחלת, וכדי שיהי' איזה גילוי מהע\"ס הוא ע\"י האין וזהו המספר דיו\"ד דברים. אך לפ\"ז צ\"ל מהו וי\"א אף קברו של משה, והענין דהנה ארז\"ל תנא אר\"י אלמלא מקרא כתוב א\"א לאומרו היכן משה מת בחלקו של ראובן דכתיב ויעל משה מערבות מואב אל הר נבו, ונבו בחלקו של ראובן קיימא",[["1593","1","<b>וביום הביכורים</b>: הוא הנחה מד\"ה זה הנדפס לעיל (ע' שנו ואילך) והוא מאמר האחרון מההמשך ”והחרים — תרל\"א\".\nמאמר זה נדפס כאן מכת\"י 1074 הכולל הנחות הרה\"ח ר' אהרן זעלגיסאן ממאמרי כ\"ק אדמו\"ר מהר\"ש מהשנים תר\"ל-תרל\"ב."],["1594","2","<b>והענין כי חג השבועות. . הנו\"ן יום. . נו\"ן שערי בינה</b>: בהבא לקמן ראה לקו\"ת במדבר יב, א ואילך."],["1595","3","<b>והענין דהנה ארז\"ל עשרה דברים. . בין השמשות</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת וירא ק, סע\"ב ואילך. ביאוה\"ז להצ\"צ (כרך ב) ע' תשעה-ו. וראה גם אוה\"ת ואתחנן ע' קנג."],["1596","4","<b>ופי' הה\"מ זצ\"ל</b>: או\"ת ט, ד. שם י, סע\"א. לקו\"א להה\"מ סי' ז (ו, א). וסי' רג (נא, א). — הובא ונת' באוה\"ת וירא שם ק, סע\"ב ואילך. ביאוה\"ז להצ\"צ שם ע' תשעה. וראה גם אוה\"ת יתרו ע' תתס. חוקת ע' תתכ (בהוצאת תשנ\"ח)."],["1597","5","<b>כמשנ\"ת בדרוש הקודם</b>: ד\"ה כמראה הקשת לעיל ע' שנב. וש\"נ."],["1598","6","<b>ביו\"ד מאמרות. . היו\"ד ספירות שבמל'</b>: ראה (באו\"א) אוה\"ת נ\"ך (כרך ב) ע' תתמא. סה\"מ תרנ\"ט ע' קמז. תש\"ד ע' 74."]]],[2000510478,"דכתיב ובני ראובן וגו', והיכן משה קבור בחלקו של גד דכתיב וירא ראשית לו כי שם חלקת מחוקק ספון, מחלקו של ראובן עד חלקו של גד כמה הוי ארבעה מילין, אותן ד' מילין מי הוליכו, מלמד שהי' משה מוטל בכנפי השכינה ומלאכי השרת אומרים צדקת כו', והקב\"ה מאי אמר מי יקום כו', ור\"י אמר והחכמה מאין תמצא, ושם וי\"א לא מת משה כתיב הכא וימת שם משה וכתיב התם ויהי שם כו', א\"ר חמא בר' חנינא אף משה רבינו אינו יודע היכן קבור כתיב הכא ולא ידע איש את קבורתו וכתיב התם וזאת הברכה אשר ברך משה איש האלקים, פי' הגם שהיה מושל ושליט על שם אלקים וזהו איש האלקים, מ\"מ לא ידע קבורתו.\n<b>ובכדי</b> להבין כ\"ז צריך להבין ענין נתינת התורה<sup data-n=\"1599\">7</sup>, דהנה ארז\"ל לא ניתנו דברי תורה חתוכין למשה אלא מ\"ט פנים טהור ומ\"ט פנים טמא, שזהו נגד חו\"ג, כי התורה שרשה ממדות עליונות, וזהו דודי צח ואדום, צח הוא ב\"פ מ\"ט, ויש בזה צח ואדום חו\"ג. ובעבודה הוא כי יצ\"ט ויצה\"ר שרשן ג\"כ מחו\"ג, וכדי לאהפכא את היצה\"ר ששרשו מגבורה הוא ע\"י התורה. והענין דהנה כתיב חלקת מחוקק ספון<sup data-n=\"1600\">8</sup>, מחוקק בגימט' רמ\"ח הוא רמ\"ח מ\"ע, וע\"י מגיעים למדריגת ספינה כי ספון הוא מלשון ספינה, דהיינו כמו שהספינה מחברת ברואים שביבשה עם הים<sup data-n=\"1601\">9</sup>, כי ברואים שבים היינו דגי הים המה מכוסים ומובלעים בתוך הים כי זהו חיותם וקיומם, אבל ברואים שביבשה הרי א\"א להם להיות בתוך הים, והספינה מחברת ברואים שבעלמא דאתגלייא עם עלמא דאתכסייא. כמו\"כ הם מעשה המצות שנשפלו למטה מטה, והנה\"א ירד ג\"כ למטה ונתלבש בנה\"ב, וע\"י שיקיים מצוה בגשמיות עי\"ז יוכל להשיג השגות כמו בעלמא דאתכסייא.\n<b>ובזה</b> יובן מה שהיה נצרך קרי\"ס כהקדמה והכנה למ\"ת, כי אותות ומופתים שבמצרים היה כדי להוציאם ממצרים, אבל קרי\"ס היה הקדמה למ\"ת. והענין דכדי שיוכלו נש\"י לקבל התומ\"צ, ועל ידם יתחבר עלמא דאתגלייא בעלמא דאתכסייא, והם לא ראו מעולם ולא ידעו מה זה הגילוי דעלמא דאתכסייא, לכן הי' תחלה קרי\"ס הפך ים ליבשה, דהיינו שנתגלה להם הים שזהו עלמא דאתכסייא וראו הגילוי הגדול דשם, ואח\"כ ניתן לישראל תומ\"צ ועל ידם מתגלה ג\"כ גילויים עליונים. אך זהו ההפרש שבקרי\"ס הי' הגילויים ביבשה, אור האצי' רק בבריאה כמ\"ש ובני ישראל הלכו ביבשה בתוך הים, היינו לפי שני הפירושים לפי' הזהר וכתבי האריז\"ל, אבל ע\"י תומ\"צ משיגים למטה בעולם העשי' כל ההשגות שבו כמו שמשיגים בעלמא דאתכסייא. ועוד זאת כי קרי\"ס הי' הגילוי לפי שעה אבל ע\"י קיום המצות משיגים בכל עת ובכל שעה כשמקיים איזו מצוה הרי אז הוא מתקשר א\"ע להמצוה, ועי\"ז מתגלה ע\"י גילויים עליונים.",[["1599","7","<b>ובכדי להבין כ\"ז צריך להבין ענין נתינת התורה</b>: בהבא לקמן ראה אוה\"ת יתרו ע' תתצא-ב. סה\"מ תרכ\"ז ס\"ע שב ואילך. שיג. תרנ\"ח ע' מד. עת\"ר ע' קיז-ח. עטר\"ת ס\"ע תג-ד. תרפ\"ח ע' קלא-ב."],["1600","8","<b>והענין דהנה כתיב חלקת מחוקק ספון</b>: בהבא לקמן ראה ביאוה\"ז להצ\"צ שם ע' תשעה-ו."],["1601","9","<b>כמו שהספינה מחברת ברואים שביבשה עם הים</b>: בכ\"ז ראה ביאוה\"ז לאדהאמ\"צ מא, סע\"ג ואילך."]]],[2000510479,"<b>ובזה</b> יובן מהו ההתחדשות דמ\"ת<sup data-n=\"1602\">10</sup>, והלא האבות קיימו ג\"כ את התורה עד שלא ניתנה. אך הענין דהנה האבות קיימו את התורה בכח עצמם דהיינו במס\"נ, וכמ\"ש בס' הבהיר אמרה מדת החסד לפני הקב\"ה כ\"ז היות אברהם בארץ לא הוצרכתי לעשות מלאכתי שהרי אברהם עומד במקומי, הרי דאברהם אבינו נעשה מרכבה למדת החסד, והוא ע\"י שהי' נדיב בגופו ונפשו וממונו, כמו\"כ קיום המצות שלו הי' ג\"כ ע\"י המס\"נ שלו, ועי\"ז השיג ברוחניות כל מה שיש במצות. אבל כאשר ניתן התורה א\"צ למס\"נ לכל מצוה בפרט אלא לקיים רצון הבורא ועי\"ז מאיר על נפשו גילויים אלו, אך התקשרות צ\"ל למצות, דאם מקיים דרך מצות אנשים מלומדה בקרירות לא ימשיך עי\"ז כלום, אבל כשמקשר א\"ע איזה התקשרות, כמ\"ש בשו\"ע דבתפילין צריך לשעבד הלב והמוח, וע\"י כוונה זו הפשוטה מתקשר לאלקות ומאיר ומתגלה גילוי אלקי על נפשו, אבל מה שקיים אאע\"ה הי' זה ע\"י עובדות ומס\"נ. וזהו מ\"ש אני כברוש רענן<sup data-n=\"1603\">11</sup> ברוש הוא ארז הגדול בגובה, וכאשר כופפין את ראשו ומניחין עליו איזה דבר הנה אח\"כ כשמניחין אותו ונזקף מכפיפותו הרי הוא מגביה את הדבר שמונח עליו למעלה מעלה, כן הוא בנמשל על מצות, כי המצות נשפלו למטה בגשמי' וכאשר מקיים איזה מצוה עי\"ז נתעלה הנפש למעלה מעלה. דהנה כל מצוה הוא רצה\"ע ב\"ה, אך הוא פרטי הרצון, כמו שבת מוחין דאבא, יו\"ט מוחין דאימא, ובדרך כלל ג' רגלים הם כנגד ג' בחי' בתי אחותי ואמי, וע\"י קיום כל המצות נתעלה הנפש מה שלא הי' יכול להתעלות מצד עצמו, וזהו אני כברוש רענן. וזהו ג\"כ מ\"ש סולם מוצב ארצה וראשו כו' ומלאכי כו' עולים ויורדים, ואיתא במדרש סולם זה סיני וקאי על תורה, ובמדרש תנחומא דרשו מלאכי אלקים על מצות, כי ע\"י המצות נתעלה הנפש וגם ממשיכים המשכת אלקות. וזהו חלקת מחוקק ספון דהמצות הם כמו ספינה שמחברים המשכת אלקות למטה.\n<b>ובזה</b> יובן מה שבחג השבועות יוכל להתעלות גם החמץ, כי חמץ קאי על יצה\"ר כמ\"ש מכף מעוול וחומץ ונק' חמץ שיכול להתחמץ לגמרי, והקרבן הוא שיהפכו אותו מן הקצה אל הקצה, וזהו כל שאור כו' לא תקטירו כי ע\"פ סדר השתלשלות אינו יכול להתעלות כ\"א צריך לדחות אותו בדרך לא, וזהו לא תקטירו, אך בחה\"ש מקריבין לחם חמץ שנתחמץ לגמרי דהיינו מחמת עוצם הגילוי שבחג השבועות יוכל גם החמץ להתעלות. וזהו והניף הכהן אותם על לחם הביכורים תנופה גו' על שני כבשים, כי כבש מורה על סדר השתל' כי הכ\"ף רומז על הכתר והבי\"ת הוא חכמה ושי\"ן ג' מדות, אבל כשב הוא למעלה מסדר השתל'<sup data-n=\"1604\">12</sup> דשי\"ן קודם לבי\"ת מדות דא\"א, והניף הכהן אותם למעלה למעלה ממדריגת הנבראים כ\"א למדריגת כשב, ועי\"ז יוכל להתעלות גם החמץ כי בשבועות הי' מ\"ת. והענין דהנה ארז\"ל כל המשתמש באור תורה אור תורה מחייהו, ובילקוט הגי' טל תורה<sup data-n=\"1605\">13</sup> מחייהו,",[["1602","10","<b>ובזה יובן מהו ההתחדשות דמ\"ת</b>: בהבא לקמן ראה בארוכה לעיל ע' קסג ואילך. וש\"נ."],["1603","11","<b>וזהו מ\"ש אני כברוש רענן</b>: בהבא לקמן ראה לקו\"ת אחרי כו, ב. דרושים ליוהכ\"פ סט, ג."],["1604","12","<b>כבש. . סדר השתל'. . אבל כשב הוא למעלה מסדר השתל'</b>: ראה בארוכה לקו\"ת אמור לז, ב ואילך. לח, סע\"ד ואילך."],["1605","13","<b>והענין דהנה ארז\"ל כל המשתמש באור תורה. . טל תורה</b>: ראה בארוכה סה\"מ תרכ\"ט ע' תז ואילך. [ובהנסמן שם בתחילת המאמר]. סה\"מ תרל\"ב ח\"א ע' קעא. ח\"ב ס\"ע תרעד. ועוד."]]],[2000510480,"כי אור הוא כמ\"ש והי' אור הלבנה כאור החמה ואור החמה יהי' שבעתיים כאור ז' הימים, ופי' רש\"י בפסחים ז' פעמים ז' הרי מ\"ט וז' פעמים מ\"ט הרי שמ\"ג, וזהו מדריגת גשם שבתו', וגשם הוא אתעדל\"ת וזהו אור תורה שהאור יכולים להמשיכו ע\"י אתעדל\"ת, אבל טל<sup data-n=\"1606\">14</sup> תורה הוא טלא דנטיף מעתיקא ואין יכולים להמשיכו ע\"י אתעדל\"ת, וזהו כל המשתמש באור תורה הוא אתעדל\"ת טל תורה מחייהו שמאיליו נמשך אח\"כ, ובשבועות הי' הגילוי מטל תורה ועי\"ז יכול להתעלות גם החמץ.\n<b>ובזה</b> יובן הגמרא בסוטה נידון קברו של משה, דמה שארז\"ל יו\"ד דברים<sup data-n=\"1607\">15</sup> נבראו ערב שבת בין השמשות נת\"ל שכל היו\"ד דברים הם יוצאים מדרכי הטבע כמו פי הארץ ופי הבאר כו', וי\"א אף אילו של יצחק שזהו ג\"כ למעלה מהשגה, וכדי שיבואו לידי בריאה הוא ע\"י ע\"ס דאצי' או ע\"ס הגנוזות והוא ע\"י גילוי האין, וי\"א אף קברו של משה הוא שער החמשים, כי בחייו לא השיג כ\"א מ\"ט שערים, וקודם הסתלקותו השיג השער הנו\"ן ג\"כ עד רום המעלות, והי\"א אף משה בעצמו אינו יודע היכן קבור, הוא כי לאחר הסתלקותו נתעלה למדריגת רישא דלא ידע ולא אתיידע, והגם כי לא ידע ולא כו' מ\"מ הרי הוא נק' בשם רישא, וזהו מפני כי נתינת התורה הי' ע\"י משה ונת\"ל שיש בתורה שני בחי' אור וטל, וע\"י משה ניתן הב' מדריגות דתורה, לכן זכה שנתעלה למדריגת רישא דלא ידע. אך האיך יש בכח הנברא להתעלות כ\"כ, ע\"ז אמרו משה מוטל בכנפי השכינה כי מצד חוק הבורא אין שום מניעה. וי\"א משה לא מת היינו שנתעלה למדריגה גבוה עד שא\"א שם לומר מת. אך האיך יכול להיות שיתעלה הנברא כ\"כ, ע\"ז למדו מויהי שם ארבעים יום והמ' יום הוא ד' יודי\"ן דשם ע\"ב הרי דבחייו היה יכול להתעלות למעלה מעלה ממדריגתו, וכ\"ש לאחר הסתלקותו, אך זהו הכל מפני שהוא מוטל בכנפי השכינה, וזכה משה לזה מפני שהי' מ\"ת על ידו, שתורה הוא תיקון ושבה\"כ הי' בעולם התהו, ותכלית הכוונה ממתן תורה הוא מה שע\"י התורה דתיקון מתבררים ניצוצות דעולם התהו, דבאמת תהו ותיקון שניהם נקראים בשם עולם.\n<b>אמנם</b> לע\"ל כתיב והחרים ה' את לשון מצרים והניף ידו על הנהר בעים רוחו והכהו לז' נחלים, והענין כי מצרים נת' בתו\"א דקאי על עולמות בי\"ע<sup data-n=\"1608\">16</sup> והכוונה לבחי' בי\"ע שעד רום המעלות, והרי א\"ק נק' בשם אדם דבריאה, ומפני כי נק' בשם בריאה לכן נק' בשם מצרים, כי כל מה שנופל עליו שם בריאה נק' בשם מיצר לגבי א\"ס הנעלה ממנו, וים הוא המעלים אורות דאצי', דכמו בפרטיות אצי' יש בחי' ים, כמ\"כ בכללות אצי' יש ג\"כ ים המעלים, וההעלם הוא לצורך גילוי בי\"ע,",[["1606","14","<b>וגשם הוא אתעדל\"ת. . אבל טל</b>: ראה לקו\"ת האזינו עג, א ואילך. עד, ב. עה, ד. עטרת ראש מד, א. סה\"מ תרכ\"ז ע' תסב ואילך. וש\"נ. תרכ\"ט ע' תד ואילך. וש\"נ."],["1607","15","<b>ובזה יובן הגמרא. . דמה שארז\"ל יו\"ד דברים</b>: בהבא לקמן ראה אוה\"ת וירא וביאוה\"ז להצ\"צ שם."],["1608","16","<b>מצרים נת' בתו\"א דקאי על עולמות בי\"ע</b>: תו\"א בשלח סה, סע\"ג-ד."]]],[2000510481,"ולכן והחרים לשון ים מצרים היינו כל מה שנוכל לומר עליו ים מצרים וההוי' דסדר השתלשלות, וכ\"ז יחרים ה' שלמעלה מסדר השתלשלות, כי והחרים הוא ע\"ד כל חרם לה' יהי', היינו להוי' שלמעלה מסדר השתלשלות. ואז יהי' והניף ידו על הנהר ג\"כ, כי נהר הוא בינה שהוא מקור ההשגה, כי חכ' הוא ברק המבריק שהוא למעלה מהשגה אבל בינה הוא השגה ונש\"י יתעלו למדריגות שלמעלה מהשגה ולגבי זה השגה מבלבל. ויובן זה ע\"ד מה שצם ר\"ז מאה תעניתא<sup data-n=\"1609\">17</sup> כי היכא דלשכח תלמוד בבלי ממנו, מפני שאין תורה כתורת א\"י ולכן בבלי מבלבל לגבי השגת ירושלמי, ולכן צם בכדי שלא יהי' כח הזוכר כלל, וע\"ד מה שכדי שתוכל הנשמה להתעלות מגעה\"ת לגעה\"ע נצרך להיות טבילה בנהר דינור<sup data-n=\"1610\">18</sup>, הגם כי געה\"ת הוא ג\"כ מדריגה גבוה, אך לגבי געה\"ע מבלבל זאת ההשגה, כמו\"כ לגבי המדריגה שיתעלו נש\"י יהי' ההשגה מבלבל, ולכן והניף ידו על הנהר. אך ההנפה יהי' בידו, כי ידו הוא כמ\"ש ימינך כו' ימינך כו' שכולו ימין לית שמאלא בהאי ע\"ק. וזהו ההפרש בין קרי\"ס, כי בקרי\"ס הי' ע\"י מטה היינו לרדות בו פרעה כמ\"ש במד\"ר מה דרכו של כלב ללקות במקל, כך הקב\"ה אין רודה את הרשעים אלא במקל, אבל לע\"ל לא יצטרכו למטה כ\"א והניף ידו, ומ\"ש על לע\"ל מטה עוזך כו' היינו ממשלה ומ\"ש ורדה היינו ג\"כ מלשון ממשלה.\n<b>ובזה</b> יתורץ ג\"כ למה והחרים על ים מצרים וההנפה על הנהר, דממ\"נ או דההנפה וההחרמה היה נצטרך להיות על הנהר, או שניהם על ים מצרים, אך דמפני שוהניף ידו על הנהר דהיינו גילוי ע\"ק שהוא למעלה מההשגה ולכן והניף על הנהר שהוא השגה, משא\"כ והחרים קאי על ים מצרים כללות השתלשלות. וזהו שאמר במד\"ר ע\"פ הבל הבלים אמר קהלת דקאי על שבעה ימי בראשית שהוא הכל הבל, דכל מה שנברא בששת ימי בראשית עתידין לבלות וחשיב שם בשלישי יקוו המים ולע\"ל כתיב והחרים לשון ים מצרים, כי לגבי הגילוי העצום דלע\"ל נק' כל כללות סדר השתל' בשם הבל, הגם כי הוא מדריגה גבוה מאד מ\"מ נק' בשם הבל, וזהו והניף ידו על הנהר בינה השגה. אך צ\"ל מ\"ש והכהו לז' נחלים האיך שייך שם גדר מספר, ולמה לע\"ל יהי' דוקא לז' נחלים הלא בקרי\"ס הי' לי\"ב גזרים. אך הוא עדמ\"ש והיה מספר בני ישראל אשר לא יספר, שנק' מספר ע\"ש זה שאם הי' בא לידי גילוי הי' מתהווה ממנו למטה מספר בריבוי מאד, וכן על לע\"ל כתיב ועמדו רגליו ביום ההוא על הר הזיתים שנת' במ\"א הפי' כי רגליו הוא אותיות<sup data-n=\"1611\">19</sup>, דהיינו שיהי' עליות העולמות למדריגה גבוה אשר א\"א לקרות אותו כ\"א בשם אותיות, ואם הי' מתגלה קצת דקצת ממנו הי' מתהווה ממנו ריבוא רבבות עולמות עד אין שיעור.",[["1609","17","<b>ויובן זה ע\"ד מה שצם ר\"ז מאה תעניתא</b>: בהבא לקמן ראה תו\"א יתרו סט, ג. מאמרי אדה\"ז תקס\"ו ע' רטו. מאמרי אדהאמ\"צ במדבר ח\"ב ע' תמא. וש\"נ. סה\"מ תרל\"ג ח\"ב ע' תכא. ועוד."],["1610","18","<b>שתוכל הנשמה להתעלות. . טבילה. . בנהר דינור</b>: ראה בכ\"ז תו\"א מקץ לא, א. לב, ד. מג\"א צו, א. [ובהנסמן בהע' שלפנ\"ז]."],["1611","19","<b>ועמדו רגליו. . שנת' במ\"א. . רגליו הוא אותיות</b>: מאמרי אדה\"ז תקע\"א ע' נז ואילך. נביאים ע' רנח ואילך. סה\"מ תרכ\"ז ס\"ע ק ואילך. תר\"ל ס\"ע שכא ואילך. ועוד."]]],[2000510482,"<b>ועד\"ז</b> הפי' ג\"כ כאן שהוא מדריגה שהוא למעלה מגדר מספר. אך מ\"מ בהתגלותו יהי' במספר ז' כי הגילוי יהי' לבנ\"י ובנ\"י הם בנים דישראל סבא עד רום המעלות ובנ\"י הוא מדות ומספר המדות הוא ז', ואז יקבלו מלמעלה מבינה, ועל הנהר דבינה יהי' ההנפה לכן והכהו לז' נחלים, אבל בקרי\"ס הי' לי\"ב גזרים כי הגילוי דקי\"ס הי' שיתחבר בריאה עם אצי' והגילוי הי' בכדי שיתעלו י\"ב שבטים דבריאה לי\"ב גבולי אלכסון דאצי' כמ\"ש ששם עלו שבטים דבריאה שבטי י\"ה כמו שהוא באצי', וכמ\"ש י\"ב בקר והים עומד עליהם, ולכן נקרע הים לי\"ב גזרים בכדי שכל שבט יעלה במסילתו, אבל לע\"ל יהי' גילוי כללות שלמעלה מעלה מהתחלקות ואין שייך שם שום התחלקות שבטים לכן יהי' לז' נחלים. אך איך יהי' הגילוי בזה פליגי רש\"י והת\"י דרש\"י פי' לז' גזרים הוא שיהי' עליות מלמטלמ\"ע, והת\"י מפרש ז' נחלין היינו שיהי' גילוי מלמעלמ\"ט, דכמו בקרי\"ס פליגי הזהר והאריז\"ל האיך הי' הגילוי, אם נתגלה אצי' בבי\"ע או בי\"ע נתעלה לאצי', כמ\"כ פליגי רש\"י והת\"י בהגילוי דלע\"ל ג\"כ. ואז יהי' והדריך בנעלים, כי ענין נעל נתבאר בלק\"ת שהוא נעל דשכינתא<sup data-n=\"1612\">20</sup>, דהיינו שכדי שיוכל להיות נבראים מוגבלים הוא ע\"י מלאכים הנק' בשם נעל, דהיינו שכמו שהנעל חופה על הרגל שלא יתגלה, כמו\"כ הם חופים לאור מדות דאצי' שלא יתגלו כמו שהן, ועי\"ז מתהווים בע\"ג, ובנ\"י ידריכו לע\"ל ע\"ז הנעלים כי יתעלו למעלה מעלה מהם, והענין דהנה אי' בזהר הרקיע שיש כדוגמת עתיק לעילא מן גלגלתא דא\"ק, ונק' בשם אצי' לגבי א\"ק שנק' בשם אדם דבריאה, וכשנופל עליו שם אצי' ממילא יש שם ים ונהר ושם יהי' ההנפה על הנהר ובנ\"י יתעלו למדריגה זו, לכן והדריך בנעלים שהם ידרכו על הנעלים ועי\"ז והי' מסילה לשאר עמו. ובזה יובן ג\"כ מה שמדקדק רש\"י ע\"פ והי' ביום ההוא יוסיף כו' מאשור ומפתרוס שאינו כ\"א ז' גליות דהיינו דע\"י בירור ז' מדות היינו ע' לשון בזמן הגלות עי\"ז יזכו להגילוי העצום דז' נחלים.",[["1612","20","<b>ענין נעל נתבאר בלק\"ת שהוא נעל דשכינתא</b>: לקו\"ת שה\"ש מג, ג ואילך. וראה גם לקו\"ת חוקת סד, ב. שה\"ש כה, א.\n<br>"]]],[2000510488,"<h3>פתח דבר לד\"ה ויקח ה\"א</h3>\n<b>ב\"ה.\nפתח דבר</b>\nלד\"ה ויקח ה\"א תרל\"א —\nלקראת י\"ג תשרי, יום ההילולא של כ\"ק אדמו\"ר מהר\"ש נ\"ע, הננו מוציאים לאור — בפעם הראשונה — מאמר ד\"ה ויקח ה' אלקים את האדם גו', מאת כ\"ק אדמו\"ר מהר\"ש, שאמר בש\"פ בראשית תרל\"א.\n<b>המאמר</b> נמצא בכת\"י מעתיק הידוע ר' שמואל סופר, עם תיקונים והערות בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש.\n<b>מאמר</b> זה הוא תדפיס מתוך הספר \"לקוטי תורה תורת שמואל — תרל\"א\", הנמצא בדפוס.\nלתועלת הלומדים הוספנו כמה הערות וציונים מהמו\"ל.\nמערכת \"אוצר החסידים\"\nו' תשרי<sup data-n=\"e91\">*</sup>, ה'תשס\"ד\nמאה ואחת שנה להולדת כ\"ק אדמו\"ר זי\"ע וג\"ן שנה לנשיאותו\nברוקלין, נ.י.\n\n<br>",[["e91","*","_<b>יום הי רצייט-הילולא של הרבנית הצדקנית מרת חנה ע\"ה זי\"ע — אמו של כ\"ק אדמו\"ר זי\"ע. וראה תורת מנחם-התוועדויות תנש\"א ח\"ב ע' 175</b>: ”שאמי מורתי ע\"ה היתה מעתיקה — בדיוק ובמהירות — מאמרי חסידות שהיו מגיעים בבית אבי' (חסיד עוד מאדמו\"ר מהר\"ש), כפי שהי' נהוג בזמנים ההם, שהמתינו וציפו שיגיע מאמר חסידות מליוב„וויטש, והיו מעתיקים אותו ובכמה העתקות וכו'\"."]]],[2000580076,"<h3>ויברך אלקים את יום השביעי</h3>\n<b></b><b>בס\"ד, ש\"פ בראשית, ל\"ב (רשומי דברים בקצרה).</b>\nבראשית\n<b>ויברך</b> אלקי' את יום השביעי ויקדש אותו כי בו שבת כו' אשר ברא וגו', וצ\"ל מהו נתינת הטעם כי בו שבת על שברכו וקדשו, והלא ביום וא\"ו בבריאת האדם נא' ג\"כ ברכה גם כשעדיין לא שבת כו', ובמד\"ר פי\"א ברכו באור פניו של אדם וקדשו כו' לא דומה כו', וצ\"ל מהו ענין אם הפנים מאיר ביותר א\"ל.\n<b>ולהבין</b> זה צ\"ל למה השבת אינו נק' ראש כמו ר\"ח שכולל ל' יום והוא הראש, וכן ר\"ה כולל וראש כל השנה, וכן שבת צ\"ל ראש השבוע, וצריך להבין ההפרש בין ר\"ח לשבת. ויובן בהקדם ענין מ\"ש ויהי ערב ויהי בקר שהוא בחי' חשך ואור כמ\"ש ויקרא וגו' ולחשך קרא לילה, והנה אור הוא חסד כמ\"ש כי טוב חסדך מחיים וכתי' את האור כי טוב, וענין האור הוא שמאיר למרחוק דוקא, וע\"ד הלבנה שמארת אותה כשמתרחקת מן השמש, וכן זיו השמש עצמה נראה אורה בהאירה על הארץ דוקא, להיות כי בארץ אין שם מאור השמש עצמה.\n<b>ועד\"ז</b> יובן בעבודה בנפש האדם דכתי' ואהבת הוא בגימ' ב\"פ אור שהוא חסד, וזה נמשך ע\"י התבוננות ברוך שם כבוד מלכותו לעולם ועד, שם, כבוד, מל', הארה דהארה דהארה, שם הוא הארה, ובחי' כבוד שהוא ג\"כ לבוש כמארז\"ל ר\"י קארי למאנא מכבדותא אמנם זהו לבוש והארת ל\"ב נ\"ח כבוד גימ' ל\"ב, וכמו שאנו רואי' שהלבושי' מעלי' וכמשל הגשמי שע\"י הלבושי' ממשיכי' הגוף, וכן ח\"ו בהיפך מלבושי כבוד כמ\"ש בלק\"ת בד\"ה כי ביום הזה יכפר שבפ' אחרי, ומל' הוא"],[2000580077,"ג\"כ התפשטות שמו, אמנם פועל רוממות בעצמותו שהרי המלך אין רואין אותו כשהוא מסתפר וכשהוא ערום כמארז\"ל בפ\"ב דסנהדרין, ונמצא מובן איך שהם הארה דהארה דהארה, וה\"ז הוא הפלגת הריחוק כו' והוא בחי' יחו\"ת, אמנם אחד הוא בחי' יחו\"ע שלמעלה מאהבה כ\"א ביטול לגמרי, ולכן ארז\"ל מן שמע עד אחד בעמידה (ע' בתוס' ברכות די\"ג ע\"ב), ואהבת יכול לילך, והיינו שהילוך הוא בחי' אור, אבל ענין העמידה הוא ביטול, ופי' יחו\"ע הוא עד\"מ אור וזיו השמש כמו שהוא במאור השמש שאז אינו עולה בשם כלל, ואינו נק' בשם אור, ובחי' ומדריגה זו הוא בחי' יצחק דכתי' בי' ותכהינה עיניו מראות שהוא בחי' החשך בחי' ביטול לגמרי, וכן בק\"ש צריך להעביר ידיו ע\"ג עיניו בפסוק ראשון בחי' חשך וכענין עולמתא שפירתא דלית לה עיינין, ולכן ברכת ק\"ש מתחילין יוצר אור ובורא חשך, ופי' האריז\"ל ובורא חשך ימשמש בתפילין של ראש הרי החשך גבוה מהאור כו', ובכל יום בק\"ש צ\"ל ב' בחי' אחד ואהבת, חשך ואור שז\"ע יצחק ואברהם, אברהם הוא בחי' אברהם אוהבי, ויצחק ותכהינה ביטול מס\"נ שלמעלה מטו\"ד והוא ממעל לעצים עץ החיים ועץ הדעת כו', ולכן אין הלכה כאנשי יריחו כו' כ\"א צריכין להפסיק בשכמל\"ו, ועד\"ז בר\"ח העלאה ואח\"כ המשכה, וזהו קרבן דר\"ח פרים בני בקר שנים רצוא ושוב, שלא יהי' יניקה מב' הבחי' כי ע' שרים מקבלי' מחו\"ג ישמעאל באהבה ועשו ביראה, וזהו דכתי' ובראשי תרין ראשין, וכנגד זה החשך והאור בלבנה.\n<b>והנה</b> לע\"ל יאמרו ליצחק כי אתה אבינו וה\"ז בחי' חשך, ויובן בהקדם ענין שבת שאז כתי' ויכולו השמים והארץ, ואז גילוי התענוג כו' אך מי שטרח בערב שבת ביטול היש יבוא בשבת לביטול אמיתי בירור שני, והיינו ע\"י ההמשכה מלמעלה תענוג נשמה יתירה, ואח\"כ העלאה במקור התענוג, וזהו ב' שבתות כהלכתן אברהם ויצחק, כי יצחק הוא בחי' צחוק ותענוג כו' הוא ההעלאה מקור התענוג, וז\"ש יעקב אם יהי' אלקי' עמדי כו' ושבתי כו' והי' ה' לי לאלקי' גילוי בחי' יצחק, נמצא בשבת שהוא אותיות תשב עליות העולמות העיקר בחי' יצחק תענוג עליון, ור\"ח אברהם השפעה וחסד להחיות העולמות כנ\"ל."],[2000580078,"<b>ועפ\"ז</b> יובן למה לא נק' שבת ראש, כי הראש כולל והתחלה לל' יום עד\"מ, שהוא המקור לל' יום שבאי' אח\"כ, וכן ר\"ה לכל השנה וה\"ז כלל לפרט כמו מאמר דבראשית שכולל עשרה מאמרות היינו גם ט' מאמרות פרטי' שבאי' אח\"כ, או כמו מח' לריבוי הדבור שאח\"כ, אבל שבת הוא שביתה ועליי' בלמעלה מהזמן לגמרי, ואיך שייך לומר שכולל ז' ימי' שאח\"כ, הלא זהו עלי' בלמעלה מן הזמן לגמרי, ולכן ארז\"ל ר\"ח להבא וכן ר\"ה, אבל שבת ושביעית שעברה והיינו כי אחר ששת ימי בראשית הוא שבת, ולכן ארז\"ל מונה ששה ימי' ושובת, וא\"כ שבת הוא בחי' יצחק וזהו ל' צחוק ותענוג וצחוק עשה לי אלקי', ולכן השבת הוא כי בו שבת לפי שויכל אלקי' כו' מכל מלאכתו, והגילוי דר\"ח הוא אברהם, וכן בר\"ה והוכן בחסד כסאו בחי' אברהם אתקין לכורסייא. אך קודם הגילוי צ\"ל עלי' וז\"ע ער\"ח דכתי' מחר חדש כו' כי יפקד מושבך, והיינו ההעדר שזהו חשך דיצחק כו', וי\"ל שההעדר שבסוף הוא העלאה שעי\"ז נמשך בר\"ח עוד בחי' עליונה יותר, ואח\"כ נעשה עוד העלאה יצחק חשך כו', ובערב ובקר צריך לומר שהחשך שקדם זהו ע\"ד סוף מעשה במח' תחלה כו'.\n<b>ואמנם</b> צ\"ל א\"כ מהו מעלת השבת היתכן שהוא בחי' חשך ח\"ו, אך הענין דיש ב' בחי' עליות, עד\"מ בשינה עליות הנשמה בצדיקי' בידך אפקיד רוחי שהנשמה מתעלית למקורה לבחי' ואתה נפחת בי ויפח כו' מאן דנפח כו', ומשגת שם מה שאינה משגת בגוף, ועכ\"ז לגבי הגוף ה\"ז חשך יותר, ויש צדיקי' משיגים קצת ע\"י החלום, ועכ\"ז אינו גילוי גמור משא\"כ בחי' נבואה שהיא ג\"כ עליי' והיינו שהגוף מזדכך ג\"כ עד שעולה ג\"כ בעלות הנשמה ואינו יורד בבחי' שינה, וע\"ד אלי' שעלה בסערה גם גופו, וכן כתי' ורוח אלקי' ישאך כו' וה\"ז לגבי ההשגה שבחלום כמו אור לגבי חשך, וז\"ש בחלום אדבר בו לא כן עבדי משה כו' פא\"פ כו' ומראה ולא בחידות, ותמונת כו'.\n<b>ועד\"ז</b> יובן החילוק בין עלי' דר\"ח ור\"ה לשבת, שר\"ח ור\"ה העלי' רק בפנימיות בהאור אבל למטה נשאר חשך, אבל בשבת העליות הוא בבחי' הגוף והכלי' וה\"ז אור גדול ולא חשך, ועד\"ז יאמרו לע\"ל ליצחק כי אתה אבינו, וזה יהי' ג\"כ בלבנה לע\"ל שתתעלה מעלה מעלה גם בחיצוניות ולא יהי' חשך למטה ח\"ו, ובחי'"],[2000580079,"השמש הוא דרך המשכה, וזהו בחי' אברהם ויצחק ב' בחי' שמש ושמתי כדכד שמשותיך, חמה ולבנה, מאחר שאור הלבנה יהי' כמו אור החמה וזה עד דוד הגדיל, וזהו ואהבת ב\"פ אור, ועד\"ז רצו אנשי יריחו להיות או\"ח ואהבת מבחי' אחד, יריחו ל' ריח חדש לבנה, אמנם זה יהי' לע\"ל ע\"י העבודה דעכשיו בשכמל\"ו בחי' ריחוק, וגם זה יתקרב ע\"י שבכל שבת ושבת ויכל אלקי' בחי' הצחוק שנעשה מבחי' ש' אלקי' כו'.\n<b>וזהו</b> ענין ברכו באור פניו של אדם וקדשו כו', והיינו בהיות נודע כי מקור הראשון לברה\"ע הוא מבחי' המדות וכמ\"ש כי אמרתי עולם חסד יבנה, וז\"ע ששת ימי' עשה שהששת ימים הם ז' מדות, עשה שנשפלו בבחי' דיבור שנק' מעשה, וכנודע כי דבורו של הקב\"ה חשיב מעשה, ובכלל זה גם המוחין שבמדות כו', ולאחר ששבת ונתעלו המדות ומוחין שבמדות לשרשם, אז ברכו וקדשו שהוא בחי' המשכת חו\"ב דאצי' עצמן וניכר זה באור פניו ע\"ד חכמת אדם תאיר פניו, וכתי' יאר ה' פניו אליך כו', והטעם הוא להיות כי שבת מכל אשר ברא ותחלה נא' מכל אשר עשה, והיינו שזהו נגד ג' בחי' אדם דכלליות שהם בי\"ע דכלליות, ולכן להיות כי שבת גם מכל אשר ברא ג\"כ שנכלל בזה גם אדם דבריאה, לכן נתגלה אז הארת אצי' העליון דכלליות, וזהו ברכו וקדשו כו', ולכן ויברך כו' ויקדש מפני ששבת מכל אשר ברא כו'."],[2000580080,"<h3>עשה לך תיבת עצי גופר</h3>\n<b>(בס\"ד. ש\"פ נח רל\"ב).</b>\n<b>עשה</b> לך תיבת עצי גופר קנים, וארז\"ל במד\"ר פל\"א ל\"ג א' קנים קולין ומדורין אמר ר' יצחק מה הקן (דרש קנים ל' קן צפור) מטהר את המצורע אף תיבתך מטהרתך (י\"ל לבוא לבחי' טהורה היא שורש הנשמה, וכשבא לזה ובקע חושך הגוף ה\"ז מים חיים שגבוה יותר מבחי' כמו שהי' הנשמה קודם התלבשותה בגוף, וזהו ע\"י עיכוב בתיבה י\"ב חודש עיבור שני), פי' קן מדור העוף, קן צפור, דרור קן לה, יעיר קנו, וכן מדורי התיבה נק' קנים, ובמאו\"א אות קו\"ף סל\"ג קן"],[2000580081,"בינה קן והיכל לחכ', שכינתא עילאה היכל קדש הקדשים, שמשם נמשך יכפר כו' תטהרו, והיינו כי ע\"י המצות פוגמי' בבחי' קודש סוכ\"ע, והכפרה מבחי' קדש הקדשים בד\"ה שבת שבתון. ועד\"ז יובן בעבודה מצורע מוציא שם רע, וכן נח לא ביקש עבור אנשי דורו, וכמו שקרבן צפור מטהר את המצורע כן התיבה בינה יובלא דרור קדש הקדשים מטהרתך, ועי\"ז נמשך הכפרה וזהו וכפרת אותה ע\"ד כי ביום הזה יכפר.\n<b>ופי'</b> וענין עצי גופר ארז\"ל בסנהדרין ק\"ח ב' אמרי דבי ר' שילא זו מבליגה, פרש\"י עץ הוא, ואמרי לה גולמיש, ובפ\"ב דר\"ה ך\"ג א' כלונסאות של ארז, ארז קתרוס, מאי קתרוס מבליגא ואמרי לה זו גולמיש, הרי שזהו מין ארז, והיינו כי להגן על הצדיק שהרי לא חטא רק מה שלא ביקש על אנשי דורו, אבל צדיק תמים הי', נמשך ההגנה מבחי' ארז כמ\"ש צדיק כתמר כו' כארז, ואם שהוא מין ארז מ\"מ ה\"ה קל לשוט על פני המים כמ\"ש במכלול.\n<b>והענין</b> הוא דהספינה היא הממוצע להוביל את האדם במים, ים ויבשה עלמא דאתכסיא ועלמא דאתגליא, והעבודה בתומ\"צ הוא להמשיך מעלמא דאתכסי' בעלמא דאתגלי', ע\"ד וידגו לרוב בקרב הארץ, וזהו ע\"י המצות שנק' ארבין כמ\"ש בבה\"ז פ' בשלח, והיינו כמו שהספינה היא ממוצע כן מעשה המצות הם ממוצעי' להיות נמשך בהם ועל ידם המשכת אלקות, והם נעשי' לבושי' לנפש שתוכל הנפש להשיג השגות אלקות, כמו הספינה שהיא ג\"כ לבוש לאדם רק זהו ע\"ד בית, מ\"מ ה\"ה ממוצע בינו למים. וז\"ש מחקק ספון, מחקק גימ' רמ\"ח, ספון מל' ספינה, וענין לבוש זהו ע\"ד ויבא משה בתוך הענן וע\"ד משל לבוא לחכ' השכל, כך הארבין הם ממוצעי' לילך בהם במים שאין להם סוף, ולכן עשה לך שנח שהי' צדיק הי' יכול לעשות הלבושי' לנר\"נ לשוט בהם במים שאין להם סוף.\n<b>ובעבודה</b> דנה\"א כשם שע\"י המצות שנק' ארבין יכול לשוט במים שאין להם סוף הוא בחי' מל', שכתר מל' הוא ממל' שבכתר לכן הוא א\"ס, כן מגיני ומצלי מלעו\"ז, שהוא מים רבי' טרדות הפרנסה, וכשמעמיק בהם ואומר כוחי ועוצם"],[2000580082,"ידי, הרי כמו שע\"י תומ\"צ נפש אדוני צרורה בצרור החיים, כן להיפך נפש אויבך יקלענה היא הקליעה למרחוק מאד שא\"ס להתרחקותו, וההולך בהם הוא ע\"י המצות שכאשר מכוין במסחרו למען ירויח ויוכל לפרנס בניו וב\"ב ויתן צדקה לעני ויתעסק בגמ\"ח בין לעני בין לעשיר, אז הוא מעלה מסחר הגשמי, ונמצא כי בהם ועל ידם הולך במים רבים ואינו נטבע בהם (פי' טביעה הוא שמאבד חיותו כו') ואדרבה מעלה אותם כו'.\n<b>אמנם</b> מי שכבר נמשך בהם ח\"ו, ה\"ה צריך לתיבה שפי' אדמ\"ו תיבה היא תיבת התפילה ותיבת התורה שהם בחי' תשובה מלמטלמ\"ע ותשובה מלמעלמ\"ט, ועי\"ז נמשך וכפרת אותה מבית ומחוץ שהוא בבחי' פנימי' וחיצוניות, והיינו ע\"י קלא פנימאה דלא אשתמע וקלא דאשתמע, הקל קול תפילה ותורה, ועי\"ז נמשך וכפרת ל' יכפר.\n<b>תוכן</b> הענין שהצדיק יכול להמשיך ע\"י התיבה מעשה המצות שנק' ארחין, וצ\"ל תמים תוכו כברו ע\"ד הספינה שצריכה שתהי' בלא נקב, אבל מי שפגם צריך לתשובה מעומקא דליבא, וע\"י התורה ותפלה שהם קלא פנימאה וקלא דאשתמע, עי\"ז נמשך וכפרת כי ביום הזה יכפר כו', תיבתך מטהרתך הוא בחי' תטהרו."],[2000580083,"<h3>אנכי מגן לך</h3>\n<b>בס\"ד, ש\"פ לך, ל\"ב.</b>\nרשומי דברים בקצרה.\n<b>אנכי</b> מגן לך שכרך הרבה מאד, וצ\"ל קישור וחיבור אנכי מגן לשכרך הרבה, בעקרי' מ\"ד פל\"ו פי' שע\"פ שורת הדין הי' מחויב שהשכר יהי' רק זמניי אלא שמחסד השי\"ת שהוא רב חסד לכן יהי' השכר נצחיי."],[2000580084,"<b>והענין</b> הוא דהנה במד\"ר במקומו רפמ\"ד העירו מפסוק אמרת ה' צרופה מגן הוא לכל החוסי' בו, רב א' לא ניתנו המצות אלא לצרף בהם את הבריות, וכי מה איכפת כו' אלא כו', ומשמע שעי\"ז נעשה לו מגן שע\"י צרופה הצירוף דמצות נעשה מגן כו', ואח\"כ דרש זה על אברהם צרופה שצירפו בכבשן האש, מגן אנכי מגן לך.\n<b>והענין</b> הוא דהנה קיים אברהם כו' וא\"כ מהו ההתחדשות ממ\"ת, אך הענין הוא שההפרש הוא בשני דברי', הא' שאברהם קיים ע\"י מס\"נ בפועל ממש ובהתקשרות עצומה עד שאמרה מדת החסד כו' שהרי אברם כו', ובס' ארחות צדיקים שהי' נדיב בכל הג' דברי', אבל במ\"ת שניתנו המצות הנה ע\"י קיום המצות ממשיכי' כו'. שני' אם שאברהם קיים במס\"נ, מ\"מ לא הי' יכול להגיע בעבודתו מצ\"ע למעלה משורש הנבראי', והראי' מעין עיטם שהי' גבוה מקרקע העזרה ך\"ג אמה, וא\"כ גם ע\"י מס\"נ לא הי' מגיע למעלה משורש הנבראי' אבל ע\"י המצות אשר קדשנו במצותיו, אשר תענוג, וקדשנו בקדש העליון במצותיו שהוא מקיים, ולכן ארז\"ל ע\"פ שמן תורק כל המצוות שעשו האבות ריחות היו אבל אנו שמן תורק שמריקין כו', ונמצא כי ההפרש הוא בשני דברי'.\n<b>אמנם</b> כ\"ז הוא ע\"פ שורת הדין אבל מחסד הקב\"ה שהוא רב חסד לכן גם שכר אברהם הוא נצחי, וזהו שכרך הרבה מאד שהוא נצחי שזהו ריבוי שאין כמוהו היינו לפי שאנכי מגן לך שמבחי' אנכי נמשך לך להיות מגן, כמו שע\"י קיום המצות נמשך מבחי' תענוג אשר קדשנו במצותיו, בחי' אנכי מי שאנכי, כן לך הגם שאתה מקיים המצות בעבודתך שהיא גבולי מ\"מ יומשך לך מגן מבחי' אנכי, והטעם"],[2000580085,"הוא ע\"י שנצרף בעשרה נסיונות, שענין הנסיון הוא כי מנסה ה' אתכם שזהו מחמת ההסתר, ודרך רשעים צלחה, ומ\"מ אל יהרהרו מאומה ולהתנהג בדרך הטוב והישר, ועי\"ז מתברר מה שנפל בשבירת הכלים, וכל המקיים את התורה מעוני סופו כו', ולכן אברהם ע\"י שנתנסה בעשרה נסיונות הוא בחי' הצירוף שעי\"ז זכה לבחי' המגן כמו שע\"י מעשה המצות שהם ג\"כ רק לצרף כי וכי איכפת לי', היינו לפי שקמי' ית' כחשוכא כאורה בשני כפי\"ן שגם האור שוה לחשך, אלא לצרף שזהו ענין הנסיון שמנסה כו' לדעת הישכם אוהבי' הוא בחי' דעת שנחלק לחו\"ג מ\"ע ומל\"ת, וזהו בחי' מ\"ת שניתן במתנה כן באברהם ע\"י הנסיון במס\"נ בפועל ממש זכה ג\"כ למגן שנמשך מבחי' אנכי.\n<b>וביאור</b> הענין הנה כתי' כמגדל דוד כו' אלף המגן פי' אלף המגן, כשנמשך מגן לאלף דור ה\"ז נצחי, וכמו ועושה ונוצר חסד לאלפי' כו', וזהו בחי' מגדל דוד, ע\"ד ואעשך לגוי גדול א\"ל ומנח לא העמדתי ע' אומות, אותו שכתי' בו כי מי גוי גדול ממך אני מעמיד. והענין הוא דכתי' הבט משמים וראה, שמים אש ומים, תורה בחי' חכ' עילאה, ועי\"ז וברך את עמך ישראל שעי\"ז אנו עם בנ\"י נתראים לפניו לדבר חשוב, וזהו ומי גוי גדול, וע\"י מה הוא הגדלות לפי שע\"י התורה ממשיכי' בחי' גדול הוי' וכמ\"ש ואתם הדבקי' בהוי', ולכן אלקי' קרובי' אליו כמ\"ש במד\"ר במקומו, וההמשכה הוא בעיר אלקינו. וזהו כמגדל דוד בחי' מל' עיר אלקינו שנעשה ג\"כ גדול מחמת המשכת גדול הוי' בה.\n<b>וזהו</b> אלף המגן פי' ברבות על משה שהי' לאלף דור עם התתקע\"ד דור שקמטו, ועל ידו נמשך המגן מבחי' אנכי מי שאנכי, והיינו ע\"י הצירוף דמעשה המצות כן ע\"י הצירוף שנצרף אברהם בעשרה נסיונות אמר לו אנכי מגן לך שגם לך יומשך המגן מבחי' אנכי מי שאנכי, וזהו שכרך הרבה מאד בלי גבול, כמו שהמצות הם בלי סיקוס רחבה מצותך מאד כמ\"ש באגה\"ק, ולפ\"ז צ\"ל מ\"ש ריחות היו זהו מצד עצמן אבל מחסד ה' אנכי מגן לך שזהו מאד נצחי כו'."],[2000580086,"<h3>יפה שעה אחת</h3>\n<b></b>מאמר זה לא נרשם בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש, ונמצא רק הנחה מהמאמר, ונדפס לקמן בחלק ההנחות"],[2000580087,"<h3>ויקח לו יעקב מקל לבנה</h3>\n<b></b><b>(בס\"ד. ש\"פ ויצא, ל\"ב).</b>\nויצא\n<b>ויקח</b> לו יעקב מקל לבנה לח וגו' ותלדנה הצאן עקודי' נקודי' וברודי', ויתן פני הצאן אל עקוד. וצ\"ל איך בירר יעקב מצאן לבן עקודי' נקודי' וברודי' שפי' האריז\"ל שהם עולמות שלמעלה מאצי'. והענין דהנה עקודים נקודים וברודים הם בי\"ע דכלליות, ובזח\"א קס\"א ב' פי' פסוק ויקח לו יעקב, ותוכן הענין שבחר לו מדת הת\"ת קו האמצעי בריח התיכון המבריח מן הקצה אל הקצה שממשיך בו אור הכתר ועי\"ז מחבר חו\"ג, והמשיך אור זה למל' בכדי שיתברך בי\"ע.\n<b>וביאור</b> הענין יובן בהקדם מ\"ש וזרעתי את בית ישראל זרע אדם וזרע בהמה, זרע אדם הם הנשמות הגבוהות שמבחי' אדם בצלמינו, ונק' בנים למקום וכמו מעלת האדם הרגשה כך נשמו' אלו יש להם דעת, ואין הפי' ידיעה אלא הרגשה, וזרע בהמה הם הנשמות שאין להם דעת כ\"כ שבדורותינו אלה, כי בני עלי' מועטי' גם בדורות הראשונים, ואין הפי' שאין להם דעת כ\"א הגם שיודעי' מפי ספרי' וסופרי' איך שמחי' ומהוה ולגדולתו אין חקר מ\"מ אינו מורגש בבחי' דעת שלם ה\"ז זרע בהמה שהרי הבהמה רואה ושומעת ג\"כ, מ\"מ אינה מבנת מפני שאין לה דעת כ\"כ, וכך נשמות אלו הגם שיודעי' אין זה בבחי' הרגשה והתקשרות, כי דעת מל' והאדם ידע. ומבשרי אחזה כאילו רואה."],[2000580088,"<b>והגם</b> שא\"א לראות אלקותו ית' בעין הגשמי מ\"מ ה\"ה ע\"ד מאדם יודע ומרגיש חיות נפשו הגם כי לא ראה אותה מעולם מ\"מ מרגיש, והרי בצאת כו' וגם בחייו לא כל העיתי' שוי' שהרי בעת השינה מתדמה לו דברי' הפכי' שבהקיצו משנתו הוא מתפלא ע\"ז, והיינו מפני שבשינה רק קיסטא דחיותא, וכשניעור שב חיות נפשו וה\"ז מורגש היטיב. ועד\"ז הוא הדעת באלקות הגם דלית מח' תפיסא בי' כלל, אבל מציאותו נודע ונרגש שהעולם גוף גדול וחיים וקיימי' מאוא\"ס בכל עת ובכל רגע, וכשהוא מרגיש כאילו רואה התהות היש מאין, וע\"ז אמרו איזהו חכם הרואה את הנולד מאין ליש, ועז\"נ וה' עליהם יראה בחי' ראי' והרגשה, אבל כשאין השכלה זו בבחי' הרגשה ה\"ז זרע בהמה, והגם שכל ישראל מאמיני' בני מאמינים והאמונה למע' מן הדעת, מ\"מ ה\"ה רק בבחי' מקיף, וצ\"ל דעת כמ\"ש דע כו' ועבדהו כי ע\"י הדעת מורגש ואין העולם מסתיר, וגם האהבה ויראה הבאה מבחי' דעת כאילו רואה אין ערוך אלי'.\n<b>ולכן</b> הסתכל בשלשה דברים, הסתכל דוקא, כמו אדם הרואה איזה דבר טוב או הפוכה ח\"ו הגם שהוא רחוק הזמן מ\"מ מתיירא אם רע ח\"ו ושמח אם טוב, אבל בבחי' שמיעה אזי לא תפול עליו היראה כ\"כ וכן השמחה, והיינו מפני שאינו בהתגלות כ\"כ, וזהו אינו דומה שמיעה לראי', שכשיראה ד\"ז עצמו ששמע מתפעל באופן אחר כו', ולכן אמרו הסתכל, וההפרש כשהוא בבחי' שמיעה אזי כשיסיר לפי רגע פונה לדרך תאותו אבל כשהוא בבחי' ראי' והתגלות בחי' הסתכל אזי אי אתה בא כו', נמצא חכ' ראי', ובינה שמיעה, ואבא מקננא באצי' ואימא בבריאה, ולכן הנשמות דבי\"ע אין להם ראי' ונק' זרע בהמה, משא\"כ נשמות דאצי' יש להם ראי' והם זרע אדם.\n<b>וזהו</b> שורש ההפרש בין פ' ראשונה דק\"ש עושין רצונו של מקום שעז\"נ ועמדו זרים, ופ' שני' אין עושין רצונו של מקום שלא נא' בכל מאדך מאד אותיות אדם בחי' ראי', ועי\"ז בא לבחי' ועמך לא חפצתי כו', משא\"כ פ' שני' והי' אם שמוע בחי' שמיעה לא נא' בכל מאדך. והנה המחבר חו\"ב הוא הדעת, והאדם ידע מקשר אדם וחוה חו\"ב, ובעבודה לקשר בחי' התבוננו' פנימית להיות בבחי' רעו\"ד ולא בבחי' מח' לבד, הנה גורם לחבר חו\"ב, ובחי' דעת זה הוא זרע אדם, ויש ד\"ת"],[2000580089,"המחבר מוחין ומדות להיות פנימיות המדות מקושרי' בהתקשרות חזק לבחי' שפע החכ' כו'.\n<b>והנה</b> ביחזקאל ססי' ל\"ד כתי' ואתן צאני צאן מרעיתי אדם אתם, נמצא גם בצאן נשמות דבי\"ע יכולי' להמשיך שיהיו בחי' אדם, וזה הי' עבודת יעקב שהי' א' מז' רועים המפרנסי' נש\"י, ולכן עשה לו מקל לבנה לח בחי' חסד, לוז וערמון גבורה, והוא אעיל בינייהו, מחשוף הלבן הגברת החסדי', בכדי להמשיך מ\"ד לברר ב\"ן בבי\"ע להמשיך בהם ג\"כ בחי' דעת עליון עד שנק' צאן אדם ממש, וזהו ענין המקלות ששם ברהטי' כו', וא\"כ בירר והעלה נשמו' דבי\"ע, ולכן נמשך מזה הבירור עקודים נקודים וברודים, והיינו שכמו ע\"י בירור דנה\"ב שבאדם מתעלה הנה\"א ע\"ד והחיות נושאות כו', והיינו לפי ששורשה מבחי' נקודי' לכן גדול ורב כוחה כו', כן ע\"י בירור זה שבירר אצל לבן עד הניצוצות היותר אחרונות, כי מעשה אבות סימן לבני'.\n<b>ובדרך</b> כלל יש ב' מיני רע, הא' רע הנגלה, ולזה אין צריך שהיית זמן כ\"כ לבררו, להיותו נגלה, וע\"ד הראשונים שנתגלו עוונם נתגלה קיצם כו', אבל יש בחי' רע שנדמה לירא שמים ותוכו מרמה זהו לבן הארמי, ולכן לברר בחי' זו נשתהה יעקב עשרי' שנה, ומעשה אבות כו', וכמו שהוא הלך אתו בעקמומיות ובמרמה אם כה יאמר כו' ששינה בכל עת, כמו\"כ הוכרח יעקב לבוא עמו עד\"ז בכדי להוציא ניצוצות הטוב המובלע בו.\n<b>ומפני</b> היותו מראה עצמו לבן, הוכרח יעקב להמשיך מ\"ד ג\"כ מבחי' לבן, וז\"ע מקל לבנה והמשיך מ\"ד [מ[הכתר, עד ששם פני הצאן נשמו' דבריאה אל עקוד פי' בע\"מ מאכ\"ח ח\"א סי' ט' זה יצחק, וכ\"ה ביר\"ק עקידה, והיינו בחי' מסי\"נ דיצחק. ובעבודה זהו ענין למסור נפשו באחד בק\"ש ע\"ד פ' ראשונה דכתי' בה בכל מאדך אותיות אדם וכנ\"ל שז\"ע ועמך לא חפצתי אפי' בחי' עמך מקור חיים, וע\"י בירור זה ותלדנה הצאן עקודים נקודים וברודים פי' לידה הוא בחי' גילוי וע\"י שרעה ופרנס נשמות דבי\"ע שיהי' פני הצאן הוא בחי' פנימיות רצונם בחי' רעו\"ד אל עקוד, עי\"ז נתגלה בי\"ע דכלליות שהוא בחי' עקודי' נקודי' וברודי' כו'."],[2000580090,"<h3>פדה בשלום נפשי</h3>\n<b></b><b>בס\"ד. (ש\"פ וישלח י\"ט כסלו, ל\"ב).</b>\nוישלח, י\"ט כסלו\n<b>פדה</b> בשלום נפשי כי ברבי' היו עמדי, וארז\"ל (ברכות ד\"ח א') אמר הקב\"ה כל העוסק בתורה ובגמ\"ח ומתפלל עם הצבור מעלה אני עליו כאילו פדאני כו', ופי' רש\"י תורה וגמ\"ח נק' שלום דכתי' וכל נתיבותי' שלום, וע\"י גמ\"ח מתרבה אחוה ושלום, ומתפלל כו' זהו כי ברבי' היו עמדי. ויש להעיר ממ\"ש והחוט המשולש לא במהרה ינתק, וארז\"ל בילקוט ע\"פ כי חלק הוי' עמו שקאי על יעקב שהי' שלישי לאבות, והי' בחיר שבאבות.\n<b>וביאור</b> הענין בהקדם מארז\"ל במד\"ר האבות הן הן המרכבה ולכאו' צ\"ל מהו שייך על האבות שהן מרכבה, שחיות המרכבה דבי\"ע הם ממה שנפל בשבה\"כ בבריאה, ושורשן מלפני מלך מלך, ולכן רב כוחם להעלות, ונק' מרכבה ע\"ש שבטלי' כסוס כו', אבל האבות הם מאצי' דאיהו כו' חד איך יקראו מרכבה.\n<b>ויובן</b> בהקדים ענין המרכבה שהם נושאות את הכסא עם בחי' אדם, אדם התכללות ג' קוין כמו תמונת אל\"ף יו\"ד כו' וקו באמצע המחברם, וכללות הג' קוין נק' אדם גימ' מ\"ה שם הוי' במילוי אלפין, וצ\"ל הלא שם מ\"ה הוא ביטול כו' במקורו ואיך יקרא אדם ג' קוין, אך באמת הא בהא תלי' דלהיותו התכללות ג' קוין זהו ע\"י ביטול. והענין כי חסד דרועא מים יורדי', וגבורה הסתלקות האורות מלמטלמ\"ע ועבד הלוי, והקו מחברן, ונודע כי להיות מחבר שני הפכי' צ\"ל הארה והמשכה מבחי' עליונה ששם בטלי' כו' ואין שם דבר והפוכו הסתלקות והמשכה, כי זה שייך במרכבה רצוא ושוב, אבל שם הכל בטל ממש בלי שום הסתלקות ובלי שום המשכה, ומשם נמשך"],[2000580091,"הארה לבחי' אדם להיות התכללות הג' קוין והתחברותן והיינו ע\"י חיות המרכבה, כי כל ענין עבודת החיות כדי להמשיך ולעשות בחי' אדם שיהי' בבחי' התכללות ולא יהי' ענפין מתפרדין, וע\"כ הם נושאות אותו למעלה להמשיך משם בחי' ביטול והתכללות, וז\"ש ודמות פניהם פני אדם מלבד שיש בד' חיות פני אדם פרצוף בפ\"ע, הנה בכללותן נמשך פרצוף אדם שכאו\"א כלול מבחי' אדם ג\"כ, והיינו לפי שעיקר מגמתם ופנימיותם להמשיך בחי' אדם בחי' התחברות הג' קוין והתכללותן כו'.\n<b>ולכאו'</b> צ\"ל איך נאמר שע\"י עבודת המרכבה נמשך בחי' אדם התכללות, הלא כל ענין עולם התיקון הוא שנעשה בחי' אדם שהוא בחי' התכללות ג' קוין. אך הענין ע\"ד שנת' בלק\"ת בביאור דוהניף דל\"ד ל\"ה, שעולם התיקון הוא בחי' התכללות המידות שיהי' רך כקנה שיכולי' לסבול היפוכו, וה\"ז נק' התכללות, ונת' שם מעלת התיקון שמפני היותם רך כקנה התכללות ג' קוין כללות ע\"ס, עי\"ז יכול להאיר בהם אוא\"ס מבחי' שלימותא דכולהו, ועי\"ז נעשה ביטול המדות ע\"ד עושה שלום במרומיו שעי\"ז מאיר בהם אוא\"ס בחי' שם מ\"ה דאיהו אורח אצי' המקשר ומחבר, שז\"ע קישור וחיבור יותר הרבה באין ערוך מבחי' עולם התיקון בפ\"ע שז\"ע רך כקנה, ונת' שם בהג\"ה שזהו כהפרש ענין ביטול היש לגבי ביטול אמיתי, וע\"ד שבת תתאה, ושבת עילאה, כן נא' בזה בעבודת חיות המרכבה, הן אמת שהתיקון הוא בחי' אדם, אמנם כתי' כמראה אדם שזהו רק התכללות ג' קוין ע\"ד רך כקנה שיכולי' להתכלל, (ומ\"מ בלתי המשכת אוא\"ס בהם יכול להיות ח\"ו ג\"כ בחי' ענפין מתפרדין, וכענין ראו מ\"ה, או כמו אברהם יצא ממנו כו' יצחק כו' והיינו מפני כי לא נולד יעקב עדיין קו האמצעי המחברם וממשיך מבחי' אוא\"ס דכתר, וזהו והחוט המשולש כמשי\"ת אי\"ה), וע\"י עבודת חיות המרכבה מעלים את בחי' אדם לבחי' אוא\"ס, ועי\"ז נמשך בחי' ההוא נביעא דאיהי נשמתא לגופא בחי' שם מ\"ה תכלית הביטול, שזהו בחי' היותר גבוה ונעלה מכמו שהוא תחלה רך כקנה כו', והיינו מפני ששרשם מבחי' נקודי' שלמעלה מבחי' ברודי' בחי' תיקון רך כקנה כו', ועי\"ז נמשך מבחי' אורות דתהו שהם בחי' מ\"ה בעצם, כמ\"ש בד\"ה יו\"ט של ר\"ה (ל\"ב).\n<b>אמנם</b> הנה כ\"ז הוא בחיות הקדש שנק' מרכבה, אך מהו ענין האבות חג\"ת ששם איהו כו' לקרותם בשם מרכבה. והענין דמבואר באד\"ז או\"א ממוחא"],[2000580092,"סתימאה נפקי ז\"א בעתיקא אחיד ותליא, וביאור הענין עד\"מ מבשרי כו', כי הנה השכל הוא נולד מן המשכיל שלמעלה מן השכל ששם לא נודע עדיין גילוי השכל וטעמו של דבר כלל, אבל מ\"מ הוא נק' משכיל מקור לשכל זה. אבל ז\"א בעתיקא כו' שורש המדות הוא נלקח ממקום עליון יותר, והגם כי ע\"י השכל נולדי' כו' וע\"פ שכלו יהולל, חכ' ובינה אב ואם המולידי' את ז\"א שמולידי' לבוא לידי גילוי ומנהיגי', אבל שורשן הוא יותר נעלה הרבה, ולכן יכול להיות יפה כח הבן כו'. ולפ\"ז יובן איך הוא בכח האבות חג\"ת להגביה בחי' אדם חכ' אדה\"ר, אדם תתאה ז\"א מה שמו ומה שם בנו, וכשמתעלים המדות הנה יפה כח הבן ומעלה גם בחי' חכ' להיות נמשך המשכת אוא\"ס בחכ' להיות גילוי אנת הוא חכים כי אוא\"ס הוא לאו מכל כו', רק המשכת אוא\"ס בחכ' תלוי בעבודת האבות הן המרכבה להעלות אדם דחכ' להיות נמשך מבחי' אנת להיות חכים. וזהו שארז\"ל ע\"פ ועשיתם אתם כאילו עשאוני, ונק' מרכבה ע\"ש שבטלי' לגמרי.\n<b>וז\"ש</b> לך ה' הגדולה והגבורה והתפארת, בבחי' ביטול לך, ועי\"ז נמשך מבחי' אוא\"ס דלאו מכל אינון כו' להיות אנת הוא חכים וגם במידות, ומפני כי זה באצי' ששם בלא\"ה רך כקנה וכנ\"ל, עי\"ז נמשך מבחי' הגבוה יותר והיינו מבחי' עקודי' מה שעקוד בכלי אחד בחי' התאחדות והתכללות כו' שזהו מעלת התיקון כמ\"ש במ\"א, ע' ביאור והניף הנ\"ל.\n<b>והנה</b> זה הי' קודם מ\"ת שהי' רק ע\"פ עבודתם, אברהם מרכבה למדת החסד, יצחק גבורה, יעקב ת\"ת המחברן, וע\"י מ\"ת שניתנה לנו התורה שהיא ג\"כ בכלל בג' קוין כי יש מצות שהם בבחי' העלאה כמו תרומות ומעשרות וקרבנות צדקה, רצוא תרומם, ויש מצות שהם בבחי' המשכה כמו ציצית ותפילין, ותורה הוא קו האמצעי, ויקם עדות ביעקב ותורה שם בישראל, ובד\"כ ז\"ע על ג\"ד העולם עומד על התורה כו', עבודה עבודת הקרבנות ועכשיו תפלה כנגד תמידים, גמ\"ח מלמעלמ\"ט תורה קו האמצעי, וכדי להעלות התורה ולקשרה בבחי' אוא\"ס ב\"ה ממש שלמעלה מבחי' אדם כי לא אדם הוא ע\"י ישראל שהם זרע אברהם יצחק ויעקב וירושה לנו מאבותינו התשוקה והצימאון להבטל ולהכלל באוא\"ס ממש, וניתן לנו כח זה במ\"ת שאנחנו נעלה וינשאו את בחי' אדם בעסק תורתינו ועבודתינו בקיום המצות שבבחי' אדם רמ\"ח פקודין כו' שס\"ה כו'. וזהו שנאמר במ\"ת אנכי ה' אלקיך, שמבחי' אנכי מי שאנכי יהי' נמשך שם הוי' להיות אלקיך וע\"ד האבות הן הן המרכבה.\n<b>וזהו</b> פדה בשלום נפשי כי ברבים, שארז\"ל תורה וגמ\"ח ותפלה, ואומרם בציבור לפי שהרבים ממשיכי' י\"ג מדות הרחמים בכל עת, כמ\"ש ע\"פ דרשו, וכשעוסק בג'"],[2000580093,"דברים אלו אזי ממילא נמשך הפדי', כי כהמס דונג כו', וזהו החוט המשולש דוקא, כי העיקר הוא קו האמצעי בריח התיכון כי להיותו מבריח ממשיך אוא\"ס מבחי' כתר ששם רחמי' פשוטי', וע\"י התעוררות רחמי' דת\"ת מתעורר רחמים רבים להיות נמשך הפדי' ופדויי ה'. ועפ\"ז יובן ג\"כ ענין כאילו פדאני, כי ישועתן של ישראל ישועתו של הקב\"ה כי קרובה ישועתי לבא והיינו ע\"י וברחמי' גדולי' אקבצך כו'."],[2000580094,"<h3>פדה בשלום נפשי [הנחה מוגה]</h3>\n<b></b><b>בס\"ד, פ' וישלח י\"ט כסלו, תרל\"ב.</b>\nהנחה.\n<b>פדה</b> בשלום נפשי כו' כי ברבים היו עמדי. הנה ארז\"ל כל העוסק בתורה ובגמ\"ח ומתפלל עם הצבור מעלה אני עליו כאלו פדאני לי ולבני מבין אומות העולם, ופי' רש\"י תורה דכתיב וכל נתיבותיה שלום, גמ\"ח ע\"י הצדקה וחסד אהבה ואחוה בעולם, ותפלה עם הצבור דכתיב כי ברבים היו עמדי. וצ\"ל מהו פדאני. הנה ארז\"ל על ג' דברים העולם עומד וצ\"ל מהו מעלת הג' דברים שעליהם העולם עומד. ויובן בהקדים מ\"ש והחוט המשולש לא במהרה ינתק, חוט המשולש הוא התכללות ג' קוין, ובילקוט פי' דקאי על יעקב שהוא קו האמצעי, וצ\"ל מהו מעלת קו האמצעי.\n<b>הנה</b> אמרו במד\"ר אמר ר\"ל האבות הן הן המרכבה. וצ\"ל ביאור ענין האבות הן הן המרכבה, בשלמא פני ארי' פני שור כו' שהם מרכבה לפי שהם משבה\"כ שנפלו בבריאה ועיקרם מלפני מלוך מלך כו' דהיינו מעולם התהו, לכך יש להם כח להעלות ולנשאות את הכסא, והמה בבחי' מרכבה לפי שהם בטלים כסוס לגבי רוכבו מפני שהם נבראים ובזה נושאים ג\"כ, וכמשל הסוס שנושא את רוכבו כו', אבל האבות עיקרן ושרשן באצי' דאיהו וחיוהי חד איהו וגרמוהי חד למה נק' בשם מרכבה להיכן ישאו את אצי', ולמה צריך לנשאות, ומאין להם הכח לנשאות.\n<b>אך</b> הענין יובן בהקדים להבין ענין מרכבת החיות פני ארי' פני שור כו' שהם נושאים הכסא ודמות מראה אדם שעליו מלמעלה. והענין כי הנה אדם נק'"],[2000580095,"התכללות ג' קוין תמונת אל\"ף, יו\"ד בראשו ויו\"ד בסופו וקו באמצע, או עד\"ז חח\"ן מימין בג\"ה משמאל, דת\"י באמצע, וכללות הג' קוין והתחברותן נק' בשם אדם שהוא שם מ\"ה, וצ\"ל הלא שם מ\"ה הוא בחי' ביטול והתכללות במקורו, ואיך יתכן לקרותו בשם אדם בתמונת ג' קוין, אך באמת הא בהא תלי' שלהיות התכללות הג' קוין והתחברותן צ\"ל מבחי' ביטול , אבל בשם מ\"ה אין שם התחלקות קוין, והענין כי חסד דרועא ימינא הוא מלמעלה למטה כמים היורדים ממקום גבוה למקום נמוך, וגבורה הו\"ע הסתלקות האורות ממטה למעלה וכמו ועבד הלוי הוא, והקו הוא המחברן. ונודע כי להיות דבר מחבר שני הפכים צ\"ל הארה והמשכה מבחי' עליונה ששם בטלים אלו השני הפכים ואין שם דבר והיפוכו כלל, שאין שם שום המשכה ולא שום הסתלקות, כי ההמשכה וההסתלקות שייך בחיות המרכבה והחיות רצוא ושוב, אבל שם למעלה הכל בבחי' ביטול ממש בלי שום הסתלקות ולא שום המשכה, ומשם נמשך הארה לבחי' אדם להיות התכללות הג' קוין והתחברותן, והיינו ע\"י חיות המרכבה, כי כל ענין עבודת החיות הוא כדי להמשיך ולעשות בחי' אדם זה שיהי' בבחי' התכללות ולא יהיו ענפין מתפרדין, וע\"כ הם נושאים אותו למעלה להמשיך משם בחי' ביטול והתכללות, וזהו ודמות פניהם פני אדם כי מלבד שיש בד' חיות פני אדם פרצוף בפ\"ע, הנה גם בכללותן נמשך פרצוף אדם שכל אחד ואחד כלול מבחי' אדם ג\"כ, והיינו לפי שכל עיקר מגמתם ופנימיותם להמשיך בחי' אדם בחי' התחברות הג' קוין והתכללותן .\n<b>אך</b> צריך להבין הלא נאצל עולם התיקון שהוא ציור אדם ואם כן מהו התוס' שנעשה ע\"י החיות. אך הוא ע\"ד משארז\"ל לעולם יהא אדם רך כקנה ואל יהי קשה כארז, קנה וארז הוא בדרך כלל ההפרש בין מדות דתהו ובין מדות דתיקון, כי בתוהו היו מדות תקיפין ונעשה שבירת הכלים ומזה נתהווה רע גמור, וכמו שאנו רואין שיש מיני בני אדם, שכשעושה איזה אדם נגד רצונו ממש הוא נוקם נקמתו ממנו מיד, וזה מסתעף משבירת הכלים דתהו, הגם ששרש התהו הוא גבוה מאד אבל למטה הוא רע גמור ואין זה בדעת כ\"א מעשה בהמה ואין זה רצון הבורא כלל, ולכן אמרו אל יהי' קשה כארז. אבל מדות דתיקון הם כלים שיכולים להתכלל מחמת ביטולם, כי כל מקום שיש איזה הגבהה אין אני והוא יכולים לדור, ובכדי לקבל גילוי אלקות צ\"ל ביטול ושפלות, וזהו אצי' מדות דתיקון שנאצלו כלים שיכולים לקבל דבר והיפוכו, אבל אין זה התכללות עדיין. אבל ע\"י עבודת החיות נעשה התכללות גמור שממשיכים מא\"ס דאנת הוא שלימותא דכולא, והיינו ע\"י שמנשאים את הכסא לא\"ס שכי לא אדם, ועי\"ז ממשיכים משם להוות אדם התכללות ג' קוין. ועיקר"],[2000580096,"ההמשכה הוא בת\"ת שהוא בריח התיכון המבריח מן הקצה אל הקצה. וההפרש בין אצי' מדות דתיקון ובין עבודת החיות הוא ע\"ד ההפרש בין ביטול היש לביטול אמיתי כמ\"ש ונחנו מה, או בין שבת תתאה לשבת עילאה, כי מעצם המדות יכול להיות ע\"ד מ\"ש ראומה ראו מ\"ה שהמ\"ה והביטול נרגש, או ע\"ד לא כאברהם שיצא כו' ולא כיצחק כו'. אבל ע\"י עבודת החיות נעשה בהם ביטול אמיתי, והכח להחיות ע\"ז הוא מפני ששרשן מעולם הנקודים ונת\"ל בדרוש יו\"ט של ר\"ה שהתהו הוא מ\"ה בעצם לא כמו התיקון שהוא בגימט' מ\"ה שהגימט' הוא לבוש, ולכן יכולים להמשיך על ידי עבודתם שיהי' בתיקון גם כן מ\"ה בעצם.\n<b>ומעתה</b> נבוא לביאור האבות הן הן המרכבה שהאבות הם חג\"ת דאצי' ומהו\"ע המרכבה שלהם. אך הנה מבואר באדרא זוטא או\"א ממו\"ס נפקו וז\"א בעתיקא אחיד ותליא, וביאור ענין זה יובן עד\"מ מבשרי, כי הנה השכל הוא נולד מן המשכיל שלמעלה מן השכל ששם לא נודע גילוי השכל וטעמו של דבר כלל, אבל מ\"מ הוא נק' משכיל. אבל ז\"א בעתיקא אחיד ותלי' שהמדות נלקחו ממקום עליון יותר. כי הגם שהמדות נולדו ונתגלו מן השכל ולפי שכלו כך תהיינה מדותיו, ובינה נק' אם הבנים והחכמה אב, מ\"מ אין זה אלא שהם גורמים להולדת והתהוות המדות שיצאו מההעלם אל הגילוי. אבל עיקר המדות בשרשן נלקחו ממקום עליון יותר , ומכ\"ז מובן איך שהז\"א שהוא בחי' מדותיו ית' הוא בשרשו למעלה מבחי' או\"א אלא שנמשך למטה . ולכך האבות שהם חג\"ת הם בחי' מרכבה להעלות את האדם הוא בחי' חכמה, כנודע שיש ב' בחי' אדם, אדם הראשון הוא בחכ', ואדם תתאה הוא ז\"א, וזהו מה שמו ומה שם בנו, מה שמו חכמה, ומה שם בנו ז\"א, והנה כשמתעלות המדות נעשה יפה כח הבן ומעלה גם בחי' חכמה להמשיך התלבשות אא\"ס בחכמה להיות גילוי אנת הוא חכים, כי א\"ס בעצמו לאו דאית לי' מכל אלין מדות איהו כלל. רק המשכת אוא\"ס להיות בחכמה תלוי בהמשכת והעלאת נשמות הצדיקים וכמארז\"ל ע\"פ ועשיתם אתם מעלה אני עליכם כאלו עשאוני. והוא ע\"י ביטול המדות ע\"ד מ\"ש המשל ופחד כו' מיכאל שר של מים וגבריאל שר של אש ואין מכבין זה את זה כו', כמו למשל ב' שרים המנגדים זה לזה כשבאים לפני המלך הרי הם בטלים ממש עד שכל אחד יוכל לעשות מלאכת חבירו, אך זהו בבריאה כי יש מרכבה ביצי' ובבריאה. וכמו\"כ במדות עליונות ע\"י ביטולם לא\"ס דלאו מכל אינון מדות כמ\"ש לך ה' הגדולה כו' עי\"ז נמשך מא\"ס דלאו מכל אינון מדות כלל במדות,"],[2000580097,"וזהו שם מ\"ה דאיהו אורח אצילות וההוא נביעא איהו כנשמתא לגופא, וזהו ההפרש בין חיות הקודש שהם מרכבה לאדם תתאה, אבל האבות הם מרכבה לאדם קדמאה, וזהו שמנשאים את האצי' הגם ששם איהו וחיוהי חד כו' בכדי להמשיך מאוא\"ס אנת הוא להיות חכים. והכח ע\"ז מפני שז\"א בעתיקא אחיד ותלי'. ומצד כח האצי' נמשך עוד גילוי יותר כי תיקון הוא ברודים, ונקודים הוא תהו, ועקודים הוא ששם עקוד בכלי א' שהכלי הוא ג\"כ אחד ואין שם התחלקות עשר ספירות, וע\"י כח האצי' נמשך גילוי עקודים. והעיקר ע\"י יעקב כמו שנתבאר בדרוש ויקח לו יעקב מקל לבנה שיעקב ע\"י המקלות עשה יחודים עליונים שיתגלה עולם העקודים. וזהו החוט המשולש לא במהרה ינתק שהוא התכללות הג' קוין ע\"י יעקב מדת התפארת.\n<b>אך</b> זה הי' קודם מתן תורה אבל כאשר ניתנה התורה נעשה התחברות אדם שעל הכסא עם כי לא אדם על ידי התורה ומצות. כי בתורה יש שני הבחי' אדם שעל הכסא וא\"ס שכי לא אדם. שע\"י התורה נמשך א\"ס שכי לא אדם, כמ\"ש אנכי ה' אלקיך שעל ידי התורה נמשך אנכי מי שאנכי. ולכן יש בתורה עצמה מצות שהן בבחי' העלאות כמו תרומה ומעשרות וצדקה כמ\"ש צדקה תרומם גוי, ויש שהן בבחי' המשכות כמו ציצית ותפילין כו'. ולכך יש בהן כח זה להעלות ולעורר המשכה עליונה. ובכ\"ז מעורר בחי' אנכי ממש בחי' כי לא אדם הוא להמשיך משם לבחי' אדם כו', ואדם שבתורה הוא כמ\"ש זאת התורה אדם כי רמ\"ח פקודין רמ\"ח אברים דמלכא שס\"ה גידים שס\"ה ל\"ת.\n<b>וזהו</b> מעלת הג' דברים שעליהם העולם עומד כי ע\"י כל הג' דברים נעשה התחברות כי לא אדם עם אדם העליון. כי עבודה קרבנות ועכשיו תפלה הוא העלאות מלמטה למעלה, וגמ\"ח הוא המשכת אלקות מלמעלה למטה, ותורה הוא קו האמצעי המחברם. ומה שאמרו המתפלל עם הצבור יובן ממשארז\"ל ע\"פ דרשו כו' בהיותו קרוב, וכתי' בכל קראינו אליו ותירצו כאן ליחיד וכאן לצבור ויחיד אימת אלו עשרת ימי תשובה, וממילא מובן דכמו ליחיד בעשרת ימי תשובה נמשך רחמים רבים ממקור הרחמים שיהי' סליחות עונות, כמו\"כ לצבור בכל זמן. ולאו דוקא עם הצבור אלא בזמן שהצבור מתפללין. הרי דלהצבור על ידי התעוררות רחמים רבים נמשך רחמים רבים מלמעלה.\n<b>ועל</b> ידי זה נעשה הפדי', כי ענין הפדי' הוא כי לאום מלאום יאמץ כשזה קם זה נופל שתמיד הוא מלחמה, אבל כשנמשך כי לא אדם אז כהמס דונג כו'. ומה שאמר פדאוני כביכול על השכינה כי ישועתן של ישראל הוא ישועתו של הקב\"ה כי גלו לבבל שכינה עמהם, וע\"י אלו הג' דברים נעשה פדי' בנפש וממילא נעשה פדי' בשכינה. וזה הכח ניתן לנו בירושה מאבותינו שהיו מרכבה עליונה, אברהם אבינו"],[2000580098,"ע\"ה למדת החסד כמ\"ש בספר הבהיר אמרה מדת החסד כל זמן היות אברהם בעולם לא הוצרכתי לעשות מלאכתי שהרי אברהם עומד במקומי, ויצחק למדת הגבורה ויעקב למדת התפארת כמ\"ש אלקי אבי כו' ופחד יצחק כו', ונתנו לנו הכח שע\"י תורה ומצות נוכל גם כן להיות בבחי' מרכבה. והעיקר ע\"י מדתו של יעקב התעוררות רחמים רבים ועל ידי זה נעשה פדי'. וגאולה דלעתיד לבא יהי' ג\"כ ע\"י מדת הרחמים כמ\"ש וברחמים גדולים אקבצך ופדויי ה' כו' ובאו ציון ברינה ושמחת עולם על ראשם."],[2000580099,"<h3>כי עמך מקור חיים</h3>\n<b></b><b>בס\"ד. (ש\"פ וישב) שבת חנוכה, ל\"ב.</b>\nוישב, שבת חנוכה\n<b>כי</b> עמך מקור חיים באורך נראה אור, וצ\"ל מה\"ע באורך נראה אור. וילה\"ק תחלה שורש ענין נס דחנוכה שתקנו להדליק נרות מפני נס דפך השמן, והלא לכאו' עיקר הנס הי' הניצוח רבים ביד מעטים, ואז ממילא הי' נכלל טהרת השמן, ולמה עשו עיקר מהשמן כו'. אך הענין דעיקר הנס בהחזרת התומ\"צ, כי רצו להשכיחם תורתך ולכן טמאו כל השמני' להיות כי התורה נמשלה לשמן אבל מהצלת כו' לא הי' עיקר"],[2000580100,"כי לא רצו לאבד גופם, רק לבטל התורה, ולכן לא עשו עיקר מהצלתם כ\"א ממציאת שמן טהור לרמז על אור חכ' התורה, ולהבין זה צ\"ל מ\"ש כי נר מצוה ותורה אור שנמשלו המצות לנר ותורה לאור, וארז\"ל עבירה מכבה מצוה כמשל הנר שנכבה, ואין עבירה מכבה תורה, כמשל האור שאינו כבה.\n<b>והענין</b> יובן בהקדם מ\"ש כי עמך מקור חיים באורך נראה אור (וצ\"ל למה אינו די באור התורה שנק' תורה אור, ומהו ענין שבאורך דוקא נראה אור). הנה במ\"ת ע\"פ זה א\"ר יוחנן עובדא הוי בחד ב\"נ הי' מדליק את הנר בלילה והי' כבה ומדליקו, כבה ומדליקו, אמר עד מתי אהי' מתייגע והולך ממתין אני עד שתזרח השמש ואני הולך לאור החמה, כך ישראל נשתעבדו במצרי' עמדו משה ואהרן וגאלום חזרו ונשתעבדו בבבל, וחוזרי' ונגאלי' ע\"י חנני' מישאל ועזרי', חזרו ונשתעבדו ליון ונגאלו ע\"י מתתי' חשמונאי ובניו וזהו הנס דחנוכה, חזרו ונשתעבדו, אמרו ישראל הרי נתייגענו נגאלין ומשתעבדין אין אנו מבקשי' שיאיר לנו בו\"ד למטה אלא הקב\"ה שנא' אל ה' ויאר לנו, זהו שאמר משה בגאולת מצרים מי אנכי, דלכאו' תמוה, אלא כי משה רצה שיהי' ע\"ד הגאולה דלע\"ל, ולכן א' האם אני הוא האנכי שאמרת ואנכי אעלך גם עלה (והגם כי זה קאי על יצ\"מ מ\"מ נא' גם עלה לכן י\"ל דקאי על גאולה אחרונה) ואמר זה בכדי שיהי' ע\"י הקב\"ה שלא ע\"י בו\"ד. גם צ\"ל מה שבגאולה דלע\"ל כתי' כי לא בחפזון כו' הלא ע\"י החיפזון דיצ\"מ לא הספיק בצקת של אבותינו להחמיץ עד שנגלה עליהם מלך מלכי המלכים שזהו [מבחי'] גדול מאד, וצ\"ל פי' מלך מלכי המלכים.\n<b>הנה</b> איתא בפדר\"א עד שלא נבה\"ע הי' הוא ושמו בלבד, וכן אנו אומרי' אתה הוא עד שלא נברא כו' וכתי' ג\"כ יהללו ש' הוי' כי הוא צוה ונבראו, שלכאו' צ\"ל ל' נברא דהל\"ל בראת וכמ\"ש בראשית ברא אלקים. אך הענין הוא דהנה התהוות כל"],[2000580101,"העולמות הוא מבחי' שמו ית', ושמו ואור הוא בחי' אחת שפי' אור הוא הארה בעלמא שאינו נוגע לעצמותו כלל, כמו אור השמש ואפי' אור הנר הנה אינו נוגע אל העצם כלל אם הוא מאיר א\"ל, ולכן כשיש מסך מסתיר על האור אין בו שום שינוי וכן כשמאיר אין בהם שום גרעון, והיינו מפני כי האור הוא הארה בעלמא שאינו נוגע אל עצמותו כלל. ועד\"ז יובן למעלה שהשתלשלות והתהוות כל העולמות הוא מהארה בעלמא שאינו נוגע לעצמו כלל, וזהו בחי' שם ג\"כ שכמו שמו של האדם אינו נוגע להאדם כלל, שלעצמו א\"צ להשם כלל כ\"א לזולתו. והנה עד שלא נבה\"ע הי' הוא ושמו בלבד שבחי' השם הי' כלול בעצמותו ולא הי' עולה בשם כלל, ובריאת העולמות הי' מבחי' שמו כו', ולכן נא' ל' נברא שמשמע מאליו כי ל' בראת הוא כמו כח הפועל בנפעל שבחי' זו אינו שייך כ\"א בש' אלקים שהוא האור שמאיר לכל נברא בפרט אבל בבחי' ש' הוי' הוא ונבראו ממילא ומאליו כו', וזהו נברא העולם כו'.\n<b>והנה</b> בחי' שם ואור זה הוא בחי' מל' שזהו מ\"ש מלכותך מלכות כל עולמים, ויש בזה ב' בחי', הא' הוא בחי' מלכותך, הב' הוא בחי' מלכות כל עולמים, שבחי' מלכותך הוא האור כמו שהוא כלול בעצמו כמו קודם שנבה\"ע שהי' הוא ושמו בלבד, שהשם והאור הי' כלול בעצמותו ואז האור הוא ביתר שאת ויתר עז כמ\"ש בתניא ממשל אור השמש כשהוא בשמש הוא ביתר שאת, וזה שיאיר האור והשם הוא ירידה והשפלה, וזהו ההפרש בין מלכותך לבחי' מלכות כל עולמים, מלכותך הוא בחי' מל' דא\"ס שהוא בחי' האור כמו שהוא כלול בעצמותו ומלכות כל עולמים הוא בחי' מל' דאצי' שהוא האור כמו שמאיר להוות עולמות כו'. ופי' מלכות כל עולמים שמהוה כל העולמות, ובד\"כ נחלק לג' עולמות בי\"ע כמ\"ש ולכבודי בראתיו יצרתיו אף עשיתיו, בראתיו היא בריאה יש מאין כמו באדם אותיות המחשבה הם בחי' ראשית הגילוי, ואח\"כ דיבור ממח' הוא בחי' גילוי ההעלם שע\"י הדבור יוצא העלם מחשבתו, כמ\"כ עד\"ז יובן למעלה שבחי' עולם הבריאה היא יש מאין, ויצי' היא גילוי ההעלם וה\"ע ציור החומר, ובד\"כ עולם הבריאה הוא בחי' ג\"ע העליון עולם הנשמות, יצי' בחי' עולם המלאכי', אף עשיתיו עולם הגלגלי' כו', ובכללות בחי'"],[2000580102,"ההשתלשלות נחלק ג\"כ לג' בחי' בי\"ע כו', וזהו בהבראם בה' בראם שתמונת הה\"א הוא ג' קוין והנה ב' קווין הם מחוברים שמרמז על בריאה ויצי' שהם בבחי' ביטול וכמ\"ש וצבא השמים לך משתחוים, אף עשיתיו הנה אף הפסיק הענין שזהו רגל הג' דה\"א שנפסק לרמז על עולם העשי' ועוה\"ז הגשמי כו'. והנה מצד בחי' השתלשלות נשתלשל בחי' מצרים דקליפה כי את זלע\"ז עשה האלקי' שכמו שיש בקדושה ד' בחי' אבי\"ע כמ\"כ יש בקליפות לעו\"ז ג\"כ אבי\"ע (וזהו ק\"נ וג' קליפות, נוגה הוא בחי' אצי' דקליפה וג' קליפות הטמאות הם בי\"ע) ומזה נמשך הגלות כו', וכדי שיהי' בחי' יצ\"מ זהו א\"א להיות מבחי' זו דמלכות כל עולמי' שהרי מבחי' זה מתהווה בחי' מצרי' בריבוי השתלשלות, וכדי שיהי' יצ\"מ זהו מבחי' מלכותך דכאשר מאיר מבחי' מלכותך בבחי' מלכות כל עולמים הנה עי\"ז הוא יצ\"מ, וזהו עד שנגלה עליהם ממ\"ה שהוא בחי' מלכותך כו', וזה\"ע הנר שמאיר את חשך הגלות כו'.\n<b>והנה</b> בנר יש שמן ופתילה, שמן הוא בחי' שמן משחת קדש בחי' ח\"ע שבה מאיר גילוי אא\"ס ב\"ה מפני כי חכ' כח מ\"ה בחי' ביטול היא כלי להשראת אוא\"ס ב\"ה (היינו בחי' האור הוא בחי' מלכותך בחי' מל' דא\"ס), והפתילה בחי' המדות (יסוד ז\"א שע\"י חכ' ומדות מאיר בחי' מל' דא\"ס במל' דאצי' בחי' מלכות כל עולמים הנ\"ל ועי\"ז הוא יצ\"מ). והנה האדם מדליק את הנר והיינו מפני כי באדם יש ג\"כ בחי' נר כמ\"ש נר הוי' נשמת אדם, שהשמן הוא בחי' חכ' וביטול דנה\"א לברר ולהעלות את הנה\"ב, וב' גווני האור הם ב' בחי' אהבות נהורא תכלא ונהורא חיוורא, והפתילה היא בחי' יראה תתאה, ומפני כי באדם יש בחי' הנר ולכן כאשר מאיר הנר שלו הנה הוא יכול להמשיך בחי' הנר להאיר את החשך דגלות. וזהו כי נר מצוה שהמצות נמשלו לנרות שמאירי' את החשך, כי הנה על המצות מברכין ברוך, אלקינו מלך העולם אשר קדשנו במצותיו, פי' מלך העולם הוא בחי' ממכ\"ע שמזה נתהוה העולם בחי' העלם והסתר כו', וע\"י המצות ממשיכי' מבחי' תר\"ך עמודי אור להאיר את החשך, וזהו אשר קדשנו במצותיו מצותיו כו', וזהו נר מצוה שע\"י המצוה ממשיכי'"],[2000580103,"הנר להאיר החשך כו'. וזהו באו משה ואהרן וגאלום, אהרן הוא המעלה ומטיב את הנרות (ומשה בחי' שמן ח\"ע), הנה הם המשיכו את הנר בחי' מלכותך במלכות כל עולמים כדי שיהי' הגאולה להיות יצ\"מ כו'.\n<b>והנה</b> כדי להיות בחי' כלי לגילוי זה צ\"ל מצה דוקא כי הנה מצה הוא אותיות מצוה רק שבמצוה מתוסף וא\"ו. והנה ההפרש בין חמץ למצה שחמץ הוא בחי' הגבהה והתנשאות וגם יש בו טעם, אבל מצה היא ביטול ושפלות ואין בה טעם ונק' בזהר מיכלא דמהימנותא כי אמונה אינה ע\"פ טעם כ\"א ביטול שלמעלה מן הטו\"ד, ובאמת יש כמה בחי' שא\"א לבוא ע\"פ טעם וכמ\"ש כל שאור וכל דבש לא תקטירו כו'. והחילוק שבין תיבת מצה לחמץ כי חמץ הוא בחי\"ת ומצה בה\"א שהה\"א מרמז על ג' עולמות בי\"ע כנ\"ל שהם בבחי' הביטול כנ\"ל כמ\"ש וצבא השמים לך משתחוי' כו', אבל חמץ הוא בחי' חי\"ת ל' חטא שהוא בחי' ג' עולמות בי\"ע דקליפה שהם היפך הביטול כו'. והנה כאשר נמשך הנר במצה אזי היא בחי' מצוה, שפעם כתי' מצת בלא וא\"ו ופעם כתי' מצות בוא\"ו, והיינו כי המצה הוא בחי' נר בחי' כלי דהיינו בחי' ביטול היש, וכאשר נמשך הנר הוא בחי' השמן והאור הנ\"ל להאיר את החשך כנ\"ל אז הוא מצות בוא\"ו, כי הוא\"ו הוא בחי' המשכת בחי' הנר והאור בבחי' מצה היא הנר בחי' כלי, ואזי הוא בחי' נר מצוה כו' (המצה היא בחי' מל', והגם שבהשתלשלות יכול להיות מבחי' זו בחי' מצרי' כו', מ\"מ הרי בעולמות דקדושה יש בחי' הביטול שהוא ביטול היש, והרי היא נק' נר בחי' כלי לקבל האור והגילוי דבחי' מלכותך הנ\"ל, והוא\"ו הוא בחי' ההמשכה מבחי' מלכותך לבחי' מלכות כל עולמים בחי' נר, ואז נק' מצות בחי' נר מצוה כו').\n<b>ועוד</b> יש פי' במצה ל' מצה ומריבה, כי הנה המצה היא ביטול היש שהיש עדיין הוא בשלימות, וצ\"ל בחי' מצה ומריבה בחי' מלחמה עם הנה\"ב שיהי' ביטול היש כו'. והנה מצה זו צריכה שמירה וזה\"ע מצה שמורה כמ\"ש ושמרתם את המצות, כי הנה הלילה היא בחי' ההעלם והסתר ובחי' היש עדיין בשלימות רק שהמצה היא בחי' ביטול היש מ\"מ היש הוא בשלימות, ואפי' כשנמשך הנר להאיר את החשך דלילה הנה הלילה היא חשך עדיין כמו שהייתה קודם רק שהנר מאיר את החשך מ\"מ הלילה עצמה היא כמו שהיתה קודם, וזהו מ\"ש ליל שמורי' הלילה הזה כו' שהלילה היא חשך עדיין רק שנמשך בה בחי' זה להאיר את החשך מ\"מ צ\"ל ליל שימורי' שצריכי' שמירה שמאחר שהיש הוא הרע שבמדות הוא בשלימות ובמקומו, לכן צ\"ל בחי' שמירה שלא יפול ח\"ו בישות כו', וכמו שבגשמיות בלילה מצוי מזיקי',"],[2000580104,"<b>וז\"ע</b> ג' משמרות הוה הלילה, ראשונה חמור נוער שהוא בחי' קליפות, לכן צ\"ל שמירה, וז\"ע מצה שמורה. ועוד צ\"ל בחי' מרור שצ\"ל ג' דברי' פסח מצה ומרור, שהמרור הוא קו האמצעי בחי' רחמים כפי הסידור שמסדרי' על הקערה, ונת' הקושי' בלק\"ת (בד\"ה קול דודי) שלכאו' המרור קו השמאל בחי' גבורות. אך הענין הוא מפני שבבחי' מרירות מעורר המשכת ר\"ר, כי בחי' רחמים אינו שייך כ\"א על מי שהוא במדריגה התחתונה ואין טוב לו, אבל על מי שהוא במדרגה העליונה ואינו חסר לו כלל לא שייך עליו רחמנות כלל, ולעורר בחי' רחמים הוא ע\"י שיתבונן איך שהבריאה היא יש מאין מבחי' שם והארה בעלמא, וכ\"ש כשנמשך אחר תאוות גשמיות שמתרחק מאד מאור פניו ית', וע\"י מרירות זו מעורר ר\"ר על נפשו כו', וכתי' ואשא אתכם על כנפי נשרי' ואביא אתכם אלי שע\"י בחי' רחמי' אביא אתכם אלי (ונמצא כי ג' דברי' פסח מצה ומרור, פסח הוא בחי' הדילוג בחי' המשכת מלכותך לבחי' מצה הוא ביטול היש ע\"י המרור קו האמצעי בחי' רחמי').\n<b>ומעתה</b> יובן ענין מה שגאולת מצרי' הי' בחפזון, והוא ע\"ד שנת' בסש\"ב שיש ב' בחי' בעבודה אתכפיא ואתהפכא, שבחי' אתהפכא הוא כאשר כבר נהפך הרע וכמ\"ש אוהבי ה' שנאו רע, מואס ברע שהוא עוד יותר משנאו רע, וזהו בחי' צדיקי', ובחי' בינוני' הוא בחי' אתכפי' שהרע הוא בתקפו כתולדתו רק שמוח שליט על הלב, והעצה לבינונים לברוח מהרע, וז\"ע בחי' יצ\"מ שנאמר בה כי ברח העם שברחו מהרע, והבריחה הוא בתורה היינו לקשר מחודומ\"ע בתומ\"צ היינו לקשר מחשבתו ודבורו במחשבת ודבור התורה ובחי' המעשה במעשה המצות, ועי\"ז ממילא יתבטלו המדות רעות, כי המדות הם מדות האדם וכשמקשר מחדו\"מ במחדו\"מ דתומ\"צ הגם כי מחדו\"מ הם רק לבושי' מ\"מ הרי הם מחדו\"מ של הקב\"ה. וגם ניתן הכח להיות מוח שליט על הלב לכן מתבטלי' המדות רעות עי\"ז להיות בבחי' אתכפיא ביטול היש כו'. וז\"ע חפזון דישראל שהוא בחי' הבריחה מהרע כו', והיינו מפני כי הרע עדיין בתקפו, ולכן הי' צ\"ל כי ברח העם. וז\"ע המשל שהדליק הנר בלילה שלילה הוא בחי' החשך הוא עדיין כמו שהי', רק שהדליק הנר להאיר את בחי' החשך, וכבה, כי עבירה מכבה מצוה, היינו בחי' הנר מצוה מכבה עבירה, ולכן ישראל אחר יצ\"מ היו במדריגות פעם כך ופעם כך (ר\"ל פעם חטאו והיו במדרגה שפלה וכשעשו תשובה נתעלו) ואין עבירה מכבה תורה כי תורה היא בחי' תורה אור כו'."],[2000580105,"<b>ולהבין</b> ענין אור דתורה צ\"ל הלא מצינו בדרז\"ל שאמרו ע\"פ במחשכי' הושיבני זה תלמוד בבלי, וא\"כ כל ענין הלימוד נק' בשם חשך ואיך הוא אור. ויובן בהקדם שורש ההפרש בין תלמוד בבלי לירושלמי, שבירושלמי רוב ההלכות הם הלכות פסוקות בלתי מעורבות כ\"כ בקושיות ותירוצים כמו בבבלי, והגם שר\"י ור\"ל עסקו בפלפול מ\"מ זה הי' רק בינם לבין עצמם אבל רוב התלמידי' לא עסקו בפלפול כ\"א לימוד ההלכות בדרך קצרה לפסוק כל הלכה בטעמה, אמנם בבבל עסקו בפלפול להשיג בכל דבר הלכה עומק המושג שבה, דהיינו כשרוצה לעמוד על טעמו של דבר בעמקות לא יוכל להגיע לאמיתות הענין לעולם, וכל שיעמיק דעתו יותר, יותר יהי' הדבר מופלא ונעלם מן השכל והטעם כו', ובזה רבו המדריגות בענין הפלפול שכאשר יצטרך לטורח רב בקושיות ותירוצים רבים מאד עד שיגיע לאמיתת דבר ההלכה על בורי' יקרא פלפול גדול, ואם במעט הטורח יקרא פלפול קטן, ועכ\"פ כל ענין הפלפול הוא הפלאת המושג שלא יוכל להשיגו וישאר בהעלם מאד, ואם הי' נשאר בהעלם הרי אבד השגתו הראשונה ע\"כ יקרא חשך ומניעת ההשגה כאדם שהולך בחשך גשמי ממש, אך לאחר שהאיר לו אמיתת הענין לאחר שחשך לו קודם, הרי זה האור ממקום גבוה ירד, שהרי השגתו הראשונה מצומצמת מאד היתה, וכשהגיע למעלת ההפלאה וההעלם שלא יוכל להשיג כענין מה פשפשת כו' ה\"ז עלי' ולא ירידה, ומ\"מ יקרא חשך ולא אור מאחר שאינו משיג מאומה כו'. אמנם מ\"מ בזאת ניכר יתרון מעלת החשך כאשר חוזר ויורד מלמעלמ\"ט להאיר מן ההעלם לגילוי שהארה זו היא גבוה הרבה מאור השגה הראשונה וזה יקרא מתון ומסיק שמסיק ומוריד מן ההעלם. והנה נודע כי"],[2000580106,"החשך הוא בריאה בפ\"ע וכמו שאנו אומרים ובורא חשך, ובאור כתי' יצי' להורות על הפלאת החשך הנעלם על גילוי האור, כיתרון הבריאה נגד יצי', ולכן בלימוד הירושלמי להיות כי שם מובדלי' ביותר מטומאת הקלי' רק ק\"נ, לא עסקו בפלפול מפני כי עיקר הפלפול הוא להביא לידי העלם כנ\"ל, ובזאת ישבר כח הקלי' שהם גבורות קשות ובקושי' של תורה משבר אותם, ולכן בבבל דוקא אמרו במחשכי' כו'.\n<b>ועפ\"ז</b> יובן ענין הדלקת נרות דחנוכה, בהיות מבואר שהחושך מופלא מאד ואם יאירו את החשך הגם שהאור הוא ירידה עכ\"ז ירידה זו היא ממקום גבוה מאד כנ\"ל, וזהו ותורה אור לרמז על הארת האור מתוך החשך של הפלפול דוקא כנ\"ל. וכמו\"כ בנס דחנוכה מאחר שטמאו כל השמני' שרומז לתורה ורצו להחשיך התורה שז\"ע להשכיחם תורתך, כשהאיר ה' להם ממקום גבוה ונפלא הי' האור, ע\"כ הדליקו נרות לרמז לנס הנפלא כו', אמנם לא הדליקו רק נרות לבד ולא בחי' הנק' אור להיות כי הגאולה הי' ע\"י בו\"ד מתתי' חשמונאי ובניו כו' שהוא בחי' אתר דמשתני הוה ונפסד ולכן כבה שחזרו כו'. אמנם ע\"י שורש המשכת השמן שמצאו פך כו' שהוא מקור האור שהוא בחי' ותורה אור, הנה עז\"נ טעמה כי טוב סחרה לא יכבה בלילה נרה שגם בזמן הגלות שנמשל ללילה לא יכבה נרה לגמרי, והיינו מפני כי טוב סחרה שהמקיף בא מן ההעלם לגילוי ע\"כ גם בלילה חשך גמור לא יכבה לגמרי נרה, ורק מ\"מ מפני שהי' ע\"י בו\"ד לכן בהגלות נגלות האור נק' נרה ולכן כבה, אמנם בשורשה שנק' אור לא יכבה כו', וע\"י הבירורי' דתורה בזמן החשך עי\"ז יהי' הגילוי דלע\"ל שיהי' באורך נראה אור ע\"י הקב\"ה, והיינו כי גוף האדם הוא הוה ונפסד, ואפי' מרע\"ה, ולכן שורש המשכתו הוא מאתר דמשתני, אבל לע\"ל שיהי' ע\"י הקב\"ה לא יהי' שינוי' כי אני הוי' לא שניתי כתי', ולכן כתי' והי' אור הלבנה כו' שהלילה בעצמה כיום תאיר וא\"צ לנר כלל כי לא יהי' חשך, ולכן לא בחפזון שאין צריך לברוח מהרע כי לא יהי' רע והסירותי את לב האבן כו' ואת רוח כו', ולכן לא בחפזון כו' כ\"א בשובה ונחת תושעון, וזהו באורך נראה אור כו'."],[2000580107,"<h3>כי עמך מקור חיים [הנחה מוגה]</h3>\n<b></b><b>בס\"ד. פ' וישב, חנוכה. תרל\"ב.</b>\nהנחה.\n<b>כי</b> עמך מקור חיים באורך נראה אור. וצריך להבין מהו באורך. ויובן בהקדים ענין נס חנוכה שקבעו בנרות להורות על טהרת השמן ולכאו' אינו מובן למה קבעו עיקר הנס על טהרת השמן, והלא הי' ג\"כ הצלת נפשות כמ\"ש ורבים ביד מעטים כו' והי' צריך לקבוע עיקר הנס ע\"ז, ולא די שלא קבעו עיקר הזכרון ע\"ז עוד זאת שעשו עיקר מטהרת השמן וע\"ז לא עשו שום זכר. אך באמת עיקר כוונתם הי' להשכיחם תורתך, וזהו שטמאו כל השמנים שבהיכל כי שמן הוא חכ\"ע חכמת התורה, ומצאו פך אחד של שמן חתום בחותמו של כה\"ג להורות על החזרת אור התומ\"צ, לכן עיקר הנס בנרות להורות על אור התומ\"צ, ומה שאמרו ורבים ביד מעטים כו' היינו אם לא היו נשמעים להם לבטל תורה, אבל עיקר כוונתם הי' ביטול תורה ולכן קבעו בנרות. וענין הנרות הוא כמ\"ש כי נר מצוה ותורה אור, ולכן ארז\"ל עבירה מכבה מצוה ואין עבירה מכבה תורה, כי מצוה נק' בשם נר וכמו שיכולים לכבות אור הנר כמ\"כ עבירה מכבה מצוה, אבל תורה נק' בשם אור וכמו שאור היום אין יכולים לכבות כן אין עבירה מכבה תורה. וצ\"ל הלא אור התורה יש ג\"כ בזמה\"ג ולמה נא' דוקא על לע\"ל באורך נראה אור.\n<b>והענין</b> הנה איתא במד\"ת משל לאחד שהלך בלילה באפילה הדליק את הנר להאיר את החשך וכבה, הדליק נר שני וכבה, הדליק נר שלישי וכבה, אמר עד מתי אני מתייגע אמתין עד אור הבוקר, והיינו שאור הבוקר אינו כבה, כך אמרה כנס\"י לפני הקב\"ה, בגלות מצרים עמדו משה ואהרן וגאלום וכבה כי גלו לבבל, עמדו חנניא מישאל ועזרי' וגאלום וכבה שגלו ליון, עמדו חשמונאי ובניו וגאלום וכבה שגלו עוד, אמרה עד מתי אני מתייגע להגאל ע\"י בו\"ד, אמתין עד אור הבוקר, כמ\"ש אל ה' ויאר לנו, שהגאולה שע\"י בשר ודם נק' בשם נר אבל הגאולה שע\"י הקב\"ה נק' בשם אור. וזהו באורך נראה אור שהגאולה תהי' ע\"י הקב\"ה ותהי'"],[2000580108,"גאולה שלימה. וזהו שאמר משה להקב\"ה מי אנכי וארז\"ל במד\"ר שמות פ\"ג שא\"ל משה להקב\"ה לא כך אמרת ליעקב אנכי ארד עמך מצרימה ואנכי אעלך גם עלה ועכשיו אתה אומר לכה ואשלחך אל פרעה, ונמצא יהי' פי' הפסוק מי אנכי הכי אני הוא האנכי שאמרת ליעקב אנכי אעלך כו', והיינו כי משה רצה שתהי' הגאולה ע\"י הקב\"ה ולא ע\"י בו\"ד בכדי שתהא הגאולה נצחית כמו הגאולה דלעתיד שלא יהיו שינוים כו'.\n<b>ולהבין</b> ענין הגאולה שנמשל לנר, יובן בהקדים הענין מ\"ש על לע\"ל כי לא בחפזון תצאו, מהו המעלה שלא יהי' בחפזון הלא בגאולת מצרים ע\"י החפזון לא הספיק בצקת להחמיץ ונגלה עליהם מלך מלכי המלכים, הקב\"ה וגאלם. ובכדי להבין כ\"ז צ\"ל פי' ממה\"מ כי הנה איתא בפדר\"א עד שלא נבה\"ע הי' הוא ושמו בלבד, וכ\"ה הנוסח מה שאנו אומרים אתה הוא עד שלא נבה\"ע ואתה הוא משנברא העולם, שלכאורה אינו מובן לשון נברא דהל\"ל בראת כמ\"ש בראשית ברא אלקים. אך הענין הוא שהתהוות כל העולמות הוא מבחי' שמו ית'. ושם ואור הוא בחי' אחת, שפי' אור הוא הארה בעלמא שאינו נוגע לעצמותו כלל, כמשל אור השמש או אור הנר שאינו נוגע להשמש או להנר כלל אם מאיר האור אם לאו, שאינו תופס מקום לגבי המאור ועד\"מ כשיש איזה מסך מסתיר או עננים המסתירים ומאפילים על אור השמש לבלי יאיר אורה אחר המסך לא יש שום שינוי בהשמש או בהנר, וכן כשלא יש דבר המסתיר והשמש או הנר מאירים בטוב, לא יש שום תוס' וגירעון בהשמש כלל, וכמארז\"ל אלה תולדות השמים והארץ בהבראם כיום הבראם. ועד\"ז יובן למעלה ענין אור שהגם שבחי' אור הזה הוא כללות ההשתל', הנה אור זה אינו תופס מקום כלל ואינו נוגע אל עצמותו, ובחי' אור זה הוא בחי' אחת עם שם עד\"מ כי שם אינו עצמות כי שכל ומדות נק' בשם עצמות אבל שם אינו עצמות, הגם שע\"י אותיות השם נמשך חיות הנפש, אבל הוא הארה מצומצמת מאד שאינו נוגע לו קריאת השם כלל, כי לעצמו א\"צ להשם כלל כ\"א זולתו יקראנו בשמו אבל לעצמו א\"צ להשם כלל, כמ\"כ נבין שבבחי' אוא\"ס השם אינו נוגע כלל וכלל. ונמצא כי שם ואור הכל בחי' אחת הוא כו'.\n<b>והנה</b> בבחי' שם ואור הזה הוא בחי' מלכותך מלכות כל עולמים, ויש בזה שני בחי' הא' מ\"ש מלכותך, והב' הוא בחי' מלכות כל עולמים, שבחי' מלכותך הוא האור כמו שהוא כלול בעצמותו, והיינו כמו קודם שנבה\"ע שהי' הוא ושמו בלבד, ולכאורה אם לא הי' עולם מי קראו בשמו אלא כי שמו הוא האור והכח כמו שהי' כלול בעצמותו ואז האור הוא ביתר שאת ויתר עז וכמ\"ש בסש\"ב ממשל זיו השמש"],[2000580109,"כשהוא בכדור השמש הוא ביתר שאת, וזה שיאיר האור והשם הוא ירידה והשפלה, וזהו ההפרש בין מלכותך לבחי' מלכות כל עולמים, מלכותך הוא בחי' מל' דא\"ס שהוא בחי' האור כמו שהוא כלול בעצמותו. ולכן נאמר לשון נברא שמשמע מאליו, כי לשון בראת הוא בחי' כח הפועל בנפעל לשון זה אינו שייך כ\"א בשם אלקים שהוא האור המאיר לכל נברא בפרט, אבל בשם הוי' הוא לשון ונבראו מאיליו וממילא, ואם בשם הוי' נאמר לשון נברא מכש\"כ בשמו שהוא מל' דא\"ס. וזהו לשון נברא העולם ולא בבחי' התלבשות כח הפועל בנפעל וכן בנוסח שלנו נאמר אתה הוא לכן אומרים לשון נברא וזהו מלכותך. ומלכות כל עולמים הוא מל' דאצי' שהוא האור כמו שמאיר להוות עולמות בי\"ע, שזהו פי' מלכות כל עולמים שמהווה כל העולמות שבד\"כ נחלקים לג' בחי' בי\"ע כמ\"ש ולכבודי בראתיו יצרתיו אף עשיתיו, בראתיו הוא בחי' בריאה יש מאין כמו באדם אותיות המח' הם ראשית הגילוי, הגם שיש אותיות בקדמות השכל ג\"כ אבל אינם מורגשים עדיין, וראשית ההרגש הוא במח', אך מח' הוא עדיין העלם כי אם יחשוב כל היום לא ידע זולתו כ\"א כשבא אח\"כ בבחי' הדבור שבא לגילוי בדיבור בחי' ההעלם שבמח' שהדיבור מגלה העלם מחשבתו. ועד\"ז יובן למעלה שבחי' בריאה נק' חשך והעלם, ויצי' נק' אור כמ\"ש יוצר אור ובורא חשך, והיינו שבחי' יצירה מגלה העלם הבריאה, וכענין חומר וצורה שהצורה הוא ציור הדבר מגלה העלם החומר כו', ובד\"כ בחי' בריאה הוא בחי' ג\"ע תענוג הנשמות ויצי' הוא בחי' עולם המלאכים. אף עשיתיו עולם הגלגלים. ובכללות בחי' ההשתל' נחלק ג\"כ לג' בחי' והם ג' מיני אדם, אדם דבריאה בחי' א\"ק מח' הקדומה, ואדם דיצי' הוא בחי' כתר בכלל, ואדם דעשי' הוא בחי' אצי', וזה\"ע מ\"ש בהבראם בה' בראם שתמונת הה\"א הוא ג' קוין ששני קוין מחוברים וקו א' הוא נפרד, והוא מרמז שב' עולמות בריאה ויצי' הם מחוברים זל\"ז והם בבחי' הביטול ביותר וכמ\"ש וצבא השמים לך משתחוים, אף עשיתיו הפסיק הענין, שזהו כמו רגל השמאל שבה\"א שהוא נפרד ונפסק מן הב' קוין להורות על המקור לבחי' העשי' ועוה\"ז הגשמי כו'.\n<b>והנה</b> מצד ירידת ההשתל' נשתלשל בחי' מצרים דקליפה ג\"כ, כי את זה לעו\"ז עשה האלקי', שכמו בקדושה יש ד' בחי' אבי\"ע כמו\"כ בלעו\"ז יש ג\"כ ד' בחי' אלו והוא בחי' ק\"נ וגקה\"ט, נוגה הוא בחי' אצי' דקליפה וגקה\"ט הם בחי' בי\"ע, וז\"ע מצרים דקליפה, וכדי להיות יציאת מצרים א\"א להיות מבחי' ממכ\"ע, שהרי מבחי' זו משתלשל בחי' מצרים, שמצד ריבוי ההשתלשלות נשתלשל להיות גם ד' בחי' דלעו\"ז כנ\"ל שהם הם המצרים כו', כי ע\"י המצרים והגבלה דקדושה נעשה מזה ריבוי ההעלמות וההסתרים, כי עולם הוא מלשון העלם והסתר, עד שמתהווה מצרים דקליפה. ולכן כדי לצאת מבחי' המצרים האלה זהו ע\"י גילוי בחי' היותר עליונה, והיינו בחי' מלכותך בחי' מל' דא\"ס, וזהו\"ע עד שנגלה עליהם"],[2000580110,"מלך מלכי המלכים שהוא בחי' מלכותך, ועי\"ז וגאלם לצאת מהמצרים וגבולים כו'.\n<b>וזהו\"ע</b> הנר שמאיר את החשך, והיינו שכמו הנר הגשמי מאיר את חשכת הבית, כמו\"כ מה שנמשך הארה מבחי' מלכותך שזהו כמשל אור הנר עי\"ז האיר את חשך גלות מצרים, ועי\"ז נגאלו אבותינו ממצרים הם בחי' המיצר וחושך הגלות. והנה בנר יש בד\"כ שני בחי' שמן ופתילה, שמן הוא בחי' חכ' שמן משחת קודש בחי' חכ\"ע שבה מאיר גילוי אוא\"ס ב\"ה, להיות כי חכ' הוא בחי' אחד האמת בחי' ביטול הוא כלי להשראת אא\"ס, והיינו שהחכ' הוא כלי שישרה בה האור מבחי' מלכותך מל' דא\"ס, והפתילה הוא בחי' מדות והיינו בחי' יסוד ז\"א, וז\"ע הנר שמאיר את החשך כי ע\"י חכ' ומדות מאיר הארה מבחי' מל' דא\"ס להאיר במל' דאצי' בחי' ממכ\"ע, ועי\"ז האיר את החושך ונמשך יציאת מצרים.\n<b>והנה</b> אנו רואים שהמדליק הנר הוא האדם שהוא מדליק את הנר, ולהבין זה בנמשל, הענין הוא דהנה באדם יש ג\"כ בחי' נר כמ\"ש נר הוי' נשמת אדם שנמשלה נשמת האדם לנר, והיינו שכמו בנר יש שמן ופתילה כמ\"כ בעבודה בנשמת האדם השמן הוא בחי' חכ' וביטול של הנה\"א שמברר ומעלה את הנה\"ב, והפתילה הוא בחי' יר\"ת וז\"ע נר ה' נשמת אדם, והכוונה בפי' פסוק זה שע\"י נשמת אדם יכול להאיר בחי' נר הוי' והיינו שע\"י שמאיר בנפשו בחי' הנר שלו יוכל להמשיך בחי' נר ה' להאיר את החשך דגלות מצרים, וזהו כי נר מצוה שנמשלו המצות לנרות, כי על המצות מברכים ברוך אתה כו' אלקינו מלך העולם אשר קדשנו במצותיו, פי' מלך העולם הוא בחי' ממכ\"ע שבריבוי ההשתלשלות נשתלשל מזה בחי' מצרים העלם חשך הגלות, ואשר קדשנו במצותיו הוא כמאמרם הקב\"ה מניח תפילין הקב\"ה מתעטף, וזהו במצוותיו ממש, וע\"י המצות ממשיכין מבחי' תר\"ך עמודי אור, וזהו כי נר מצוה שהמצות הם בחי' נר להאיר את החשך, וזהו\"ע שהגאולה הי' ע\"י משה ואהרן כמ\"ש באו משה ואהרן וגאלום כי אהרן הוא בחי' שושבינא דמטרוניתא המעלה את הנרות הם נש\"י, שהנשמה היא בחי' נר ואהרן מעלה אותה שתאיר נרה, כמ\"ש בהעלותך את הנרות, ומשה הוא בחי' השמן הוא בחי' חכ' כו' יסוד אבא, ועל ידם נמשך האור דנר דבחי' מלכות דא\"ס בחי' מלכותך בבחי' מל' דאצי' בכדי להיות הגאולה דיצי\"מ, הגם כי מעצמו נגלה עליהם ממה\"מ, אך מפני זה הגילוי היו יכולים לקבל הכל, והם המשיכו במל' דאצי' שהוא דוקא לנש\"י.\n<b>והנה</b> כדי לקבל בחי' זו זה\"ע מה שנצטווינו לאכול מצה שהמצה הוא כלי לגילוי אור זה כי מצה הם אותיות מצוה, רק שבתיבת מצוה ניתוסף אות וא\"ו, והיינו כי המצוה הוא בוא\"ו להורות על ההמשכה שנמשך ע\"י עשיית המצות, והמצה להיותה רק כלי להמשכת המצות הוא מצה אותיות מצוה בלא וא\"ו להורות"],[2000580111,"שהיא רק כלי לקבלת האור כו'. וביאור ענין מצה הנה ההפרש בין חמץ למצה שהחמץ הוא בחי' הגבהה והתנשאות ומצה הוא ביטול ושפלות, כי הכלי לגילוי א\"ס הוא ביטול ושפלות כמ\"ש מרום וקדוש אשכון ואת דכא ושפל רוח, וחמץ יש בו טעם חמיצות משא\"כ מצה אין בה טעם, ונק' בזהר מיכלא דמהימנותא והיינו שאמונה אינה ע\"פ טעם ודעת כ\"א ביטול שלמעלה מן הטעם ודעת, והמצה להיותה בחי' ביטול ושפלות היא מיכלא דמהימנותא שהיא האכילה שע\"י תתחזק בחי' האמונה, כי באמת יש הרבה בחי' שאי אפשר לבוא להשיג ע\"פ הטעם ודעת וכמ\"ש כל שאור וכל דבש לא תקטירו ממנו, והחילוק שבין אותיות חמץ לאותיות מצה הוא בין אות חי\"ת לאות ה\"א, שהחמץ הוא בחי\"ת ומצה הוא בה\"א, ונת\"ל שתמונת הה\"א מרמז על ג' עולמות בי\"ע שהם בבחי' הביטול כענין וצבא השמים לך משתחוים, אבל חמץ הוא בחי\"ת ל' חטא כי רומז על בחי' בי\"ע שבלעו\"ז, והיינו בחי' גקה\"ט שהם ההיפוך מבחי' הביטול כו', וכאשר נמשך אור הנר בכלי המצה אזי נעשה מבחי' מצה מצוה כי ע\"י ההמשכה מיתוסף הוא\"ו בתיבת מצה ונעשית מצוה. ועוד יש לפרש מצה לשון מצה ומריבה, והיינו כי המצה הוא בחי' ביטול היש שהיש הוא עדיין בשלימות ולכן צ\"ל מצה ומריבה בבחי' מלחמה עם הנה\"ב בכדי שיהי' ביטול היש כו', וזה\"ע מצה שמורה כמ\"ש ושמרתם את המצות, כי הנה הלילה הוא בחי' ההעלם וההסתר ובחי' היש עדיין בשלימות, רק שהמצה הוא בחי' ביטול היש, מ\"מ היש הוא עדיין בשלימות ואפי' כשנמשך הנר להאיר את החושך דלילה, הנה הלילה הוא חשך עדיין כמו שהיתה קודם, כי החושך כדקאי קאי, רק שהנר מאיר את החשך מ\"מ הלילה עצמו הוא כמו שהי' קודם לזה, וזהו מ\"ש ליל שמורים הלילה הזה כיון שהלילה הוא חושך עדיין, רק שנמשך בה בחי' זו להאיר את החשך, מ\"מ צ\"ל ליל שמורים שצריכים שמירה, שמאחר שהיש הוא הרע שבמדות הוא בשלימות ובמקומו, לכן צ\"ל בחי' שמירה שלא יפול ח\"ו בישות כו', וכמו שבגשמיות בלילה מצוי מזיקים. וזה\"ע ג' משמרות הוי הלילה משמרה ראשונה חמור נוער שהוא בחי' קליפות, ולכן צ\"ל שמירה וזהו\"ע מצה שמורה.\n<b>ובזה</b> יובן ענין החיפזון והוא ע\"ד שנת' בתניא שיש ב' בחי' בעבודה אתכפיא ואתהפכא, שבחי' אתהפכא הוא כאשר נהפך הרע וכמ\"ש וכמ\"ש אוהבי ה' שנאו רע, מואס ברע שהוא עוד יותר משנאו רע וזהו בחי' צדיקים, ובחי' בינונים הוא בחי' אתכפיא שהרע הוא בתקפו כתולדתו רק שמוח שליט על הלב, והעצה לבינונים הוא לברוח מהרע, וזה\"ע בחי' יצי\"מ שנאמר כי ברח העם שברחו מהרע, כי הרע הי' עדיין בתוקף אצלם רק שברחו מהרע כמ\"ש בסש\"ב. והבריחה היא"],[2000580112,"בתורה היינו לקשר מחדומ\"ע בתומ\"צ, היינו לקשר מחשבתו ודיבורו במח' ודיבור התורה, ובחי' המעשה במעשה המצות ועי\"ז ממילא יתבטלו המדות רעות, כי המדות הם מדות האדם, וכשמקשר מחדומ\"ע שלו במחדומ\"ע דתומ\"צ הגם כי מחדומ\"ע הם רק לבושים מ\"מ הרי הם מחדו\"מ של הקב\"ה, וכל הקורא ושונה הקב\"ה קורא ושונה כנגדו, וגם ניתן הכח להיות מוח שליט על הלב, לכן מתבטלים המדות רעות עי\"ז להיות בבחי' אתכפיא בחי' ביטול היש כו', וזה\"ע החיפזון והיינו מפני כי הרע עדיין בתוקפו ולכן הי' צ\"ל כי ברח העם, וזה\"ע המשל שהדליק את הנר בלילה שלילה הוא בחי' החושך והוא עדיין כמו שהי', רק שהדליק את הנר להאיר את בחי' החושך, וכבה, כי עבירה מכבה מצוה היינו בחי' הנר מצוה. כי בתיבת נר יש שני פירושים הא' שמן ופתילה והב' הכלי שמקבל את השמן, והמצות הם או השמן ופתילה, או הכלי, אבל לא אור, ולכן ישראל אחר יצי\"מ היו פעם כך ופעם כך ר\"ל פעם חטאו והיו במדריגה שפילה וכשעשו תשובה נתעלו, ואין עבירה מכבה תורה כי תורה הוא בחי' תורה אור כו'.\n<b>ובכדי</b> להבין מהו האור דתורה צ\"ל הלא אמרו רז\"ל ע\"פ במחשכים הושיבני זה תלמוד בבלי, וצ\"ל תחלה ההפרש בין תלמוד בבלי לירושלמי כי הנה בירושלמי אין שם חריפות ופלפולים כ\"א הלכה פסוקה הגם שהוא ג\"כ ע\"פ טעם מעומק המושג מ\"מ הרי אין שם חריפות, לבד ר\"י ור\"ל שעסקו בא\"י ג\"כ בפלפולים, אבל רוב התלמידים לא עסקו כ\"א בהלכה פסוקה, ובבלי הוא מלא חריפות ופלפול ורמינהו קושיות ותירוצים. והנה הפלפול בעצמו הוא בעצם חשך גמור עדיין כי אינו יודע עדיין האיך יבוא אצלו גמר הענין, כי הרי מאבד מה שהי' אצלו גם במושכל ראשון, אלא שאם עוסק בעומק יותר הוא ריבוי הפלפול, ואם במעט עומק ג\"כ מיעוט פלפול, הרי שהוא בעצם חושך אלא שמ\"מ יש בו הפלאת המושג שיצא לאחר העומק שגנוז ונעלם בעצם הפלפול, וא\"כ אם לאחר הפלפול בא לפסק ההלכה ה\"ה בא להפלאת המושג, ואם נשאר בהפלפול בלא הלכה פסוקה ה\"ה נשאר בהחשך. והחשך בעצם הוא יותר נעלה ממדריגות אור כמ\"ש יוצר אור ובורא חושך שהחושך הוא בריאה בפ\"ע, וכמו שאין ערוך בין יצי' לבריאה כן אין ערוך בין חשך לאור, וכשמגיע מתוך הפלפול להלכה פסוקה הרי אז נעשה החושך במדריגת אור כי החושך בעצמו נעשה אור, הגם שאור הוא ירידה לגבי החשך להיות אור, מ\"מ הרי האור הוא מהחשך בעצמו ואין זה שם דבר בפ\"ע, וזהו שאמרו שבבלי הוא חשך מפני הפלפול, ומ\"מ נק' בשם תורה אור כי מתוך הפלפול מתגלה ההלכה, ובזה יובן מה שבא\"י לא עסקו בפלפולים, כי הנה איתא בכתהאריז\"ל שכדי לשבר הקליפות הוא ע\"י קושיות ותירוצים, ולכן הי' עוסק האריז\"ל בפלפול עד שהי' מזיע בכדי לשבר הקלי', והנה בא\"י לא הי' כ\"א קליפת נוגה שהיא עדיין קרובה להקדושה"],[2000580113,"לכן לא הי' נצרך להם הפלפול, אבל בחו\"ל שאויר חו\"ל מטמא ויש שם גקה\"ט המעלימים ומסתירים לגמרי על אור האלקי לכן עסקו בפלפול בכדי לשבר הקליפה וזהו ותורה אור.\n<b>ובזה</b> יובן מה שהגאולה דעכשיו נק' בשם נר, הגם שיש לנו תורה הנק' בשם אור, כי התורה כמו שהיא למעלה בשרשה הוא אור ממש, אבל מ\"מ ה\"ה נתלבשה בגשמיות והרע עדיין בשלימות כי לא באו מהגאולה כ\"א לבחי' אתכפיא ולכן נק' בשם כיבוי, הגם כי אין עבירה מכבה תורה כמ\"ש טעמה כי טוב סחרה לא יכבה בלילה נרה, נרה דוקא שהוא אור התו' כמו שהיא למעלה עדיין בבחי' מקיף אין שם שום אחיזה כי המקיף מסמא כו' אבל כאשר נתלבשה בגשמיות הקלי' מעלימי' ומסתירי' לגמרי. ועוד כי בתיבת נרה יש שני פירושים מלשון אור ומלשון נר הכלי. כי לימוד התורה היא מצוה ג\"כ לכן נק' בשם נר.\n<b>והנה</b> כ\"ז הוא מפני שהגאולה הי' ע\"י בשר ודם כי גוף האדם הוא הווה ונפסד, ואפי' משה רבע\"ה, ולכן שרש המשכתו מאתר דאשתני, אלא שהמשיכו הוא\"ו במצה ונעשה מצוה. אבל אור התורה כמו שהוא למעלה לא המשיכו, אבל לעתיד תהי' הגאולה ע\"י הקב\"ה ולכן לא יהי' שינויים כי יהי' מבחי' אני הוי' לא שניתי. וז\"ש לע\"ל והי' אור הלבנה כאור החמה שהלילה בעצמה כיום תאיר בחי' שמש ה' ויהי' ע\"ד אתהפכא, ולכן לא בחיפזון תצאו שלא יהי' צריך לברוח מהרע שכללות העולם יזדכך ויהי' אור הלבנה כאור החמה וממילא יזדכך האדם ג\"כ וכמ\"ש והסירותי את לב האבן מבשרכם ואת רוה\"ט אעביר מן הארץ שלא יהי' רע כלל ולכן לא בחיפזון תצאו כ\"א בשובה ונחת תושעון שהוא בחי' ישוב הדעת. אבל יצי\"מ מאחר שהוא רק ביטול היש שהרע עדיין בתוקפו הי' צ\"ל כי ברח העם בחי' חיפזון.\n<b>ובזה</b> יובן הנס דחנוכה שטמאו כל השמנים להורות על ביטול תורה להשכיחם כו', ומצאו פך א' של שמן חתום ששמור ממגע, שאין שם אחיזה, ומשם הוא החזרת התומ\"צ וזהו אור תורה. ומ\"מ לא קבעו רק בנרות כי הגאולה הי' ע\"י בו\"ד שנקרא בשם נר, אבל לע\"ל יהי' אל הוי' ויאר לנו בחי' אור, ולא יהי' שינויים ולילה כיום יאיר, שהחשך עצמו יתהפך לאור כי הגאולה יהי' ע\"י הקב\"ה. וזהו כי עמך מקור חיים באורך נראה אור שלע\"ל יאיר אור התו' כמו שהוא למעלה ואז יהי' נראה אור גם למטה."],[2000580114,"<h3>מקץ שנתיים ימים</h3>\n<b>(בס\"ד, ש\"פ מקץ ל\"ב).</b>\n<b>מקץ</b> שנתיים ימים כו' פי' בזח\"א ר\"פ מקץ דקצ\"ג א' מאי שנתיים ימים דתב דרגא לדרגא דאית בהו זכירה ופי' בזה\"ח דרגא מל', לדרגא כו' זכירה יסוד, והכוונה שנתייחדו ונתחברו אלו הנק' שנתיים ימים ואז ופרעה חולם, וע\"י החלום ההוא נתעלה במעלות עכ\"ל. משא\"כ קודם היחוד כתי' ולא זכר, שלא נתגלה הזכירה.\n<b>והנה</b> בפי' מקץ פי' בלק\"ת מהאריז\"ל שהוא קץ הימין, ובזהר לא פי' כן כ\"א על קץ הימים. אמנם נראה כפי' האריז\"ל דענין קץ הימין היינו קץ למ\"ש השיב אחור ימינו, ומאחר דשנתיים ימים הו\"ע היחוד ע\"כ צריך להיות וימינו תחבקיני שזהו ע\"י קץ הימין. וכ\"מ מפי' המד\"ר שהעיר מפסוק קץ שם לחשך ולכל תכלית הוא חוקר אבן אפל וצלמות (איוב ך\"ח ג') זמן נתן לעולם כמה שנים יעשה באפילה, ומה טעם קץ שם לחשך שכל זמן שיצה\"ר בעולם אופל וצלמות בעולם, נעקר יצה\"ר מן העולם אין אופל וצלמות בעולם עכ\"ל. (ולפמש\"נ בבה\"ז פקודי בענין קנה המידה יצה\"ר טוב מאד, יש להשוות המד\"ר עם הזח\"א שקאי על קץ הימים).\n<b>וביאור</b> הענין יובן בהקדם ההפרש בין קץ הימין ובין קץ הימים, דהנה יש בחי' קו המדה וקנה המדה, קו המדה הוא בחי' בוצינא דקרדוניתא שהוא בחי' גבורה דעת\"י המלובש במוחא סתימאה, שהוא קו המדה שבו נמדד כל אורות וכלים דאצי', והוא בחי' שיעור קומה, שיעור לכל דבר דאור פנימי, ושורש קו המדה הוא בעצמיות המאציל, כי כמו שעצמיות ההשפעה נמשך מעצמו' המאציל, כן נמשך כח המעציר כו' לבל יתפשט בל\"ג, דאל\"כ הי' הכתר בל\"ג ולא הי' יכול להיות התהוות חכ', וכן מחכ' לבינה ומבינה למדות צריך להיות הגבלה ועצירה, ועד\"מ באדם בעת תוקף הרצון אינו יכול להיות בהתחכמות, ובתוקף השכל אינו יכול להיות מדה, ובתוקף המדה אינו יכול להיות הדבור וכנראה בחוש כו'. וכלליות כח המגביל הנ\"ל"],[2000580115,"נתגלה תחלה בחכ' סתימאה ונק' בוצינא דקרדוניתא, ואח\"כ מאיר בבינה פעם ב' ה\"ג דאימא, ואח\"כ עוד למטה ה\"ג דמל'. וכמשל מי שעלה ברצונו לבנות לו בית עם חדרים רבים, שתחלה הוא בבחי' הסכם הרצון בכל הפרטים, ואח\"כ מחשב באורך ורוחב המח' בכל פרטי', ואח\"כ במדידה בעת עשיית הפעולה. ועד\"ז יובן בחי' בוצינא דקרדוניתא ה\"ג דעתיק הוא מדידה שבהסכמת הרצון, וה\"ג דאימא השיעור במח', וה\"ג דמל' כח הפועל בנפעל להחיות נבראי' בע\"ג על אופן זה דוקא, וכ\"ה בכל אורות וכלים דאצי' שנמדדו ע\"י ה\"ג דע\"ק, וז\"א ע\"י ה\"ג דאימא. אמנם בחי' קנה המדה אינו מבחי' קו המדה וכמ\"ש בזהר לאו איהו בוצינא דקרדוניתא, אלא מתמן נפקת האי קנה כו' כד אסתלקת לעילא, פי' שקנה המדה הוא רק בחי' רושם מבחי' ה\"ג דאימא שנשאר לאחר הסתלקות בינה לחכ'.\n<b>וביאור</b> הדבר הוא כי יש בחי' קץ הימין, וקץ הימים שנמשך מקץ הימין, דארז\"ל טוב זה מלאך חיים, מאד זה מה\"מ, כי טוב הוא בחי' חסד לבד, ואור החסד אינו מתעבה ואינו משתנה, ואפי' לאחר הסתלקות החסד שנשאר רושם הוא ג\"כ חסד, ואינו יכול להתהוות ממנו קלי' גמורה, וזהו טוב זה מלאך חיים שלעולם טוב. אבל מה\"מ נמשך מבחי' טוב מאד הוא בחי' גבורה שבחסד שנק' מאד ע\"ש תגבורת החיות, ומ\"מ מזה נמשך צמצומי' והתחלקות הוא בחי' קץ הימין בחי' המדידה בצמצומי' והתחלקות, אך לאחר שנסתלק בחי' קו המדה גבורה שבחסד, אז מהרושם נעשה גבו' קשות שהוא קץ הימים שהוא מה\"מ בחי' כליון של כל דבר ונפסד לגמרי. וההפרש הוא בין מדידת התיקון למדידת התהו, שבתיקון הוא קו המדה כנ\"ל אבל בתהו להיותם בבחי' גבו' אורות תקיפין לכן בהסתלק קו המדה נשאר רק גבו' קשות, והמדידה הוא ע\"י קנה המדה בחי' גבו' הנ\"ל. וזהו ההפרש בין זהב לנחושת, זהב הוא גבורה שבחסד או עוד גבוה יותר ולכן רק נוטה לאדמימות, אבל נחושת אדום גבו' קשות, ולכן נא' ומצחך כנחושה וקאי על עזי פנים שקשי' בטבע, וכתקיפות הבהמה על האדם דתיקון שהוא רק רך כקנה כו'.\n<b>והנה</b> בבחי' קץ הימין שהוא בחי' מל' כנ\"ל שנק' אחרית ונק' ים סוף סופא דכל דרגין הוא נעוץ סופן בתחלתן, וי\"ל שזהו קץ הימין שאזי יומשך ממנה אור חוזר ותהי' המל' בבחי' כתר ולכן אחרית גימ' כתר, וזהו מ\"ש מבלי אשר ימצא האדם כו' מראש ועד סוף, שבקדושה גם הסוף הוא ראש, וכוונת נעיצת התחילה היא יותר בסוף מבראש המתפשט כמשנ\"ת בד\"ה ועמדו רגליו, וי\"ל שזה\"ע עד"],[2000580116,"שתכלה רגל מן השוק להעלות רגל השמאל ואז יהי' קץ הימין, אמנם יש קץ דשמאלא וזהו קץ הימים דקין, ובזהר פי' דמקץ הוא הוא קץ דשמאלא שמזה נמשך וישכחהו, ועד\"ז פי' בת\"א קץ ותכלה לבחי' השנתיים ימים שזהו קץ הימים דקין, אמנם האריז\"ל פי' קץ הימין כנ\"ל.\n<b>ולהבין</b> ענין השנתיים ימים כי יש ב' בחי' שנה, הא' בנוק' כמ\"ש בזח\"ג תצא דרע\"ח ב' ע\"פ נקי יהי' לביתו שנה הם י\"ב ירחין י\"ב בקר, והשנה מל', ונק' שנה ל' שינוי שמשם ואילך התחיל עולם הפירוד הנראה ליש ודבר נפרד, וכמו ימי הלבנה שנ\"ה שנק' יומין תתאין בזח\"ג פנחס ד\"ר, והיינו להיות הלבנה משנה אור החמה, וכולד בבטן אמו (אמנם זהו למעליותא). ויש שנה בדכורא יומין עילאין והיינו ת\"ת נק' שנה בחי' שמש, או בינה. ואפ\"ל שזהו גילוי אני ה' לא שניתי, ולכן ל\"ת הם שס\"ה כמנין כו' גילוי שמש ה' לא שניתי, וי\"ב ר\"ח י\"ב גבולי אלכסון דז\"א, וא\"כ התחברות שנתיים ימים ב' בחי' שנה וב' בחי' יומין ע\"ד משכו יומין עילאין כו' כימי השמי' כו', ואז עלה זכרון יוסף ע\"ד מלכיות זכרונות מל' ויסוד, ופי' זכרונות ע\"ד וגם את נח כו' זכרת, וזכרתי את בריתי יעקב שהוא ענין ההנהגה שלמעלה מהטבע שבחי' זו נמשך מעלמא דדכורא, יומין עילאין, משא\"כ מנוק' בחי' טבע הבריאה יומין תתאין, וגם איש דרכו לכבוש, לכן דוקא ע\"י חיבור שנתיים ימים כו' המשכת יומין עילאין ע\"ד כי ה' הוא האלקי' עלה זכרונו של יוסף להיות ופרעה חולם עד שנמשך לו הגאולה שלא ע\"י סדר והנהגה, וכמארז\"ל שראה עולם חדש אתמול כו' והיום כו', וכ\"ז נמשך לו מדרגא דילי' יוסף ל' תוס' אור להיות חיבור שנתיים. והנה בת\"א פי' שנתיים ימים זהו ענין שעשועי' יום יום, וי\"ל כי מקור יחוד ו\"ה בחי' שנתיים הוא ע\"י יחוד י\"ה יום יום, יחוד או\"א ואח\"כ זו\"נ, וכענין ב' בחי' חו\"כ כלתה נפשי כלה שארי, וכ\"ז המשיך יוסף ע\"י מסירת נפשו לה' והיסורי' שעברו עליו מחמת שעמד בנסיון.\n<b>ומעתה</b> יובן ענין קץ שם לחשך דהנה בפרד\"ס ע' חשך כ' ג' מיני חשך, הא' בכתר, ב' גבורה, ג' בקלי', והיינו כי ע\"י הבירור דחשך דקלי' עי\"ז יאיר אור חשך דכתר דלית מח' תפיסא בי' כלל, אוכם הוא כו', וזהו שפי' רש\"י קץ שם המקום לשמים שימלחו כו'. ובעבודה חש\"ך זהו חמור שור כלב, חמרא בתקופת תמוז קרירא לי' שמש ה' לא שניתי ומ\"מ הוא בקרירות, שור נגח, כלב חוצפה"],[2000580117,"ועקשות יודע את רבונו, ועז\"נ הצילה כו' מיד כלב יחידתי שפוגם ביחידה שבנפש, וע\"י חשך דקדושה כו' כשור לעול וכחמור למשא לסבול עול תורה ישכר חמור גרם, בכור שורו ורב תבואות בכח שור, והנגיחות זה\"ע קושי' ותירוצי', וכלב י\"ל עמא פזיזא הקדמת נעשה שז\"ע קבלת עול מלכות שמים ה\"ז היפך יודע את רבונו, עי\"ז יתגלה חשך דכתר וכמ\"ש בכ\"ד (על כל כבוד) שא\"א להיות גילוי מכתר כ\"א כשיהי' ואת רוח הטומאה כו'. וזהו קץ שם לחשך דקלי' בכדי שיתגלה האור. והנה לכאור' הי' אפ\"ל המד\"ר כפי' הזהר קץ הימים שהרי יצה\"ר הוא בחי' קץ הימים כנ\"ל גבורות הוא היצה\"ר יורד ומסטין ועולה ומקטרג, אמנם באמת לא כן הוא שהרי מפרש כ\"ז שיצה\"ר בעולם הוא בחי' קץ הימים דקין אזי אופל, נעקר יצה\"ר שאז יהי' גילוי אלקות ה\"ז בחי' קץ הימין."],[2000580118,"<h3>הקבצו ושמעו בני יעקב (א)</h3>\n<b></b><b>בס\"ד. (ש\"פ ויחי, ל\"ב).</b>\nויחי\n<b>הקבצו</b> ושמעו בני יעקב ושמעו אל ישראל אביכם, וארז\"ל במד\"ר פצ\"ח ר' פנחס אמר אל הוא ישראל אביכם, מה הקב\"ה בורא עולמות אף אביכם בורא עולמות מה הקב\"ה מחלק עולמות כו'. וכן ארז\"ל במגילה פ\"ב י\"ח א' ע\"פ ויקרא לו אל אלקי ישראל שהקב\"ה שהוא אלקי ישראל קרא ליעקב אל, וכ\"ה במד\"ר וישלח ספע\"ט אני אלקה בעליונים ואתה אלקה כו' וכ\"ה בזח\"א תולדות קל\"ח א', ופי' המק\"מ דאלקי ישראל שהוא בינה שהוא אלקה של ז\"א הנק' ישראל, והוא קראו ליעקב אל. וי\"ל דיעקב קאי על בחי' מל' יו\"ד עקב שנק' ג\"כ אל שיש בה בחי' עליונה מז\"א שבמחשבה ארץ קדמה, ונמצא שהמשכת אוא\"ס בז\"א הוא ע\"י המל'"],[2000580119,"והיינו בכדי להאיר בבי\"ע, ולכן הארץ דוקא תוציא צמחה מאין ליש, אבל משמי' לא נצמח מאומה להיות כי כמו והחכ' מאין תמצא כן מאין דמל' מתהוה בי\"ע, שכח זה בארץ מל' דוקא, וכל מה שנותני' לז\"א הוא בשביל שפע למל' שהוא ע\"י ז\"א. ולכן בזמן הגלות הצדיק אבד מלקבל ברכאין כו'. גם כי המל' יורדת לברר בירורי' דבי\"ע. וז\"ע ואתה אלקה בתחתוני' שע\"י הבירורי' ממשיכי' גילוי אוא\"ס ע' בביאור ע\"פ את שבתותי תשמורו.\n<b>ושורש</b> ענין מה שקרא ליעקב אל הוא, כי אל הוא נהירו דחכמתא, וי\"ל בב' דרכי', הא' ע\"פ מ\"ש בס\"י בל\"ב נתיבות פליאות חכ' חקק כו', שבד\"כ נחלק על ל\"ב נתי', וכתי' נתיב לא ידעו עיט, שיש נתיב אחד שלא ידעו, וכמו שבשערי' דבינה שער החמישים לא נתגלה כ\"א למשה קודם הסתלקותו שעז\"נ ותחסרהו מעט מאלקי' דבינה, רק בעת עלייתו בהסתלקותו, ולכן לעליוני' נדמה כו' שזהו שער החמישי', כן בחכ' נתיב אחד לא ידעו עיט, ונשארו ל\"א, והוא בחי' מעשר ממחצה דתר\"ך שהם ש\"י עולמות דא\"א, וזהו קראו ליעקב אל. והדרך הב' הוא כי קנה חכ' קנה בינה ב\"פ קנה עולה ש\"י מחצה מתר\"ך אורות דכתר שמתלבשי' באו\"א, ובחי' אל היינו מעשר מיש, והוא בחי' מל' דאבא הנמשך ביעקב שהוא מדות דאצי' ת\"ת וכמ\"ש בזהר ע\"פ ויקח לו יעקב מקל לבנה לח ולוז כו', וא\"כ מה שנק' יעקב אל זהו ע\"ד יחוד אוא\"ס בכלי' דאצי' דאיהו וגרמוהי חד. אך צ\"ל איך יתכן זה על יעקב שלמטה שהי' רק מרכבה לת\"ת ז\"א דאצי' ולא ז\"א ממש.\n<b>וילה\"ק</b> מ\"ש רבינו ע\"פ מ\"ש בזח\"ב פ' בא דל\"ח א' מאן פני האדון ה' דא רשב\"י, דאיך אמרו זה על הנברא, דהנה כתי' למען אחי וגו' שלום בך, ופי' שלום הוא השפעת יסוד ז\"א במל' בחי' שפע הפנימי', ואומר שלמען אחי נמשך השפעה והמשכה זו. וי\"ל מי הם אחי, גם צלה\"ב מ\"ש בזהר דרשב\"י אמר על עצמו אנא סימנא בעלמא שלכאו' זהו רוממות והתנשאות מאד שאין זה מדרכי הצדיקי'. אך הענין דבראשית האצי' עשר ספירות באורות וכלים נאצלו עמהם בחי' נשמות"],[2000580120,"דאצי' ונק' אחי' ורעי' לז\"א. דהנה יש הפרש גדול בין אצי' כמו שהוא נמשך ומלובש בבי\"ע לכמו שהוא באצי' ממש, וע' ברמ\"ז ר\"פ משפטי' שיש ג' מדריגות בכלל, הא' נשמות דבי\"ע ממש, הב' נשמות דאצי' רק שהם מאצי' דבי\"ע, הג' נשמות מאצי' העליון ממש, וא\"כ יש הפרש גדול בין אצי' ממש לאצי' דבי\"ע, וכ\"ש שיש הפרש גדול יותר מאצי' דבי\"ע לבי\"ע ממש, שהרי נשמה דאצי' לא תוכל לסבול דבר רע, ולא נא' נפש כי תחטא אלא על נפש דבי\"ע שהגם שיש בה ג\"כ בהכרח הארת האצי' המחי' אותה, והיינו בחי' הארת המל' דאצי' המחי' בי\"ע, עכ\"ז הוא בהעלם והסתר, והיינו בחי' הנשמות דבי\"ע ממש לפי' הרמ\"ז שע\"ז נא' נפש כי תחטא, וכמו דבמעשה דדוד נסתלקה ממנו שכינה, והיינו לפי שהאצי' היא בחי' אלקות ממש אשר שם לא יגורך רע, משא\"כ כשמסתתר כח האלקי לברוא יש מאין בבי\"ע אשר משם יפרד, שם שייך תערובות טו\"ר בלבושי' דבי\"ע. וא\"כ מאחר שהנשמות דאצי' הם בחי' אלקות ממש ולא נשתנו להיות יש ודבר נפרד, רק שלגבי הע\"ס דאצי' הם קטני' הרבה במדריגה בבלתי שלימות כמו הע\"ס, לכן הי' רשב\"י יכול לאמר אנא סימנא בעלמא, כי הנשמה שהיא יש ודבר נפרד הוא שאין שייך בה התנשאות, משא\"כ הנשמה דאצי' שהיא אלקות באמרו אנא סימנא זהו רוממות אלקות שבו, וכמו שא' משה בפ' והי' אם שמוע ונתתי עשב, לפי ששכינה מדברת מתוך גרונו, והי' בטל לגמרי לא\"ס שמדבר בו ונחנו מה, וזה הביטול האמיתי הוא רק בנשמות דאצי', שאצי' הוא בחי' חכ' כח מ\"ה ביטול אמיתי, ע' בסש\"ב פל\"ה בהג\"ה אחד האמת. ועד\"ז יובן ענין רשב\"י מאן פני האדון ה' דא רשב\"י מכיון שהי' נשמה דאצי' ממש, א\"כ לא הי' הנשמה שלו מסתיר כלל על אור האלקי אלא ביטול גמור. ע\"כ יכולי' לומר מאן פני כו' שהשכינה מלובשת בנשמתו, ונשמתו אינה מסתרת, ואמנם בחי' זו הוא בנשמות היותר גבוהי' כמו רשב\"י.\n<b>אמנם</b> עדיין צ\"ל שכ\"ז אינו נוח לי עדיין, הלא ידוע שגם הע\"ס דאצי' ממש מה שנק' בשמות שאין נמחקי' כמו אל אלקי', אין הכוונה על הע\"ס ממש אלא על האור המלובש בהן, שאוא\"ס כשמלובש בחסד נק' אל כמ\"ש במ\"א, וא\"כ הנשמות דאצי' כיון שכבר נפרדו מהכלי' דאצי' ואין הקו מאוא\"ס מלובש בהן, א\"כ האיך"],[2000580121,"שייך לקרותם בשמות הבורא, דהא אפי' הע\"ס לא נק' בשמות הבורא רק מפני שהקו מאוא\"ס מלובש בהן, ועמ\"ש רבינו באגה\"ק ד\"ה איהו וחיוהי בענין נשמות דאצי', וז\"ל אך אינן אלקות ממש לברוא יש מאין, מאחר שכבר יצאו ונפרדו מהכלי' דע\"ס דאצי' שבהן מלובש הקו מאוא\"ס שהאור הוא כעין המאור עכ\"ל.\n<b>מיהו</b> י\"ל זהו הנשמות דאצי' כמו שהן, אבל הרי ירידתן בעוה\"ז הוא צורך עלי', וע' בת\"א ד\"ה זכור ושמור שהעלי' שיהיו נכללי' ביחוד דאיהו וחיוהי חד, ונק' לאשתאבא בגופא דמלכא ממש, ואז יהי' הקו מאוא\"ס מלובש בהן כמו שמלובש בגופא דמלכא, וז\"ע למען חייך שהוא יהי' החיות שלך ממש והם יהיו כלי' להחיות, וי\"ל ע\"ד עצו כפריו, וידוע דהאדם הוא עץ השדה, וע' בד\"ה ושמתי כדכד תוך פ\"ב, ועוד שיתעלו להתייחד בגילוי אורות מקיפי' מה שאינו מתגלה עתה אפי' בכלי' דאצי' יעו\"ש, ונמצא כי מתורץ ענין מאן פני האדון כו'. והגם כי זהו ע\"י תומ\"צ מ\"מ י\"ל הלא קיים אברהם וכן כל האבות בעובדות שלהם כו'.\n<b>ועוי\"ל</b> לתרץ עם מ\"ש באגה\"ק ססי' ך\"ה, וז\"ל דהא אשכחן דהא אפי' מלאך נברא נק' ה' בפ' וירא לפי' הרמב\"ן וכמ\"ש ותקרא שם ה' הדובר אלי' וכה\"ג טובא עכ\"ל. ובסוף הקו\"א שם כ' הרי נודע שכל מלאך שהוא שליח מלמעלה אזי נק' בשם ה' ממש השוכן בקרבו, משא\"כ כשאינו שליח יש לו שם אחר כפי עבודתו, ואזי קורא קדוש קדוש קדוש ה' וגו' כלומר ששם ה' מובדל ממנו עכ\"ל. וכיון שאפי' מלאך נברא מבי\"ע ממש כשהוא שליח נק' בשם ה' ממש השוכן בקרבו, מכ\"ש נשמה דאצי' ממש שהיא בעצם אלקות שכאשר ה' שוכן בקרבו ע\"י עסק התורה והמצות שהם ארחות ה' ממש, תר\"ך עמודי אור דכתר עליון יכולי' להיות נק' בשם ה' ממש,"],[2000580122,"גם בעודן מלובשים בגוף. וזהו כל הנק' בשמי, ובגמ' פ\"ה דב\"ב דע\"ה ב' עתידים צדיקי' שיקראו ע\"ש של הקב\"ה ע\"ש בפרש\"י שיהי' שמם הוי', והיינו שלע\"ל יהי' בהם גילוי אוא\"ס ע\"ד שמלובש בע\"ס דאצי' וזהו והתהלכתי בתוככם, אלא שזהו רק לע\"ל, אבל אבות העולם שארז\"ל ספ\"ק דב\"ב שלשה הטעימן הקב\"ה בעוה\"ז מעין עוה\"ב א\"כ הי' בהם בחי' זו דעתידי' צדיקי' שיקראו ע\"ש של הקב\"ה כו'.\n<b>ועד\"ז</b> יובן מ\"ש במ\"א הקושי' שאומרי' בשמו\"ע אלקי אברהם כו', ולכאו' אלקי השמי' הוא שבח יותר, ונת' התירוץ דאדרבה אברהם שהוא חסד דאצי' א\"כ מה שהוא אלקי אברהם הוא שבח יותר, ולפי הנ\"ל א\"ש דכיון דאבות העולם הטעימן מעין עוה\"ב ולמעלה משאר נשמות דאצי' אלא ע\"ד גילוי אלקות בע\"ס דאצי' ולכן נק' יעקב אל, א\"כ מה שהקב\"ה נק' אלקי יעקב הוא שבח עצום יותר ממה שנק' אלקי השמי' שהם בריאה יש מאין א\"כ הוא בורא נבראי', אבל מה שהוא אלקי יעקב, אף שיעקב נק' אל להיות כי בו הי' גילוי אלקות עד שהי' יכול לברוא עולמות כמ\"ש במד\"ר כאן מה הקב\"ה בורא עולמות אף אביכם כו', וא\"כ כיון שהוא ית' בורא בריאה כזו הרי זהו לו שבח גדול יותר וכענין הודו לאלקי האלקי' כו' שהוא אלקה גם על מי שנק' אלקי' כמו יעקב כו'."],[2000580123,"<h3>להבין בתוס' ביאור שרש נשמות דאצי' (ב)</h3>\n<b></b><b>בס\"ד. (ש\"פ שמות, ל\"ב).</b>\nשמות\n<b>להבין</b> בתוס' ביאור שורש ענין נשמות דאצי' וענינם, וביאור ענין ל' המד\"ר שאמר מה הקב\"ה בורא כו' מה הקב\"ה מחלק עולמות אף אביכם מחלק עולמות דלכאורה צ\"ל מה\"ע מחלק עולמות."],[2000580124,"<b>ויובן</b> בהקדם מ\"ש מי הוא מלך הכבוד וגו' וארז\"ל במד\"ר פ' וארא פ\"ח למה קרא להקב\"ה מלך הכבוד שהוא חולק כבוד ליריאיו, כיצד מלך בשר ודם אין רוכבין על סוסו ואין יושבין על כסאו, והקב\"ה הושיב לשלמה על כסאו שנא' וישב שלמה על כסא ה' למלך (דה\"א ך\"ט), והרכיב לאליהו על סוסו ומהו סוסו של הקב\"ה סופה וסערה שנא' ה' בסופה ובסערה (בפ' כתיב ובשערה בשין שמאלית) דרכו (נחום א') וכתי' ויעל אלי' בסערה השמימה (מ\"ב ב'), מלך בשר ודם אין נקראין בשמו קיסר אגוסטא ואם נקראי' בשמו ממיתין אותו, והקב\"ה קרא למשה בשמו שנא' ראה נתתיך אלקי' לפרעה אמר הקב\"ה למשה פרעה הרשע עשה עצמו אלקה שנא' לי יאורי ואני עשיתיני (יחזקאל ך\"ט) לפיכך יראה אותך ויאמר שזה אלקה, פי' על כרחו יודה לומר עליך זה אלקה, וזהו שחלק מכבודו ליראיו. ומסיים כי גבוה מעל גבוה שומר וגבוהי' עליהם (קהלת ה'), והיינו הגם כי חלק מכבודו ליריאיו שז\"ע שקראו אלקים, מ\"מ אלקיך אנוכי שאני על גבך.\n<b>והענין</b> הוא דהנה משה הי' מאצי', ונודע שאצי' הוא אלקות כי ל' אצי' הוא מל' ויאצל מן הרוח, שהאציל מן הרוח אשר על משה ונתן על ע' איש הזקנים, ואם כי זהו כמדליק נר מנר זה נהנה וזה לא חסר כלום, מ\"מ ה\"ה נחשב להפרשת הארה, שענין ההארה הוא ג\"כ שלא חסר כלום מן המאור ע\"י הארתו כו', א\"כ אצי' הוא בחי' גילוי הארה מאלקותו ית', שלכן נק' אצי' בשם אלקות כו'. וגם ענין אצי' נת' במ\"א שז\"ע גילוי ההעלם מאלקות, שאלקות לרוב העלמו אינו מושג כלל וכלל, ולכן גם הכתר שהוא ממוצע בין המאציל לנאצלי' ה\"ה ג\"כ נעלם ונק' ישת חשך סתרו ע\"ש העלמו, ומה שנתגלה להיות נק' בשם חכים הגם שג\"ז עדיין חכים ולא בחכ' ידיעא, מ\"מ להיותו נק' בשם חכים ומבין נק' בשם אצי' שהוא בחי' גילוי ההעלם מאלקותו ית', משא\"כ בי\"ע הם נבראי' בע\"ג ונפרדי', ובחי' המל' דאצי'"],[2000580125,"מהוה בי\"ע בדרך יש מאין, אשר לכן נק' אצי' אלקות נגד בי\"ע, וכנודע ממארז\"ל אלמלא מתכנשין כל באי עולם אינם יכולים לברוא אפי' כנף יתוש א', כי יכולת הבריאה לברוא יש מאין הוא לאלקות לבדו. וא\"כ יובן שפיר מה שאצי' נק' אלקות שמל' דאצי' מהוה כל ג' עולמו' בי\"ע כו', וכמ\"ש באגה\"ק שאפי' בכלי' דאצי' מתייחד בהון לברוא ע\"י יש מאין כו'. ואי לזאת יובן שמשה נק' אלקי' להיותו נשמה מבחי' האצי' והרי האצי' נק' אלקות נגד בי\"ע, ולכן אמר לו ראה נתתיך אלקי' לפרעה וכן נק' איש האלקי' להיותו נשמה דאצי' כו'.\n<b>ומ\"מ</b> אמר לו אע\"פ שקראתי אותך אלקי' אלקיך אנוכי אני על גבך, שבאמת לגבי אוא\"ס אצי' ועשי' שוין וכמ\"ש כולם בחכ' עשית שגם החכ' נחשבת כעשי' גשמי' לפניו ית', שהרי א\"ק שגבוה הרבה מבחי' האצי', שאצי' נחשב בכלליות העולמות רק בחי' אדם דעשי', וא\"ק נק' אדם דבריאה, ומ\"מ א\"ק הוא ג\"כ רק אדם דבריאה, ולכן הגם כי משה הי' נשמה דאצי' שלכן נק' אלקי', מ\"מ אני על גבך שהרי גם א\"ק הוא רק אדם דבריאה אשר לגבי א\"ק נחשב האצי' רק בחי' אדם דעשי' לבד. ולכאו' עדיין צ\"ל הלא א\"ק בכלליות העולמות נחשב בחי' אדם דבריאה שזהו כמו עולם הבריאה בפרטיות העולמות, וא\"כ כמו שאצי' מהוה בי\"ע כמ\"כ אצי' דכלליות מהוה בחי' בי\"ע דכלליות, וא\"כ משה שהי' נשמה דאצי' בפרטיות העולמו' אשר לכן נק' אלקי', וכמ\"כ כאשר נדבר בכלליות העולמות בהכרח לומר ששורש משה הוא מבחי' אצי' דכלליות, וא\"כ צ\"ל מה\"ע אני על גבך כו'. אך הענין יובן ע\"פ מ\"ש בזהר\"ק דט\"ו ע\"א שיש כדוגמת עתיק לעילא מן גלגלתא דא\"ק שבחי' זו נק' אצי' דכלליות, וא\"כ אמר בחי' הא\"ס דסובב הכללי (המקיף ד' עולמו' אבי\"ע דכלליות בשוה והוא בחי' העיגול שלפני הקו) למשה שהי' מבחי' האצי' אם כי קראתיך אלקי' להיותך מבחי' האצי' שנק' אלקי' לגבי בי\"ע, מ\"מ אלקיך אנכי אני על גבך שהרי בחי' העיגול סובב אצי' דכלליות ג\"כ בשוה עם העשי' דכלליות. וזהו הגם כי חלק מכבודו ליריאיו פי' שקאי על נשמות דאצי' שנק' אלקות, ואמר ל' שחלק מכבודו, כי כבוד הוא גימ' ל\"ב והיינו בחי' ל\"ב נתיבות חכ', ונודע ממ\"ש בת\"ז שבאצי' מאיר בחי' חכ', ולכן נשמה דאצי' להיות כי בכל עולם האצי' מאיר חכ' לכן על נשמה דאצי' שייך לומר שחלק מכבודו היינו מבחי' ל\"ב נ\"ח שנק' כבוד כו'. ומ\"מ אלקיך אנכי אני על גבך שהרי העיגול מקיף את כולם בשוה כנ\"ל. וזהו שאה\"כ הודו לאלקי האלקי' פי' הגם כי משה נק' אלקי' וגם עוד איש האלקי', מ\"מ אלקיך אנכי וזהו הודו להקב\"ה שהוא אלקי האלקי' היינו הגם שקרא למשה אלקה כמ\"ש ראה נתתיך אלקי' לפרעה מ\"מ אלקיך אנכי אני על גבך כו' וזהו הודו לאלקי האלקי' כו'."],[2000580126,"<b>ועוי\"ל</b> ביאור ענין נשמות דאצי' שנק' בשם אל כמו קראו ליעקב אל, ומשה איש האלקי' ואלקי' לפרעה, דהנה כתי' ואם זרוע כאל לך ובקול כמוהו תרעם עדה נא גאון וגובה כו' (איוב מ' ט' יו\"ד) פי' שבאה המענה מאת ה' לאיוב מן הסערה אם זרוע כאל לך כו' עדה נא גאון וגובה, דמשמע דזהו דבר שא\"א בלתי לה' לבדו, ואין לאדם כח בזה גם לצדיקי' מופלגי', וכענין שנכנע יעקב לפני עשו, והלא אנו רואי' שצדיקי' יפילו לרשעי' ע\"י תפילתם. אך הענין הוא משום דשורש הצדיקי' הוא מש' מ\"ה דתיקון כידוע, ושורש הנפשות של הרשעי' המה מבחי' התהו שנפלו בשבה\"כ כמ\"ש הנפילי' היו בארץ כו' המה הגבורי' אשר מעולם אנשי השם, פי' מעולם הוא מעולם התהו שלפני בחי' התיקון וכמ\"ש ואלה המלכי' אשר מלכו כו' לפני מלך מלך לבנ\"י, והן הן תתקע\"ד דורות שקדמו עד שלא הי' בחי' התיקון, והמה העזי פנים ששתלן בכל דור ודור להתברר ע\"י ש' מ\"ה דתיקון והוא ע\"י הצדיקי' כו', ומאחר שבחי' התהו גבוה הרבה מבחי' התיקון איך יהי' ביכולת הצדיקי' להשפילם, וזהו שאמר ה' לאיוב עדה נא גאון וגובה, אחר שהם למעלה ממך.\n<b>אך</b> הנה יש להבין בזה דהרי לצדיקי' כבר ניתן כח ועוז להפוך רע לטוב ע\"י ש' מ\"ה המברר ב\"ן, וא\"כ הגם שרשעי' הם מבחי' התהו הרי ניתן בחי' תהו להתברר ע\"י ש' מ\"ה דתיקון כו', ולמה לא יהי' ביכולת הצדיקי' להשפילם והדרא קושי' לדוכתי'. אך עיקר הענין הוא דהנה יש הפרש בזה, דכאשר הרשעי' המה בשלימותם בלתי בירור עדיין לגמרי אז לא יש ביכולת הצדיקי' להשפילם ולהכניעם, אבל כשהרשעי' מתבררין ויוצא מהם חלק הטוב אזי יש ביכולת הצדיקי' להכניעם ולהאבידם כו'. וטעם הדברים כי כאשר המה בשלימותם הרי המה אנשי השם אשר מעולם התהו ממש, והם גבוהי' מבחי' התיקון ולא יכלו להם אותם אשר למטה מהם במדרגה. אך כשמתבררי' ע\"י ש' מ\"ה ויוצא מהם חלק הטוב ולא נשאר רק חלק הרע שהוא בא בשבירה הנשאר בהיכלו' החיצוני' שלמטה מטה אזי בנקל מאד שיפלו ויאבדו לגמרי וכמ\"ש כהמס דונג מפני אש כן יאבדו כו', כי רק מצד הטוב שבהם גבוהי' המה מבחי' התיקון, אבל לאחר שהוציאו מהם הטוב ונכלל בקדושה ולא נשאר רק חלק הרע אותו יוכלו בקל להאבידו כו', והיינו ענין הבירור שניתן לתהו להתברר ע\"י ש' מ\"ה דתיקון דהיינו רק ע\"י בירור דוקא כנ\"ל ולא כמו שהם בשלימותם כו'. ודוגמא לדבר בלעם הרשע שהי' מבחי' התהו כו' ולא יכלו לו בנ\"י, אך כאשר הוציא משה ממנו חלק הטוב והוא במה שהשים ה' דבר בפיו כו' ונעשה תורה הרבה על ידו ע\"י שנשא משלו ויאמר כו' שהוא כל פ' בלק שניתנה למשה וישראל, והפרשיות הללו מדברי בלעם הם ונעשה תורה לישראל, ואז לא נשאר רק חלק הרע שבו, ולכן אמר אחר"],[2000580127,"שגמר כל דבריו הנני הולך לעמי כו' ואז יכלו לו והרגוהו כו', ועד\"ז בכולם אשר שרשם מתהו כו'. וע\"ד דוגמא במה שאמרו דילמא יפוק מיני' ברא מעלי', וכשהולידו אז יוכלו לו כו' וכיוצא בזה. וזהו שא' עדה נא גאון וגובה פי' כמו שהם בשלימותם כו'. אך הנה הגם שאין זה ביכולת הצדיקי' אבל הוא ית' כל יכול, מאחר שממנו הי' ענין השבירה והתיקון דיכולתו לעשות מתהו תיקון כו', וזהו שא' ואם זרוע כאל לך כו'.\n<b>וענין</b> מה שנת' לעיל שכאשר הם בשלימותם אזי לא יש יכולת להפילם היינו קודם שנתמלא סאתם עדיין אז א\"א לברר אותם, וכאשר נתמלא סאתם אז מ\"ה מברר ב\"ן כו'. וזהו שא' הקב\"ה למשה ראה נתתיך אלקי' לפרעה שנתן לו ממשלה זרוע כאל ממש על פרעה עם היות פרעה יונק מעורף דא\"א שז\"ע פרעה אותיות הערף, בחי' עורף דא\"א שמשם נמשך להאריך אף גם לרשעי' ושורשו מבחי' התהו כו', עכ\"ז יהי' למשה דתיקון ממשלה על בחי' זו כמו אלקי' ממש הכל יכול והיינו לפי שמשה הי' מש' מ\"ה דא\"ק כמ\"ש בביאור ע\"פ משה ידבר (שלא נדפס) שהוא למעלה מבחי' תהו ותיקון כו' רק שנשפל בבחי' התיקון כו', ופרעה עם כי ישראל בררו הניצוצות שנבלעו בו וכמ\"ש וגם ערב ר\"ב עלה אתם שבררו משם ר\"ב ניצוצות, מ\"מ נשאר עדיין גם מה שלא נתברר עד שא\"א לבררו כ\"א ע\"י שאמר ה' למשה נתתיך אלקי' לפרעה שהוא בחי' ואם זרוע כאל שביכולתו לעשות מתהו תיקון הנה עי\"ז ע\"י האותות והמופתי' והביזוז שאח\"כ עשו אותם כמצולה שאין בה דגים כלל כו' כי בררו הכל להיות נכלל בבחי' התיקון כו'. ועוי\"ל שזהו ע\"י אור מבחי' עקודים שלמעלה מהשבירה ותיקון שהם בחי' נקודים וברודים, וכמו ענין המן שירד בזכות משה שהי' ג\"כ מבחי' זו.\n<b>ועפ\"ז</b> יובן דברי רשב\"י בפ\"ק דברכות ד\"ז ב' דאמר מותר להתגרות ברשעים בעוה\"ז והיינו כי הי' הארה ממדרגת משה שהי' אלקי' לפרעה שהוא בחי' זרוע כאל הוא יכול לעדות כל גאון וגובה וע\"ד כי גאה גאה גיאה על גוותניא כו' שמתגאה על כל הגאים כו'. ולכן הי' יכול לאמר על עצמו אנא סימנא בעלמא שזהו מצד רוממות נשמתו שהוא אלקות ממש להיותה מבחי' אצי' הוא בחי' גילוי ההעלם"],[2000580128,"מא\"ס, ואם כי הנשמות כבר נפרדו מהקו, אמנם חוזרי' ומתקרבי' ע\"י התלבשותם בגוף ועוסקי' בתומ\"צ ובדביקות אלקות, וכענין שא' רשב\"י בחד קטירא אתקטרנא בי' אחידא בי' להיטא כו'.\n<b>ולכן</b> הרואה חכמי ישראל צריך לברך שחלק מחכמתו ליראיו, והיינו כי חכמי' הם עיני העדה בחי' ראי' דחכ', והרי בחי' זו נק' חלק, שחלק מחכמתו כו' משא\"כ שנתן הרי מתנה יש לה הפסק, ואיננו דבוק כלל, אבל שחלק מחכמתו ה\"ז חלק מהכלל ודבוקי' בו כמ\"ש המ\"א סי' רכ\"ד סק\"ד, כי חלק יש בו ב' פי', הא' מל' חלוקה שנחלק מהכלל ונפרד, וגם ל' חלק שהוא חלק מהכלל וה\"ה דבוק להכלל, ומאחר שגם בעת שקורא זה בשם חלק אומר מחכמתו ה\"ז הוראה שלא נפרד כ\"א היותו דבוק בהכלל, והוא ע\"י התומ\"צ שעי\"ז דבוקי' בו ית' כמ\"ש ואתם הדבקי' בה' אלקיכם כו', ולהיותו חכם צריך לברך עליו שחלק מחכמתו ית'. וי\"ל שגם על נשמות דבי\"ע אם עוסקי' בתומ\"צ בבחי' ביטול שייך לומר גם עליהם שהם דבוקי' בא\"ס ש' אל או ש' הוי' דלא גרע נשמות ממלאכי' שבשעה שעושה שליחותו הרי נק' בשם ה', וכמו\"כ המצות נק' שלוחי' כמ\"ש בתנחומא, ועיקר המצוה הוא כשאיש ישראל עושה אותה אז נק' בשם מצוה משא\"כ תפילין כשמונחי' על השולחן כו', ובהשליח יש כח המשלח כו', ולכן הרואה חכמי ישראל גם עכשיו בדורותינו אלה נשמות דבי\"ע ג\"כ צריך לברך שחלק. או י\"ל שהחכמי' עיני העדה גם עכשיו יש בהם הארת חכ' ע\"י בחי' חכ' דמל' דעשי', וכענין אתפשטותא דמשה בכל דרא."],[2000580129,"<h3>לכן אמור לבנ\"י</h3>\n<b></b><b>בס\"ד. (ש\"פ וארא, ל\"ב).</b>\nוארא\n<b>לכן</b> אמור לבני ישראל אני הוי', והוצאתי אתכם מתחת סבלות מצרים, הנה בפ' זו נאמרו ד' לשונות של גאולה והוצאתי והצלתי וגאלתי ולקחתי, שכנגד ד' לשונות של גאולה תיקנו ארבע כוסות, זהו פי' א' שבמד\"ר שכנגד ד' גאולות שבמצרים תיקנו ארבע כוסות, ועוד יש פי' במד\"ר שד' לשונות של גאולה הם כנגד ד' גליות, וכנגד זה תיקנו ארבע כוסות כו'. והנה בזהר פי' שהד' לשונות הוא כנגד ד' פעמים אמת, ולפי פי' הזהר י\"ל ששני הפי' אמת, דהנה אנו אומרים ד' פעמים אמת קודם עזרת וד' פעמים בעזרת אבותינו, והיינו שד' פעמים אמת שקודם עזרת הוא כנגד הד' גאולות שביצ\"מ, וד' פעמים אמת שבעזרת הוא כנגד ד' גאולות של לע\"ל.\n<b>ולהבין</b> זה בתוס' ביאור י\"ל ענין מ\"ש בלק\"ת בדרוש מה טובו שיש שני בחי' תשובה, תשובה עילאה ותשובה תתאה, תשוב ה' עילאה ותשוב ה' תתאה, והן שתים שהן ארבע דהיינו מלמטלמ\"ע ומלמעלה למטה. ולהבין ענין הד' תשובות,"],[2000580130,"הענין הוא דהנה כתי' סור מרע ועשה טוב כו', וענין סור מרע, היינו בחי' תשו\"ת, דהנה כתי' כי עוונותיכם היו מבדילים ביניכם לבין אלקיכם, שנק' אלקה שלנו, והנה לא מצינו בכל השמות שיהי' נק' שלנו כ\"א בשם אלקי' שנק' אלקה שלנו, ולכאו' אינו מובן למה שם אלקי' דוקא נק' שלנו כו'. והענין הוא דהנה כדי שיומשך לנו אלקי' בבחי' גילוי עד שיהי' נק' שלנו זהו ע\"י שם אלקי' דוקא שהוא בחי' צמצום, כי כדי שיהי' גילוי אלקו' למטה אי אפשר כ\"א ע\"י צמצום כו', כי בלתי הצמצום לא היו יכולים לקבל כו', וכמשארז\"ל צמצם שכינתו בין ב' בדי הארון, ולכאו' הלא עיקר הגילוי הי' בין ב' בדי הארון ולמה נק' זה צמצום, אך לפי שכדי שיהי' גילוי אלקות בין ב' הבדים א\"א כ\"א ע\"י צמצום כו', וכך כדי שיהי' גילוי אלקות בנש\"י זהו ע\"י צמצום. וזהו שנק' אלקינו כי מה שנק' שלנו הוא ע\"י שם אלקי' המצמצם, אך זה הצמצום הוא עיקר החסד שאם לא הצמצום לא הי' בבחי' גילוי כלל, וזהו מ\"ש בספרי הקבלה ששם אלקי' הוא בחי' גבורה ואלקינו הוא רחמים, והיינו לפי שזה הצמצום הוא עיקר הרחמים כו'.\n<b>וזהו</b> מ\"ש עוונותיכם היו מבדילים ביניכם לבין אלקיכם שהעון מבדיל ומסתיר שלא יהי' נק' אלקינו שלנו דהיינו שאינו מאיר אלקות בבחי' גילוי בנש\"י. ויש כמה הבדלות גם בקדושה, וכמו המבדיל בין קדש לקדש, דהיינו שאף לאחר הפרסא הוא ג\"כ קדש רק שאינו קדש כמו קודם הפרסא כו', והיינו לפי שאף שיש פרסא מ\"מ הפרסא אינו הסתר גמור לפי שהפרסא הוא מסך דק שאינו מסתיר כ\"כ וע\"כ גם לאחר הפרסא הוא קדש. אך המבדיל בין קדש לחול הוא הבדלה גמורה שמסתיר על בחי' גילוי אלקות ואינו מאיר כלל בבחי' גילוי לפי שהמסך הוא מסך עב, וזהו ק\"נ המסתיר לו, וזהו כתנות עור משכא דחויא המסתיר כמו למשל אם עושין מסך מעור מסתיר לגמרי את אור זיו השמש, משא\"כ אם עושין מסך מזכוכית אף שהוא מסתיר מעט מ\"מ מאיר ע\"י אור השמש ג\"כ, וזהו שיש כמה הבדלות המבדיל בין קדש לקדש זהו כמו למשל מסך של זכוכית, אך המבדיל בין קדש לחול הוא כמו למשל מסך מעור שמסתיר לגמרי כו' שהוא בחי' ק\"נ. ועוד יש הבדלה בין טוב לרע שבק\"נ יכול להתהפך לקדושה משא\"כ גקה\"ט לגמרי אינו יכול להתהפך לקדושה כלל כו', וזהו עוונותיכם מבדילין ביניכם לבין"],[2000580131,"אלקיכם שנעשה מסך מבדיל כו', וכדי שיהי' אלקינו בבחי' גילוי צריך שיהי' מתחלה בחי' סור מרע כדי שלא יהי' העון מסך מבדיל כנ\"ל, וזהו\"ע תשו\"ת תשוב ה' תתאה.\n<b>אך</b> כ\"ז אף שהוא סור מרע ומסיר את המסך שלא יבדיל, מ\"מ הגילוי שמאיר הוא רק מבחי' ממכ\"ע שהוא בחי' אלקינו לבד, אבל כדי שיהי' מאיר גילוי בחי' סוכ\"ע הוי' אלקינו שיהי' הוי' אלקינו זהו ע\"י ועשה טוב ע\"י מעשה המצות, כי מעשה המצות נק' טוב וכמ\"ש אמרו צדיק כי טוב, תחת אשר לא עבדת את הוי' אלקיך בשמחה ובטוב לבב מרוב כל, והנה טוב הוא בגימ' א\"ה ו\"ה שהוא ר\"ת את השמים ואת הארץ אני מלא בחי' סוכ\"ע, והיינו שע\"י ועשה טוב ממשיכים בחי' סוכ\"ע בחי' שם הוי' שהוי' יהי' אלקינו, וזהו המשכה מלמעלה למטה, וזהו\"ע יחוד ו\"ה שע\"י סור מרע ועשה טוב עי\"ז נמשך הגילוי מבחי' ז\"א ומל'.\n<b>והנה</b> יש עוד מדרגה בקש שלום ורדפהו, שלום הוא בחי' תורה כמ\"ש או יחזיק במעוזי יעשה שלום לי שלום יעשה לי וארז\"ל כל העוסק בתורה משים שלום בפמליא שלמעלה ובפמליא של מטה, והיינו שהתורה מחבר בחי' סוכ\"ע בממכ\"ע, וכיון שהתורה מחבר בחי' סוכ\"ע בממכ\"ע עכצ\"ל ששרש התורה למעלה גם מבחי' סובב וממלא, כיון שיש ביכולת התורה לחבר כו', וזהו כי אל דעות הוי' ד\"ע מלמעלמ\"ט שלמעלה היש ולמטה הוא אין שכולא קמי' כלא חשיבי, וד\"ת הוא מלמטלמ\"ע שלמעלה הוא אין ולמטה הוא היש, וזהו בחי' סובב וממלא, ושיהי' התחברות ב' דיעות דהיינו שבד\"ת יהי' ג\"כ הגילוי איך שכולא קמי' כלא חשיב צריך שיהי' נמשך מלמעלה מב' הדיעות אשר שם ב' הדיעות שוין ע\"כ יכול להיות הגילוי בד\"ת כמו בד\"ע ממש, וזהו ע\"י התורה שהתורה מחבר ב' הדיעות לפי שאוריי' מח\"ע נפקת, ושורש התורה הוא למעלה גם מבחי' חכ' דהיינו מבחי' חפץ פנימי' הרצון כו', והיינו שע\"י התו' נעשה יחוד ו\"ה וזהו תשוב ה' עילאה לגבי י', ויש בזה ג\"כ שני מדרגות תשוב ה' לגבי יו\"ד מלמטלמ\"ע וגם תשוב יו\"ד לגבי ה', וכשנק' בעל תשובה זהו שנמשך ההשפעה מע\"ק לחכ' ומחכ' לבינה זהו בעל משפיע לבחי' תשובה, וכמ\"ש בזהר מאן ישוב דא ע\"ק לאתגלאה, וזהו מ\"ש שובה אלי ואשובה אליכם.\n<b>וזהו\"ע</b> ד' לשונות של גאולה שהוא כנגד ד' מדרגות שיש בתשובה, וזהו פי' הפסוק לכן אמור לבנ\"י אני הוי' שכדי שיהי' גילוי בחי' שם הוי' גילוי"],[2000580132,"בחי' י\"ה וגילוי ו\"ה צריך שיהי' ד' בחי', מתחלה והוצאתי אתכם מתחת סבלות מצרים שהוא בחי' סור מרע, כי העון נק' סבל שהוא כבד וכמ\"ש כבד עון, ואח\"כ והצלתי שהוא בחי' ועשה טוב מעשה המצות, כי בפי' והצלתי יש שני פי', א' לשון הצלה, והב' מל' צל, והיינו שהצל הוא בחי' מקיף, וע\"י המצות ממשיכי' בחי' מקיף סוכ\"ע, וכמ\"ש ואשים דברי בפיך ובצל ידי כסיתיך, ואשים דברי בפיך הוא בחי' תורה ובצל ידי כסיתיך הוא בחי' מעשה המצות כו' וזהו ו\"ה (וגאלתי הוא בחי' ה' עילאה בינה שגאולה הוא בחי' לידת המדות ובינה נק' אם הבנים כו'), ולקחתי גו' לי לעם זהו בחי' תשו\"ע שהוא בחי' לי לעצמותו ומהותו כו'. וזהו\"ע ד\"פ אמת שהוא כנגד ד' גאולות ד' אותיות שם הוי' והוא בחי' ד\"פ אמת, שיש ד' מדרגות באמת, אף שזו המדריגה ג\"כ אמת מ\"מ יש בחי' אמת שלמעלה מאמת זה, וכמ\"ש וארא אל אברהם אל יצחק כו' באל שדי ושמי הוי' לא נודעתי להם, ופירש\"י לא ניכרתי במדת אמיתי' שלי, ולכאו' אינו מובן וכי שם שדי אינו אמת ח\"ו, אך הפי' שגם זו בחי' אמת, אך מ\"מ יש בחי' שלמעלה כו' וכמ\"ש כי גבוה מעל גבוה שומר וגבוהים עליהם (הגם שבחי' זו ג\"כ גבוה אעפי\"כ יש בחי' שגבוה מזו ג\"כ), וזהו\"ע ד' גאולות שביצ\"מ.\n<b>ועתה</b> י\"ל איך שייך ביצ\"מ עצמו ד' גאולות, הענין הוא דהנה איתא במד\"ר שכשנתן הקב\"ה התורה למשה אמרה ד\"פ בינו לבין עצמו ואח\"כ נתן כו' (ומזה נלמד שכשאדם צריך לומר איזה דבר תורה צריך לחזור אותה ד\"פ בינו לבין עצמו) וכמ\"ש אז ראה ויספרה הכינה וגם חקרה ויאמר לאדם, שיש כאן ד' מדרגות עד ויאמר לאדם, ולהבין זה איך שייך לומר שאמרה ד\"פ בינו לבין עצמו, הענין הוא דהנה שרש התורה היא למעלה מאד וכדי שיומשך למטה אם הי' נמשך התורה כמו שהיא למעלה לא היו יכולים לקבל, וע\"כ הוצרך להיות מתחלה צמצום, וזהו ענין שם הוי' שהוא בחי' צמצום והתפשטות המשכה והתפשטות כו', והיינו ששם הוי' הוא מקור להתהוות, וכדי שיהי' התהוות מאוא\"ס זהו ע\"י צמצום והתפשטות כו', וכך כדי שיומשך התורה למטה זהו ע\"י צמצום והתפשטות המשכה והתפשטות, והיינו שצריך שיהי' נמשך ע\"י אותיות שם הוי', וזהו ד' מדרגות אז ראה הוא בחי' חכ' שמתחלה נמשכה בבחי' חכ' כי ראי' הוא בחי' חכ' וכמ\"ש איזהו חכם הרואה את הנולד, וחכמים הם עיני העדה כי ראי' היא מבחי' חכ' כו', ויספרה הוא בחי' בינה כי ספר הוא בחי' בינה, הכינה וגם חקרה זהו בחי' ז\"א ומל' ואח\"כ ויאמר לאדם שנמשכה למטה בבי\"ע כו'. ובזה יובן ענין ד' גאולות שביצ\"מ, שביצ\"מ גופא הי' צ\"ל ד'"],[2000580133,"גאולות, והיינו שכדי שיומשך מאוא\"ס למטה בחי' גאולה הוצרך שיהי' ד' מדרגות גאולה שהוא בחי' צמצום והתפשטות המשכה והתפשטו', וכנגד זה תיקנו ד' כוסות כו'.\n<b>ועתה</b> י\"ל ענין ד' פעמים אמת שלע\"ל, והענין הוא דהנה ידוע שיש שני בחי' הוי' וכמ\"ש ויקרא הוי' הוי' ופסיק טעמא בגווייהו, והיינו הוי' שהוא מקור להשתלשלו', ויש בחי' שם הוי' שאינו מקור להשתלשלו' כלל רק שעלה ברצונו, דהנה אנו רואים למטה שהרצון הוא העיקר ואעפי\"כ מהרצון שלמטה לא יתהווה כלום שאף שירצה כמה לא יתהווה מזה כלום כ\"א כשיומשך הרצון במחדו\"מ, משא\"כ למעלה שכיון שעלה ברצונו מיד נתהווה כך וכמ\"ש כל אשר חפץ ה' עשה כו', וזהו שיש בחי' שם הוי' גם למעלה ברצון כו' לפי ששם ישנם ג\"כ כל הבחי' כו', אך מ\"מ פסיק טעמא ששם הוי' דלעילא הוא למעלה הרבה מבחי' שם הוי' דלתתא ואינו מקור להשתלשלו' כלל. והנה לע\"ל יהי' מאיר גילוי בחי' שם הוי' דלעילא וכמ\"ש ביום ההוא יהי' הוי' אחד ושמו אחד, דהיינו שלא יהי' פסיק טעמא בגווייהו אלא שם הוי' דלעילא יהי' מאיר בבחי' שם הוי' דלתתא, וזהו ביום ההוא יהי' הוי' אחד כו', וממילא יהי' ושמו אחד, דהנה עכשיו לא כמו שאני נכתב אני נקרא, נכתב בהוי' ונקרא באד' לפי שהגילוי הוא ע\"י שם אד', וכמ\"ש הוי' בהיכל קדשו, היכל הוא אד' ששם אד' הוא היכל לשם הוי', אך לע\"ל כשיהי' מאיר גילוי בחי' שם הוי' דלעילא אזי יהי' הגילוי ע\"י שם הוי' לבד שלא ע\"י שם אד' וכמ\"ש ולא יכנף עוד מוריך שלא יהי' הסתר כלל כו' ע\"י לבושים כו', והיינו לפי שיהי' מאיר גילוי שם הוי' דלעילא כו'. וזהו\"ע ד' גאולות של לע\"ל, והיינו שהד' גאולו' של לע\"ל הוא מבחי' ד' אותיות שם הוי' שברצון כו', וזהו ד\"פ אמת שבעזרת שהיא בחי' אמת שבשם הוי' דלעילא כו', וזהו תשורי מראש אמנה, דהיינו מראש ומקור של אמנה שהוא בחי' רזא דמהימנותא שהוא בחי' ע\"ס כו'."],[2000580134,"<h3>קול מצהלות</h3>\n<b></b>מאמר זה לא נרשם בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש, ונמצא רק הנחה מהמאמר, ונדפס לקמן בחלק ההנחות"],[2000580135,"<h3>מהרה ישמע</h3>\n<b></b>מאמר זה לא נרשם בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש, ונמצא רק הנחה מהמאמר, ונדפס לקמן בחלק ההנחות"],[2000580136,"<h3>ויקרא משה גו' משכו וקחו</h3>\nמאמר זה לא נרשם בגוכי\"ק כ\"ק אדמו\"ר מהר\"ש, ונמצא רק הנחה מהמאמר, ונדפס לקמן בחלק ההנחות"],[2000580137,"<h3>לא יצא האיש לא בסייף</h3>\n<b></b><b>בס\"ד. (ש\"פ בשלח, ל\"ב).</b>\nבשלח\n<b>לא</b> יצא האיש לא בסייף ולא בקשת ולא בתריס ולא באלה ולא ברומח כו' ר' אליעזר אומר תכשיטין הן לו, וחכמים אומרים אינן אלא כו' שנא' וכתתו כו' ובגמ' דס\"ג ע\"א מאי באלה קולפא פי' שבט שמכין בו וראשו עב, וא\"כ הוא ג\"כ כלי זיין, וכן פי' רש\"י בברכות דנ\"ח ע\"א יהבי לי' קולפא, מקל לרדות, משא\"כ תריס הוא מגן לחסות מפני החיצים ושאר דברים, ומ\"מ הוא ג\"כ כלי זיין רק שהוא להגן כו'.\n<b>ולהבין</b> שורש מחלוקותן. הנה ביצ\"מ כתי' וחמושי' עלו בני ישראל מארץ מצרים ופי' בירושלמי פ\"ו דשבת על משנה הנ\"ל שהיו מזוייני' בחמשה מיני זיין ובקה\"ע שם שהם חמשה מיני זיין הנ\"ל המנויים במשנה (בירושלמי שלפנינו הגי' חמשה עשר, אמנם בקה\"ע גורס חמשה, ופי' שלמד מל' וחמושי' לשון חמשה, וביפ\"מ כ' בפי' שהגירסא היא חמשה, ושהכי איתא* במכילתא).\n<b>ולהבין</b> זה בעבודת ה' הנה כתי' רוממות אל בגרונם וחרב פיפיות בידם, ודרשו רז\"ל כל הקורא ק\"ש על מטתו כאילו אוחז חרב של שתי פיות, וי\"ל למה צריך חרב של שתי פיות דוקא. הענין הוא דהנה איתא* בזהר ששם הוי' נק'"],[2000580138,"חרב, רישא דחרבא הוא יו\"ד של שם הוי', גופא דחרבא הוא וי\"ו של שם הוי', ה\"א ה\"א הן תרי פיות דילי', נרתקא דחרבא הוא שם אד', וי\"ל למה נק' שם הוי' חרב כו'.\n<b>אך</b> הענין הוא דהנה יניקת החיצוני' יכול להיות משני אופנים, א' מחמת ריבוי צמצומים דשם אלקי' המסתיר ומעלים הארת אלקות בתכלית ההעלם וההסתר עי\"ז יכול להיות יניקת החיצונים, דשכשמאיר אא\"ס בבחי' גילוי משם אינם יכולים לקבל, לפי שאין השראת אא\"ס אלא בבחי' ביטול אבל בבחי' יש אינו יכול להיות גילוי אא\"ס כי אין אני והוא יכולים לדור, לכן הקליפות שהם בבחי' יש ודבר נפרד אינם יכולים לקבל מבחי' גילוי, אבל כשנתצמצם בבחי' ריבוי הצמצומים יכולים הם לקבל תוס' יניקה לפי שעכ\"פ מעט ביטול יש בהם דקרו* לי' אלקא דאלקי' כו', וז\"ש* כרחל לפני גוזזיה נאלמה שעי\"ז גוזזיה שגוזזי' בחי' שערות הם בחי' ריבוי צמצומי' עי\"ז נמשך יניקת החיצוני' נאלמתי דומי' החשיתי ר\"ת נדה, וז\"ע מה שמצמצומי' דשם אלקים יכולי' לקבל והיינו מבחי' צירופי' אחרונים דק\"ך צירופי אלקי' שהם ריבוי צמצומי' נמשך שממ\"ח צירופי' אחרונים מקבלים יניקה אדמת בני חם כו', וזהו אופן א'. והב' שמקבלים דוקא ממקום גבוה מאד שלמעלה מהשתלשלות, דהיינו מעולם התהו שקדם לתיקון ששם אינו תופס מקום כלל כחשכה כאורה שוים ושממית בידים תתפש כו', וזהו מ\"ש אם תגביהי כנשר שמגביהים א\"ע למעלה מאד וכמו דרך* הנשר בשמי' כו'. והנה ב' מיני אופני יניקתם תלוי הכל בנש\"י, וכמ\"ש יעקב חבל נחלתו, וכמו* למשל החבל כשראשו א' קשור למעלה וראשו א' למטה שכשמתנענע הקצה התחתון מתנענע גם הקצה העליון, ועד\"ז בנפש האדם שכשאדם נמשך בבחי' פנימי' הרצון לאלקו' בת\"ת ותפלה נמשך מלמעלה ג\"כ מבחי' פנימי' הרצון, אבל כשהאדם משפיל א\"ע בתאוות ורוח הבהמה היורדת למטה אזי עי\"ז גורם למעלה שיומשך ג\"כ בחי' השפלה שיומשך אלקו' בבחי' ריבוי צמצומי' מאד עד שיכול להיות מזה יניקת החיצוני', וכן כשאדם מגביה א\"ע בבחי' התנשאות וגסות הרוח הגשמי מצד חומר גופו כאשר יגבה לבבו ע\"י העושר וכבוד, והגם שיודע היטיב הפחיתות שלו מ\"מ מתנשא בלא טעם ודעת, ורוח אייתי רוח גורם להתעורר למעלה התנשאות החיצוני' לומר לי יאורי וכדומה וחוצפא אפי' כלפי שמי' מהני' שמגבי' א\"ע לקבל יניקה ממקום גבוה מאד, לפי שהעולם נתון בלבו של אדם וכמ\"ש וגם את העולם נתן* בלבם. וזהו שב'"],[2000580139,"אופני יניקה הכל תלוי בנפש האדם, וזהו ענין פרעה* אותיות הערף שמקבל מבחי' עורף דא\"א שהוא בחי' גבוה מאד וזהו ע\"י כי פנו אלי עורף ולא פנים עי\"ז נמשך בחי' פרעה שיונק מעורף דא\"א ששם כחשכה כאורה כו', ולכן נמשך מזה גלות מצרים כו'.\n<b>והנה</b> כדי להכרית היניקה מב' אופנים הנ\"ל לזה צריך חרב של שתי פיות, והחרב של שתי פיות כו' הוא בחי' מ\"ש רוממות אל בגרונם וחרב פיפיות בידם שע\"י רוממות אל בגרונם עי\"ז נעשה חרב של שתי פיות כו'. והענין הוא דהנה בגרון יש ג' בחי' קנה וושט וורידין, שזהו\"ע ג'* שרי פרעה שר המשקי' ושר האופי' ושר הטבחים, כי מצרים הוא בחי' מצר הגרון, ולכן יש בגרון ג' שרי פרעה כו' כנ\"ל. והנה כמו שיש מצרים בלעו\"ז כמ\"כ יש מצרים דקדושה, וכן ג' שרי פרעה יש ג\"כ בקדושה, והנה שר המשקי' זהו בחי' קנה, כי בקנה יש גידי המוח שממנו נמשך לריאה וללב וכמשארז\"ל תלת קני הוי חד פריש לריאה וחד פריש לליבא וחד פריש לכבדא כו', ולכן נק' שר המשקי', לפי ששואב לחלוחית שבמוח לריאה וללב כו'. והנה כמו שמים מצמיחים כל מיני תענוג, וכך הקנה נק' שר המשקי' ממשיך בחי' תענוג באלקו' וכמ\"ש ונהר יוצא מעדן להשקות את הגן עדן הוא בחי' תענוג עליון ונהר היוצא מעדן ממשיך בחי' התענוג בגן כו', כמ\"כ הקנה ממשיך בחי' תענוג, דהנה כתיב קנה חכ' קנה בינה שהקנה מבחי'* חכמה כו', ועי\"ז נמשך בחי' תענוג דהיינו כשמתבונן באלקו' איך שאני הוי' לא שניתי ואין ערוך אליו כלל ויעמיק דעתו בזה מאד עי\"ז נולד לו אהבה בתענוגים, וזהו שבקנה* יש ששה טבעות, וקנה עם הכולל בגי' ששה פעמים הוי' והיינו שהקנה ממשיך בחי' ש' הוי' בבחי' ששה מדות דהיינו המשכת מוחין במדות כו'. וזהו ענין שר המשקי' שבבחי' תפלה שממשיך בחי' תענוג אהבה בתענוגי', וגם בתורה שנאמר להשקות את הגן בחי' ג\"ן סדרים דאורייתא שנמשך בחי' תענוג עליון בתורה זהו ענין עיון התורה, שע\"י התורה עי\"ז נמשך בחי' תענוג כו' שמתענג מהתורה כו'. והנה שר המשקי' הוא שמוזג את היין, והמזיגה הוא ע\"י מים, וכך בתורה צריך שיהי' מזיגה* מים ביין, יין הוא בחי' יינה של תורה שהוא בחי' תושב\"כ, ומים הוא בחי' תושבע\"פ ערבים עלי דברי סופרי' יותר מיינה של תורה כו', וזה\"ע שר המשקי' דקדושה בחי' קנה חכ' קנה בינה, והנה עי\"ז הוא מכרית את היניקה שיונקי' ממקום גבוה שמגביהים לפי שכשההמשכה נמשך ע\"י בחי' חכ' א\"א להם לקבל יניקה, לפי שחכ' הוא בחי' ביטול."],[2000580140,"<b>ושר</b> הטבחים הוא בחי' וורידים, והנה הוורידין הוא שבהם עולה הדם מהלב, והוא ענין רתיחת הדמים דקדושה שהוא בחי' אהבה ברשפי אש, כי בחי' קנה הוא בחי' אהבה* הנמשכת כמים אהבה בתענוגים, ושר הטבחים הוא בחי' אהבה ברשפי אש כו', וע\"י בחי' אש דקדושה עי\"ז אש אוכלה אש בחי' אש דלעו\"ז בחי' תאוות זרות כו', וזהו שת\"א על שר הטבחי' רב קטוליא, והיינו כמ\"ש זובח תודה יכבדנני כל* הזובח את יצרו (זוכה ונוחל שני עולמות כו'), והנה עי\"ז מכרית היניקה מאופן הא' שהוא ע\"י ריבוי הצמצומי' כו' לפי שריבוי הצמצומי' נמשך מבחי' רוח הבהמה היורדת למטה שמשפיל א\"ע בתאוות גשמי', אבל ע\"י שר הטבחי' ששורף ומכלה את כל התאוות ורצונות זרות, לכן לא יוכלו לקבל מזה יניקה. ושר האופים הוא בחי' תורה כי התורה נק' חטה ך\"ב אותיות דאורייתא, וכדי שיהי' מבחי' חטה לחם צריך אפי' וכמ\"ש ואפו עשר נשים לחמכם בתנור אחד פי'* ואפו לחמכם שהוא התורה בתנור אחד פי' בחמימות האהבה הבאה מהתבוננות של אחד יחידו של עולם, וזהו שר האופי' שהוא בחי' תורה כו', והגם שנת' לעיל שהקנה הוא בחי' תורה זהו עיון התורה הוא בחי' קנה, אבל סתם* תורה נק' שר האופים כו'. והנה התורה עצמה נק'* ג\"כ חרב של שתי פיות וכמ\"ש ודברי אשר שמתי בפיך, שיש שני בחי' פה העליון ופה התחתון, שהתורה היא בחי' דברי ממש, כל הקורא ושונה הקב\"ה קורא ושונה כנגדו כו', וזהו שתי פיות כו'.\n<b>וזהו</b> וחרב פפיות בידם שע\"י רוממות אל בגרונם וכנ\"ל עי\"ז נעשה יציאת חרב פפיות כו' שע\"י הגרון עי\"ז נעשה יציאת מצרי' שהוא בחי' מיצר הגרון דלעו\"ז. שבלעו\"ז יש ג\"כ ג' בחי' שהוא ג' בחי' שרי פרעה, שר המשקי' הוא בחי' התענוגי' גשמי' שנק' שר המשקי' וכמ\"ש וישא* לוט את עיניו, ותשא אשת אדוניו את עיניה, כי כולה משקה, וכמ\"ש אלכה אחר מאהביי נותני צמרי ופשתי שמני ושיקויי, והיינו שהוא בחי' תענוגי' גשמי' הן בתאוות היתר והן בתאוות"],[2000580141,"איסור כו' וכמו אנשי סדום שהיו רעים וחטאים מאד שהלכו אחר תאוות ליבם כו', והנה ברבות איתא כי כלה משקה ע\"ש* והשקה את האשה את מי המרים המאררים, והיינו כי תענוגי' גשמיי' תחלתן מתוק וסופן מר וכמ\"ש נופת תטופנה שפתי זרה ואחריתה מרה כלענה כו', וזהו ענין שר המשקי' דקליפה. ושר הטבחים הוא בחי' רתיחת הדמים שהוא בחי' כעס שנק' רב קטוליא וכמ\"ש* טורף נפשו באפו כו' (שעושה את הנפש טרפה כו'). ושר האופים יש ג\"כ בלעו\"ז וכמ\"ש וכל היום בוער כתנור כו'. אך ע\"י רוממות אל בגרונם עי\"ז נעשה וחרב פיפיות בידם שמכרית ממילא היניקה שלא יוכלו לקבל יניקה כי את זלעו\"ז ואמלאה החרבה כתי', וכיון שרוממו' אל בגרונם ע\"י ג' בחי' שיש בקדושה ממילא עי\"ז נעשה וחרב פפיות בידם, כי אור דוחה חשך, וזהו ג\"כ ששם הוי' נק' חרב, דהיינו שמכרית יניקת החיצונים וכמ\"ש אם תגביה כנשר משם אורידך נאום הוי', שמבחי'* שם הוי' אינם יכולים לקבל יניקה, וזהו שק\"ש נק' חרב פפיות כו', וגם רמח שע\"י רמ\"ח תיבין דק\"ש נעשה רמח וחרב להוציא את החיות משם, וכמ\"ש בק\"ש אני הוי' אלקיכם אשר הוצאתי אתכם מארץ מצרים שע\"י ק\"ש נעשה יצי\"מ כו'.\n<b>ובד\"פ</b> יש לבאר כל החמשה מיני זיין הנ\"ל בעבודה שבלב זו תפילה, דהנה סייף שהוא חרב קאי על פסוד\"ז שהוא בחי' רוממות אל בגרונם, שהוא* ענין שארז\"ל לעולם יסדר אדם שבחו של מקום ואח\"כ יתפלל, וסידור שבחי' הוא מה שמספר בחי' ההילול מכל הנבראי' איך שהללו את ה' מן השמי' כו', ועי\"ז נעשה וחרב פיפיות להכרית את החוחי' והקוצי' הסובבי' את השושנה העליונה כו', וזהו\"ע פסד\"ז מל' זמיר עריצי', וזה\"ע הסייף. ובקשת הוא בחי' כל הבקשות דשמו\"ע, ואין מבקשי' אא\"כ חסר וז\"ע משיכת הקשת על היתר, ושורש ענין הבקשות דשמ\"ע הוא שיומשך הארת אלקותו ית' שז\"ע ברוך אתה הוי', והיינו ע\"י שמתבונן ברוממות אלקות איך שאין ערוך אליו כלל, ואיך שהוא רחוק מאלקותו ית' בתכלית עי\"ז יתמרמר מאד ומבקש מעומקא דליבא שיומשך גילוי הארת אלקות בנפשו, וע\"י קשת זה שהוא בחי' הבקשות הנ\"ל עי\"ז הוא הורג את שונאיו הוא בחי' החיצוני' שעומדי' לנגד כו'."],[2000580142,"<b>וההפרש</b> בין סייף לקשת שע\"י הסייף אינו יכול להרוג כ\"א השונאי' שעומדי' אצלו בקרוב אבל להשונא שעומד ברחוק אינו יכול לנגוע בו, אמנם ע\"י הקשת פועל פעולתו גם מרחוק, וכן פעולת הקשת שכל מה שימשוך הקשת על היתר ביותר הרבה, תזרוק החץ למרחוק יותר, וכן הוא בתפילה שהוא בחי' הקשת כל מה שיתמרמר יותר מריחוקו מאלקות מגיע החץ למרחוק יותר, והיינו להרוג ולהעביר גם את הרע שבדקות מאד שלכאו' אינו מרגיש אותו כלל ונדמה לו שאינו נפרד עי\"ז, אבל כשמתבונן בגדולת א\"ס בק\"ש ובקשות דשמו\"ע שיומשך גילוי אלקות בנפשו אז מרגיש גם דקות הרע המונע ומעכב גילוי אור האלקי בנפשו. ולכן לאחר שמו\"ע אומרי' וידוי' אשמנו, שלכאו' הי' צריך להתחיל התפילה בזה, אלא שקודם התפילה דרך איש ישר בעיניו כי מאחר שאינו עובר רצונו ית' בפו\"מ לעשות רע ח\"ו, וכ\"ש כשעושה איזה מצוה ולומד תורה מעט נדמה לו כי מקורב הוא לגמרי ואיננו רחוק כלל, אמנם ע\"י הצירוף דתפלה כמ\"ש מצרף לכסף כו' איש לפי מהללו שע\"י ההילול ושבח דתפילה שמבקש קרבת אלקות מתגלה בהתייהו* איך שנמצא בו עדיין סיגי' ופסולת הוא בחי' הרע שבדקות המונע ומעכב קרבת אלקות, ולכן תוהא ומתחרט עליו מאד ומבקש סלח לנו כו' וכל הוידוי' דא\"ב דאשמנו כו', וה' יסלח לו להאיר גילוי אור האלקי בנפשו להיות מכון לשבתו ית'. ובזה יובן מ\"ש בפ' וגם את הצרעה כו' עד אבוד כו' לא תערוץ כו' אל גדול ונורא שלכאו' מהו צריך לנתינת הטעם אל גדול, אלא כדי להעביר גם את הנסתרי' שהוא הרע שבדקות שאינו מרגיש בו כלל צ\"ל מבחי' אל גדול, וכמו אבוקה שמאיר למרחוק להיות האור דאבוקה דוחה גם את החשך שמרחוק כו' הוא בחי' דקות הרע שבו כו'.\n<b>ואלה</b> שפי' בגמ' קולפא הוא מקל* לרדות, הוא כמ\"ש וגם אתה תדין את ביתי, בחי' דינא דמלכותא דינא, כי בדברי' לא יוסר עבד הוא הנה\"ב, וצריך להכותה בשבט בחי' לעולם ירגיז אדם יצ\"ט על יצה\"ר, ופי' לעולם כי הרי תמיד יש לו בחי' הרוגז שהוא מצד הגבורה שאין לך אדם שאינו כלול מטו\"ר, והרע היינו בחי' הרוגז והחימה, והכל הוא מסטרא דרע וכמארז\"ל רע לשמי' ורע לבריות, והרוגז והכעס ישפוך על הרע שבו שיקצוף מאד ויחרה אפו למה הוא כך כו', וזהו בחי' הכלי זיין שנק' אלה שהוא מקל לרדות בו את הנה\"ב שבאדם כו'. ובחי' רומח הוא בחי' ק\"ש כמ\"ש ויקח רמח בידו הוא* בחי' רמ\"ח תיבי' דק\"ש, והיינו כמו שע\"י"],[2000580143,"הרומח הוא נטילת חיות האדם לגמרי, כך ע\"י ק\"ש מבטלי' ומחרימי' את בחי' הרע מכל וכל מבחי' עת אשר שלט האדם באדם כו', וזהו שפי' במאו\"א אות ר' סט\"ו רומח רמ\"ח איברי' הכלולי' בוא\"ו שהוא ז\"א, וע' בפע\"ח שער ק\"ש שעל המטה פי\"א, ובק\"ש הוא בחי' רמ\"ח תיבין, שלכן כופלי' ה' אלקיכם אמת כו', והוא\"ו הוא בחי' שית תיבין דיחודא דשמע ישראל. וי\"ל ההפרש בין אלה לרומח כי במדות דנה\"ב יש ב' בחי', הא' תאוות היתר, והב' תאוות איסור הנמשך מרע דנוגה, ולנגד בחי' הא' די להכותו בשבט שהוא בחי' אלה קולפא מקל, אבל נגד בחי' הב' צריך להחרימה מכל וכל ע\"י חרב ורומח. וענין התריס הוא המגן להגן שלא יהרג ע\"י החיצים שזורק עליו המנגד, וכן יובן ענין זה בעבודת ה' בתפילה ששעת צלותא הוא שעת קרבא צריך ללבוש טלית ותפילין שהם נעשי' למגן ומחסה מהמנגד שעומד לנגדו להפילו בתאוות והרהורי' רעי', ודוקא* בעת ק\"ש ותפלה שאז מתגבר יותר, וכדרך הנלחמי' זע\"ז, ולכן לובשי'* אז טלית ותפילין בהיות נודע כי ע\"י מעהמ\"צ עי\"ז נעשה לבושי' לנפש, וכן נעשי' לבושי' להגן מפני החיצים ואבני בליסטראות מהמנגד כו'.\n<b>וזהו</b> וחמושים עלו בני ישראל מארץ מצרים להיות כי ביציאתם ממצרי' הי' הרע אצלם עדיין בשלימות, ולכן* כי ברח העם שהוכרחו לברוח מהרע, ולכן עלו חמושי' בחמשה כלי זיין הנ\"ל להלחם עם הרע שיוכלו לברוח ממנו ולהעבירו מכל וכל שז\"ע סייף וקשת כנ\"ל.\n<b>ומעתה</b> יובן הטעם שאמרו שבשבת לא יצא האיש בסייף, דהנה בעבודה בששת ימי החול הנה שעת צלותא היא שעת קרבא להלחם עם הרע שבנפשו, אמנם בע\"ש עם חשוכא נפרד הרע מן הטוב, וכמאמר וכל דינין מתעברי' מינה ולית שולטנא כו' ואיהי אתפרשת כו', ולכן בשבת אינו שייך ענין מלחמה הנ\"ל כ\"א שבת הוא בחי' עליות המדריגות, והתפילה דשבת היא יותר נעלה הרבה מתפילה דימי החול, ולכן תומ\"צ ותפילה דכל ימי החול מתעלי' בתפילה דשבת, להיות כי שבת הוא זמן העלי'. ולכן אמרו לא יצא האיש בכל החמשה כלי זיין הנ\"ל בשבת, כי בשבת אינו זמן המלחמה הנ\"ל כי איהי אתפרשת כו' והרע מובדל ומרוחק כו'. אבל ר' אליעזר אומר שמ\"מ תכשיטין הן לו והיינו שהבירורי' דכל ששת ימי החול הנה גם בשבת הם תכשיטין להתקשט בהון והוא כל בחי' הבירורי' שבירר בימי החול, וכמו שהן מתעלין בתפילה דשבת כן יכול לצאת בהן דאם היות שאינם צריכי' להלחם בהן מ\"מ ה\"ה קישוטין לו שנצח בימי החול ע\"י, וחכמים אומרים אינם אלא לגנאי כי"],[2000580144,"המברר בהכרח להשפיל א\"ע במקום המתברר ולכן שלא בעת המלחמה לא יצא בהן, וראייתם מלע\"ל שנא' וכתתו כו' היינו מפני כי לא יצטרכו להם כלל, כי לע\"ל נא' ואת רוח הטומאה אעביר כו', כן בשבת שאינו זמן המלחמה ג\"כ אל יצא בהם, וטענתו שתכשיטין הן לו אינו טענה דא\"כ מדוע לא יתקשטו בהם לע\"ל להורות על הבירור שקודם לכן, אלא מפני שא\"צ להם אינם אלא לגנאי מטעם הנ\"ל ולכן בשבת ג\"כ כן הוא כו'."],[2000580145,"<h3>שלוש פעמים בשנה</h3>\n<b></b><b>בס\"ד. (ש\"פ משפטים, בדר\"ח אדר ראשון, ל\"ב).</b>\nמשפטים\n<b>שלש</b> פעמים בשנה יראה כל זכורך וגו', שז\"ע מצות ראי' ברגלי' שהיא מדריגה גבוה מאד וכמארז\"ל כדרך שבא לראות כך בא ליראות, ולכאו' צ\"ל הלא שבת גבוה מיו\"ט ששבת הוא בחי' קדש, וכמ\"ש ושמרתם את השבת כי קדש היא, ויו\"ט הוא רק מקרא קדש כמ\"ש מקראי קדש אשר תקראו אותם במועדם, וגם שבת הוא בחי' מוחין דאבא, ויו\"ט הוא בחי' מוחין דאימא, ומדוע לא ניתן מצות ראי' בשבת כמו ברגלי'.\n<b>והענין</b> הוא דהנה כתי' צמאה נפשי לאלקי' לאל חי מתי אבוא ואראה פני אלקי' וארז\"ל בילקוט בשם מדת\"ל, ובמ\"א כ' בשם פסיקתא רבתא אמרה כנס\"י לפני הקב\"ה מתי תחזור לי הכבוד הראשון שהייתי עולה לרגל ג\"פ בשנה שנא' שלש פעמים בשנה יראה כל זכורך, א\"ל הקב\"ה בעוה\"ז הי' שלש פעמים, אבל לעתיד בכל חדש וחדש שנא' והי' מדי חדש בחדשו ומדי שבת בשבתו. ומקשי' האיך אפשר"],[2000580146,"שיבואו בכל שבת, אך ע\"ז נא' מי אלה כעב תעופינה וכיונים אל ארובותיהם (ישעי' ס' פסוק ח') שהעננים יביאום כו' כמ\"ש בילקוט ישעי' רמז שס\"ג, גם משמע שם שזהו כענין עיניך יונים והיינו שכמו שדרך היונים להוליד גוזלות זכר ונקבה בכל חדש, כך יעלו ישראל לראות פני השכינה בכל חדש, ולשון עיניך הוא כמו אראה פני אלקי' כו', וכמשארז\"ל כדרך שבא לראות כך בא ליראות כו'.\n<b>ויובן</b> זה בהקדם ענין ר\"ח שכתי' ובאת אל המקום אשר נסתרת שם ביום המעשה, ות\"י ביומא דחולא וקאי על ער\"ח, אבל ר\"ח עצמו לא מצינו שיהי' נק' יום המעשה בל' הפסוק, וצ\"ל הלא ר\"ח מותר בעשיית מלאכה ומפני מה אינו נק' יום המעשה, אך הענין הוא דכתי' ששת ימים תעשה מעשיך, וצ\"ל למה צריך היתר לעשיות מלאכה, וגם הלא כתי' ששת ימים תעבוד כו', אך הנה מפני שאת השמים ואת הארץ אני מלא שלית אתר פנוי מיני' ומכה\"כ לכן הי' מהראוי שיהי' אסור ענין עשיית מלאכה, כמשל לפני המלך אסור לעשות מלאכה כמשארז\"ל אחוי לי' בידי' קטעו לו ימינו דמאן דמחוי במחוג קמי' מלכא קטלא חייב, ומכ\"ש לפני מלך מה\"מ הקב\"ה דלית אתר פנוי מיני' כנ\"ל הי' [צ\"ל] אסור עשיית מלאכה, לזה נא' ששת ימים תעשה מעשיך שהוא היתר על עשיית מלאכה, ומפסוק ששת ימים תעבוד לבד לא היו יודעים היתר ברור על מלאכה, שהרי במד\"ר בראשית פט\"ז פי' פסוק ויניחהו בג\"ע לעבדה ולשמרה, לעבדה ששת ימים תעבוד, ונת' במ\"א בדברי רז\"ל שלעבדה הוא רמ\"ח מ\"ע, וא\"כ י\"ל שזהו הכוונה גם בפי' ששת ימים תעבוד בעבודת רמ\"ח מ\"ע, ועשית כל מלאכתך קאי על מלאכת התורה שנק' ג\"כ בשם מלאכה כמארז\"ל בסוטה דמ\"ד ע\"א ע\"פ הכן בחוץ מלאכתך זה מקרא, ע' בד\"ה אבות מלאכות, לזה נא' עוד פסוק ששת ימים תעשה מעשיך שזהו היתר על עשיית מלאכה בחול, והיינו מפני כי גם הוא ית' עשה מלאכה בששת ימים כו'. וזהו שבע\"מ לא נאמר רק שם אלקי' כמ\"ש בראשית ברא אלקי', רק לאחר שבת נא' הוי' אלקי', דהנה שם אלקי' הוא מדת הצמצום והמסתיר שיהי' יש ודבר נפרד, דמצד בחי' שם הוי' בחי' ביטול אינו תופס מקום כלל וכולא קמי' כלא חשיב כו', אך מפני שעלה ברצונו אנא אמלוך ואין מלך בלא עם בחי' נפרדי', לזה הוא בחי' ש' אלקי' שמסתיר ומעלים עד שיהי' נראה העולם ליש ודבר נפרד כו', וזהו שמש ומגן ה' אלקי' כמו שהמגן מסתיר על השמש, כן בחי' שם אלקי' מסתיר על ש' הוי' להיות בחי' התהוות העולם ליש ודבר נפרד כו'. ולכן מותר בעשיית מלאכה, דהן אמת שלית אתר פנוי מיני' עכ\"ז הרי זהו בהעלם, ואפי' בחי' מלא כל הארץ כבודו ג\"כ אינו בבחי' גילוי לכן מותר עשיית"],[2000580147,"מלאכה, וגם כי הוא ית' עושה מלאכה בשית יומין דחול כמ\"ש ובטובו מחדש בכי\"ת מע\"ב, שבכל עת ובכל רגע נמשך חיות חדש להוות ולהחיות מאין ליש ע' בד\"ה אבות מלאכות ארבעים חסר אחת, אבל שבת להיות כי הוא בחי' שבת להוי' וכן יו\"ט שנק' מועדי הוי' או מועדי, אסורים בעשיית מלאכה, רק ביו\"ט הותר מלאכת אוכל נפש כו', מטעם שנת' בפע\"ח שער מקראי קדש רפ\"ג שהנהגת חול לא בטלה יעו\"ש, וע' בסדור בסעודת שבת בפי' ביני ובין בנ\"י אות היא לעולם. והגם כי הגילוי הוא רק בפנימיות העולמות דהיינו בנשמות ובמלאכים ולא בחיצוניות כו', מ\"מ אסור בעשיית מלאכה כו', משא\"כ בששת ימי החול שלא יש הגילוי משם הוי' כ\"א משם אלקי' מדת הצמצום כנ\"ל מותר בעשיית מלאכה.\n<b>אך</b> צ\"ל הלא כתי' ששת ימים עשה הוי' (בפ' יתרו ך' י\"א), ואיך שייך ל' עשי' בש' הוי'. אך הענין הוא דפי' עשה הוי' היינו ע\"י התלבשותו בש' אלקי', כנודע שש' הוי' הוא בחי' שורש האורות וש' אלקי' הוא שרש הכלים כמשנ\"ת מזה בד\"ה ואהבת את הוי' אלקיך למ\"ד, ומפני כי האורות שנמשכי' מבחי' ש' הוי' מלובשי' בכלי' ששרשן מש' אלקי' שייך לומר לשון עשה הוי', והיינו שזהו ע\"פ פי' האריז\"ל בפי' גרמוהי שקאי על בחי' זו\"נ האורות עם הכלים כו', ושורש התהוות העולמות הוא מבחי' גרמוהי כידוע, לכן שייך עשה הוי'. ומה שנת\"ל ששם הוי' הוא בחי' ביטול דקמי' כלא חשיב, הכוונה הוא על בחי' האור עצמו כמו שהוא בלתי מלובש בכלים כו', או בחי' שם הוי' דחכ' כמ\"ש הוי' בחכ', וגם לפי מה שהאור מלובש בכלי שעז\"נ עשה הוי' מ\"מ לגבי בחי' ש' הוי' שהוא בחי' האור המאיר בכלים דזו\"נ אינו שייך ל' ברא כ\"א ונבראו מאליו וממילא, כמ\"ש מזה במ\"א ע' בלק\"ת בשה\"ש בד\"ה קול דודי ובההגהות לשם. וע' בד\"ה זכור ה', ובד\"ה ואהבת, למ\"ד. ויותר נראה לומר דהנה בתחלה עלה במח' לברוא את העולם במדה\"ד בראשית ברא אלקי' ראה שאין העולם מתקיים שיתף עמו מדה\"ר, שזהו מ\"ש ביום עשות ה' אלקי' ארץ ושמים, וע' במד\"ר ס\"פ י\"ב ע\"פ ביום עשות ה' אלקי' למלך שהיו לו כוסות ריקים כו' חמין מתבקעין,"],[2000580148,"צונן הן מקריסין (פי' מתבקעין בלי חסרון) עירב חמין בצונן ונתן בהם ועמדו, כך אמר הקב\"ה אם אני בורא את העולם במדה\"ר חטויה סגיאין במדה\"ד האיך העולם יכול לעמוד אלא אני בורא אותו במדה\"ד ומדה\"ר. ונמצא כי שיתף מדה\"ר שזהו בחי' שם הוי' לכן שייך לומר עשה הוי', גם לפי מה שפי' בד\"ה איהו וחיוהי שגרמוהי הם כלים דע\"ס, מ\"מ צ\"ל שיתף מדה\"ר דאל\"כ האיך העולם יכול לעמוד, ולכן שייך לומר עשה הוי' כו'.\n<b>אך</b> עדיין צ\"ל מהו שאמר ששת ימים עשה הלא במאמר א' יכול להבראות וכמו\"כ ברגע א', אך הענין הוא דהנה בריאת העולם הוא מבחי' ששה מדות וכמ\"ש כי אמרתי עולם חסד יבנה וגם מבחי' חכ' המלובש במדות, וזהו בראשית ברא אלקי', בראשית הוא ב' ראשית, שיש ב' בחי' חכ' ח\"ע וח\"ת, ועיקר הבריאה הוא מבחי' ח\"ת כו' בחי' ש' אלקי' המצמצם בכדי שיהי' יש ודבר נפרד כו', והמכוון מבחי' ירידה זו בכדי להעלות בחי' המעשה שיתעלו כל בחי' המעשה ג\"כ לקשרה בהוי' אחד, שהמלאכות הם לצורך האדם וחיותו וקיומו, וכאשר האדם נושא את נפשו בתפלתו לה' אחד בק\"ש ואהבת כו' ובתפלה ברוך אתה כו' ע\"י כח האכילה ההיא, או שמברך ברכות על המאכל, הרי גם כל כחות החיונית שבמלאכות שהם חיותו וקיומו מתעלי' עמו ונכללי' באחד כי בהם וע\"י ניתן הכח לאדם להעלות ולקשר נפשו באלקי' חיים בק\"ש ותפלה, והעלאה זו הוא ע\"י החכ' דבחכ' אתברירו לפי שהחכ' היא בחי' ביטול, ולכן ע\"י החכ' יוכל להיות ביטול היש כו' עד שיבוא לבחי' שבת שהוא בחי' שבת להוי' בחי' ביטול כו', ואז אסור בעשיית מלאכה כו'.\n<b>וזהו</b> שנא' בשבת ממצוא חפצך ודבר דבר וארז\"ל שלא יהא דבורך של שבת כדבורך של חול, שבשבת דבור אסור, והיינו מפני כי דבור הוא ל' הנהגה, ולמעלה הוא בחי' עיר אלקינו בחי' עולם הדבור וכמו שאנו רואים באדם שהדבור הוא נפרד ויוצא לחוץ, משא\"כ בחי' המחשב', כך עד\"ז יובן למעלה שבחי' הדבור הוא מקור להתהוות עולמות הנבראי' ונפרדי' כו', ולכן בשבת דבור אסור כי שבת הוא בחי' השביתה ואז הוא בחי' גילוי הוי' כו', אמנם לפ\"ז צ\"ל הלא השביתה למעלה הי' מבחי' הדבור והי' צ\"ל עיקר האיסור למטה בבחי' הדבור ובאמת עיקר האיסור מדאוריי' הוא רק מעשה והדבור אינו אסור אלא מדרבנן, אבל דין תורה מותר הדבור. ומה שארז\"ל בירושלמי מה הוא שבת ממאמר אף אתה שבות ממאמר זהו רק מדרבנן, אך הענין הוא דהנה דבורו של הקב\"ה הוי מעשה וכמ\"ש בדבר ה'"],[2000580149,"שמים נעשו, וכתי' באברהם לזרעך נתתי את הארץ הגם כי עדיין לא ניתנה, אך מפני שאמר לו הקב\"ה כך הרי הוא דומה כאלו כבר ניתנה, ובאמת למעלה כבר נתן לו בחי' ארץ העליונה כו', וא\"כ דבורו של הקב\"ה הוי ממש כמעשה דמאי איכפת לי' אם נתהווה מבחי' מעשה או מבחי' הדומה למעשה דהיינו בחי' דבורו של הקב\"ה כו', לכן עיקר האיסור דין תורה הוא המעשה כי מבחי' דבור של האדם לא יתהווה מאומה, משא\"כ מבחי' המעשה, שע\"י מעשה האדם יוכל להעשות והרי הוא דומה לדבורו של הקב\"ה כביכול שמדבורו של הקב\"ה נתהווה, וממעשה האדם יוכל להעשות כו', משא\"כ מבחי' הדבור כו'. אך מ\"מ מפני כי הדבור דומה קצת לדבורו של הקב\"ה ששניהם הם בחי' דבור לכן אסור מדרבנן גם בחי' הדבור כו', וזהו ודבר דבר שדבור אסור רק מדרבנן כו'.\n<b>וע\"פ</b> הקבלה מעשה בראשית נת' בפרד\"ס בשער ערכי הכנויים שהוא בחי' מל' ובל' המד\"ר נק' אדריכל, וענין הצמצום הוא בחי' הפרסא ויש כמה בחי' פרסא שיש פרסא באצי' גופא שזהו מ\"ש והבדילה הפרוכת לכם בין הקדש ובין קדה\"ק כו', וגם בבחי' מל' דאצי' יש בחי' פרסא ויש פרסא שמפסיק בין יצי' לעשי' שמסתיר ומעלים לגמרי, הגם כי קמי' ית' אינו מסתיר כלל אבל מאחר שמסתיר לפנינו לכן מותר בעשיית מלאכה, כי זהו אינו נק' בפני המלך כי הפרסא מסתיר כו', אבל בשבת הוא בחי' עליות הדבור ומאיר מלמעלה מן הפרסא הרי העושה מלאכה בשבת דומה כעושה מלאכה בפני המלך כו', לכן בשבת אסור עשיית מלאכה, ואפי' דבור אסור מדרבנן כי בשבת הוא בחי' עליות הדבור למקורו כו'.\n<b>והנה</b> שבת ור\"ח בבחי' אחת הם דומים זל\"ז, והיינו כמשארז\"ל בתעניות שמש בשבת צדקה לעניים שנא' וזרחה לכם יראי שמי שמש צדקה ומרפא בכנפי'. הנה עיקר הפסוק קאי על מ' לע\"ל, במלאכי ג' פ\"ך, ורז\"ל דרשו משמש צדקה ששמש בשבת צדקה לעניים כו', נמצא ששבת הוא בחי' שמש, ור\"ח הוא ג\"כ בחי' שמש כי עיקר ענין ר\"ח הוא מה שהלבנה מקבל הארה מהשמש כו', ולכן בשבת נא' וזרחה לכם כו' ובר\"ח נא' ג\"כ לכם כמ\"ש החדש הזה לכם. ולהבין ענין מה ששבת נק' שמש צ\"ל מ\"ש שמש צדקה ומרפא, דהנה כתי' סמכוני באשישות כו' כי חולת אהבה אני, וקאי על ששת ימי החול כי חול יש בו ב' פירושי', הא' ל' חולין, הב' ל' חולי, והיינו כי בשית יומין דחול הוא בחי' חולת אהבה, והיינו ממה שהיש הוא היפך האין, דהנה האין הוא בחי' הביטול דכולא קמי' כלא חשיב, והיש הוא בחי' יש ודבר נפרד היפך האין, והגם כי היש נמשך מבחי' אין אכן הנה הוא ע\"י צמצומי' רבים עד שנעשה ליש ודבר נפרד, וממילא בחי' כח אלקי זה המחי' ומהוה בחי' היש הוא תמיד בתשוקה נפלאה ונכספה וגם כלתה נפשו לעלות להתכלל באור הוי' א\"ס ב\"ה,"],[2000580150,"ואהבה בכלות הנפש כזו הוא בחי' חולה מפני תוחלת ממושכה אשר תמיד נכספה וגם כלתה נפשה ולא תגיע לה כל ימי חייה כו', וכמו באדם כאשר רוצה איזה דבר בכלות הנפש וא\"א לו להשיג בא מזה לידי חולי כו', וכך עד\"ז יובן בשית יומין דחול שמאיר ע\"י צמצום דשם אלקי' בכדי שיהי' יש ודבר נפרד כנ\"ל, לכן הוא בחי' חולת אהבה. אבל שבת הוא בחי' רפואה כי בשבת מאיר בחי' ש' הוי' גילוי אלקות כנ\"ל לכן הוא מרפא וזהו שמש צדקה ומרפא, וזהו שמש בשבת צדקה לעניים והיינו בשבת שמאיר בחי' שמש הוי' הוא צדקה לעניים דלית לון מגרמייהו כלום, והיינו כמו שע\"י הצדקה שנותן לעני דלית לי' מגרמי' כלום הוא מחי' אותו, כך בחי' שמש הוי' שמאיר בשבת הוא כמו צדקה לעניים. ולכן אומרים בשבת ישבעו ויתענגו מטובך, כי טוב ואור הוא בחי' א' כמ\"ש וירא אלקי' את האור כי טוב, והטוב ממשיך האור, ובשבת כשמאיר בחי' האור דשמש הוי' אומרים ויתענגו מטובך כו'. אך ע\"י מה יבוא לבחי' זו זהו ע\"י צדקה לעניים כי מי שטרח בע\"ש יאכל בשבת והיינו ע\"י בחי' ההכנה בשית יומין דחול בתפלה, וקודם התפלה צ\"ל צדקה כמו ר\"א יהיב פרוטה כו', (וגם ע\"ז נתקן ענין קבלת שבת לכה דודי לקראת כלה כו' לכה דודי שיהי' הארה מלמעלה לקראת כלה היא כנס\"י כדי שפני שבת נקבלה כו'), ובדרך פרט יש בכל יום כמו שבת וחול, שהתפלה היא כמו בחי' שבת וכל היום הוא חול כו', וההפרש שבין העלאה דשבת להעלאה שבחול בעת התפלה, כי אינו דומה בן כרך שראה את המלך לבן כפר שראה כו', שזהו ההפרש שבין שרפי' לחיות ואופנים שהאופנים וחיות הקדש הם ברעש גדול ע\"י השגתם בחי' קדוש ומובדל כו' והם אינם יכולים להגיע כו' לכן הם ברעש גדול, והרי זהו דומה לבן כפר שראה כו' עד\"מ, שביטולו מפני המלך מחמת חידוש רוממותו למעלה מגדר השגתו, וזהו בחול בעת התפלה, משא\"כ בשבת הוא בחי' התגלות עונג העליון ולכן אומרים ישבעו ויתענגו כו', אז הוא דומה לבן כרך שראה עד\"מ, שאין חידוש בעיניו רוממות המלך אלא מתענג ונהנה מזיו יקר תפארת גדולתו.\n<b>ומעתה</b> יובן ענין ר\"ח שהוא ג\"כ בחי' גילוי שנק' זה כמ\"ש החדש הזה וכמ\"ש ביום הזה באו מדבר סיני וארז\"ל שהי' בר\"ח נא' כאן הזה ונא' החדש הזה כו', והיינו כי ר\"ח נק' זה להיות כי זה רומז לבחי' הגילוי כמו שאמרו בים זה אלי כו', וכענין משה נתנבא בזה זה הדבר כו', ובר\"ח הוא בחי' גילוי היינו כי הלבנה מקבל הארה מבחי' שמש הוי' כו', אך כדי שיהי' הגילוי מבחי' שמש הוי' שכינתא עילאה (ע' בפרד\"ס בעה\"כ פך\"א) בסיהרא בחי' שכינתא תתאה צ\"ל נמשך כח לזה מלמעלה, והיינו שכדי שיהי' יחוד שמשא וסיהרא צ\"ל נמשך כח לזה מבחי'"],[2000580151,"הגבוה יותר. וזה מ\"ש שער החצר הפנימית הפונה קדים סגור יהי' ששת ימי המעשה וביום השבת יפתח וביום החדש יפתח, פי' הפונה קדים כי קדם הוא למעלה מבחי' ראשית כי כשיש ראשית יש שנית ושלישית והיינו בחי' ע\"ס שחכ' היא ראשית ההשתל', אבל בחי' קדם הוא למעלה מע\"ס והיינו בחי' כתר כו', וכדי שיהי' יחוד שמשא וסיהרא נמשך מבחי' קדם, וזהו סגור יהי' ששת ימי המעשה כי בששת ימי המעשה הוא בחי' הסתר והעלם כנ\"ל, וביום השבת יפתח וביום החדש יפתח, ביום השבת וביום החדש דוקא יפתח להיות כי בשבת ובר\"ח מאיר מבחי' שמש הוי' כו', וזהו שאומרים בשבת לשמש שם אהל בהם והוא כחתן יוצא מחופתו, פי' אהל הוא בחי' מל' בחי' ש' אלקי' המסתיר על בחי' השמש הוא בחי' שמש הוי', וכדי שיהי' בחי' שמש הוי' יוצא כחתן הוא בחי' חות דרגא צ\"ל נמשך כח לזה מחופתו בחי' החופה שעל כל כבוד כו', דהיינו בחי' פונה קדים הנ\"ל, ואומרים זה בשבת לפי שבשבת הוא גילוי שם הוי' כו', וזהו ג\"כ ענין משארז\"ל על ר\"ח שאמר הקב\"ה הביאו עלי כפרה על שמיעטתי את הירח, פי' עלי היינו כמו על הוי' והיינו בחי' הפונה קדים כו'.\n<b>אמנם</b> הנה לפ\"ז צ\"ל הלא שבת ור\"ח הם בחי' אחת, ומפני מה בשבת אסור עשיית מלאכה ובר\"ח הגם כי אינו נק' יום המעשה בל' הפסוק כמו שית יומין דחול, מ\"מ הוא מותר בעשיית מלאכה. והענין הוא מפני כי עיקר בחי' ר\"ח הוא בחי' דבור, והגם כי בר\"ח הלבנה מקבלת הארה מבחי' שמש הוי', היינו כי בר\"ח נמשך מלמעלמ\"ט הארה מבחי' שם הוי' בשם אלקי' הוא בחי' דבור כנ\"ל, ומ\"מ הוא בחי' דבור, וה\"ז כמו שמצינו בענין הדבור שלפעמים הוא מקבל מבחי' המדות כמו כשמדבר שיחת חולין שלפי שאוהב את הדבר מדבר בו או מפני שכועס כו', ולפעמים הדבור מקבל מבחי' השכל שמדבר מה שמבין בשכלו כמו הדבור בד\"ת כו'. ועד\"ז יובן ענין ר\"ח ושית יומין דחול, שבשית יומין דחול הדבור מקבל מבחי' המדות, משא\"כ בר\"ח הדבור מקבל הארה מבחי' החכ', ולכן אינו נק' יום המעשה בל' הפסוק להיות כי אז הדבור מקבל מבחי' הגבוה יותר כו', משא\"כ בשבת הוא עליות הדבור לבחי' חכ' לכן אסור בעשיית מלאכה כו'. וביאור הענין הנה ההפרש שבין שבת לר\"ח הוא ההפרש בין שילוב ה' באד' ובין שילוב אד' בהוי', כמ\"ש בסש\"ב ח\"ב שאות הראשון הוא גובר ולכן בשילוב אד' בהוי' הנה אות הראשון הוא יו\"ד של שם הוי' אז שם הוי' גובר, ולכן בשבת שהוא עליות הדבור הוא בחי' ש' אד' (כי אד' ואלקי' הם בחי' א') בבחי' חכ' הוא בחי' שם הוי' אסור בעשיית מלאכה ואינו נק' יום המעשה כלל, משא\"כ בר\"ח הוא בחי' שילוב ה' באד' אז שם אד' גובר, והיינו כי עיקר הגילוי הוא משם אד' כי אזלת לקרתא עביד כנימוסהא וכמו במשה כשעלה אל האלקי' לא אכל ולא שתה, והמלאכים שירדו למטה אכלו והיינו מטעם הנ\"ל, ולכן"],[2000580152,"בר\"ח שהעיקר הוא בחי' הדבור, רק כי בר\"ח הדבור מקבל הארה מבחי' ש' הוי', אבל עיקר הגילוי למטה הוא בחי' הדבור, לכן מותר בעשיית מלאכה, אך מפני כי הדבור אז אינו כמו בשית יומין דחול כנ\"ל לכן אינו נק' יום המעשה בל' הפסוק כו'.\n<b>והנה</b> כ\"ז הוא בחי' שבת וחדש שאחר יומין דחול, אבל לעתיד והי' מדי חדש בחדשו ומדי שבת בשבתו דהיינו חדשו של חדש ושבתו של שבת, פי' שהשבת דעכשיו נחשב כחול לגבי בחי' השבת שיתגלה לעתיד, ועד\"ז הו\"ע חדשו של חדש. ולהבין זה, הנה כתי' והי' אור הלבנה כאור החמה ואור החמה יהי' שבעתיים כאור שבעת הימים, פי' הפשוט שאור הלבנה יהי' כאור החמה דעכשיו, ואור החמה יהי' עוד יותר גדול, והיינו שבעתיים כאור שבעת הימים, נמצא שגם לע\"ל יהי' בחי' שמש ולבנה, והלבנה דלעתיד תקבל הארה מהשמש דלעתיד. והענין הוא דהנה כתי' ביום ההוא יהי' הוי' אחד ושמו אחד וארז\"ל אטו האידנא לאו אחד הוא, לא כמו שאני נכתב אני נקרא, נכתב בשם הוי' ונק' בשם אד', פי' הגם כי הכתיב הוא ש' הוי', אבל הגילוי למטה הוא רק שם אד' שמסתיר ומעלים, ורק במקדש היו קורין את השם ככתבו, אבל במדינה בכנויו והיינו בשם אד', אבל לע\"ל יהי' שמו אחד שיהי' נק' כמו שנכתב, והיינו כי אז יהי' הגילוי שם הוי'. וזהו שאור הלבנה שהיא בחי' שם אד' וש' אלקי' יהי' כאור החמה הוא בחי' ש' הוי', וזהו שמו אחד. והוי' אחד הוא, כי הנה כתי' ויקרא הוי' הוי' ופסיק טעמא בגווייהו שיש בחי' שם הוי' דלתתא שהוא מקור המהוה ומחי' כו', אבל בחי' שם הוי' דלעילא הוא למעלה מגדר עלמין ולכן פסיק טעמא בגווייהו, אבל לעתיד יהי' הוי' אחד שלא יהי' פסיק טעמא, ושם הוי' דלתתא יהי' במדרגת ש' הוי' דלעילא כו', וזהו ה' אחד שההויות יהיו אחד, וזהו ואור החמה הוא בחי' שמש הוי' יהי' כאור שבעת הימים בחי' ז\"ת דע\"י, וזהו ענין שבתו של שבת. ועד\"ז יהי' ענין חדשו של חדש, כי הנה י\"ב חדשי' הם בחי' י\"ב בקר דבריאה והים הוא מל' דאצי' עליהם מלמעלה ושרש קבלתם הוא מבחי' י\"ב גבולי אלכסון דאצי', אבל לע\"ל יקבלו בר\"ח מבחי' יגמדה\"ר דאריך, וזהו חדשו של חדש שי\"ב ר\"ח יקבלו מבחי' יגמדה\"ר דא\"א (ומה שבחדשי' הוא רק י\"ב ומדה\"ר דאריך הם י\"ג מדות, אפ\"ל כי בר\"ח נמצא חדש העיבור, או כנגד י\"ב בקר והים עליהם מלמעלה הרי הם י\"ג, ולע\"ל יקבלו מבחי' י\"ג מדות כו'), ואז יבוא כל בשר להשתחוות, והיינו"],[2000580153,"שכמו שהי' מצות ראי' ברגלים יהי' לעתיד כן ויותר מזה בכל חדש וחדש ובכל שבת ושבת.\n<b>ולהבין</b> זה צ\"ל הלא מצות ראי' ברגלים היא בחי' גבוה מאד כמשארז\"ל כדרך שבא לראות כך בא ליראות פני השכינה, ופי' ענין הראי' שהיו מקבלים גילוי הארה בנפש ומפני מה הי' ביו\"ט דוקא ולא בשבת, הלא שבת גבוה מבחי' יו\"ט שלכן ביו\"ט שחל להיות אחר השבת מבדילי' המבדיל בין קדש לקדש. אך הענין הוא דהנה ארז\"ל במד\"ר ר\"פ אחרי ישראל לא שמחו בעולמי, שמח ישראל בעושיו אינו נאמר אלא ישמח, עתידים הם לשמוח במעשיו של הקב\"ה לע\"ל, כביכול הקב\"ה לא שמח בעולמו, שמח ה' במעשיו אינו אומר אלא ישמח, עתיד הקב\"ה לשמוח במעשיהם של צדיקי' לע\"ל, והיינו מפני כי עכשיו אין השמחה בשלימות, ואע\"פ שיש שמחה של מצוה מ\"מ אינה בשלימות כי יש בחי' עצבות כו', וכמ\"כ יובן למעלה כביכול הגם שנא' עוז וחדוה במקומו מ\"מ אין השמחה בשלימות מפני כי למטה הוא יש ודבר נפרד, והוא מפני שיש למעלה בחי' מדה\"ד המצמצם עד שיהי' נראה ליש ודבר כנ\"ל, לכן אין השמחה בשלימות, אבל לע\"ל יהי' השמחה בשלימות כו'.\n<b>והנה</b> היו\"ט הם מועדי' לשמחה וכמ\"ש ושמחת בחגך שאז הוא בחי' התגלות השמחה, משא\"כ שבת לא מצינו שיהי' נק' יום השמחה, כ\"א בל' התורה נק' יום המנוחה ובל' הנביאים הוא בחי' ענג כמ\"ש וקראת לשבת ענג, אבל יו\"ט הם זמן השמחה, והיינו מפני כי ג' יו\"ט הם כנגד ג' אבות, והאבות הטעימן הקב\"ה מעין עוה\"ב לכן הם מועדי' לשמחה. והשמחה גורם גילוי כמשל המלך שהוא יושב בתמידות בחדרי חדרים ובעת שמחתו הוא מתגלה לעין כל, כך עד\"ז יובן לפי שיו\"ט הם זמן השמחה לכן אז דוקא מאיר גילוי אלקותו ית', ולכן ביו\"ט דוקא היו רואים פני השכינה.\n<b>וע\"פ</b> הקבלה הנה שבת הוא מוחין דאבא, ויו\"ט הוא מוחין דאימא, וצ\"ל מפני מה מצות ראי' היא ביו\"ט דוקא, ותירץ בפע\"ח שמוחין דאבא הגם כי הם גבוהים יותר ממוחין דאימא אבל הם מאירים ע\"י ב' לבושי', היינו בחי' נה\"י דאבא ונה\"י דאימא, משא\"כ מוחין דאימא מאירים ע\"י לבוש א' היינו בחי' נה\"י דאימא לבד, לכן הם מאירים בגילוי יותר כו', וגם הנה באמת פעמים מצינו מעלה יתירה בבחי' בינה מבחכ', והיינו מפני כי התגלות עתיק הוא בבינה, וביאור הענין הנה כתי' ומבני"],[2000580154,"יששכר יודעי בינה לעתים וארז\"ל דאפי' בימי משה לא אשתכח כוותייהו דכתי' הבו לכם אנשים חכמים ונבונים וידועים כו' ואח\"כ ואקח את ראשי שבטיכם אנשים חכמים וידועים ואלו נבונים בימי משה לא אשתכח, והיינו כי חכם נק' מי שמבין השכל היטב הגם כי לא יוכל להסבירו לזולתו, אך מפני כי בעצמו מבין את השכל נק' חכם, אבל נבון הוא שיוכל להסביר את השכל לזולתו שזהו מעלה יתירה, וע\"ד שמצינו בשלמה שא' שלשת אלפים משל כתי' עליו ויחכם מכל האדם, שכדי שיוכל להבין ולהסביר לזולתו צ\"ל נמשך מבחי' הגבוה יותר, ועד\"ז הוא ההפרש שבין חכ' לבינה שבינה הוא בחי' השגה והבנה ויכול להיות בבחי' גילוי למטה והיינו מפני כי בבחי' בינה מאיר התגלות ע\"י, משא\"כ בבחי' החכ' שנק' אב רם שכל הנעלם מכל רעיון, ולכן הי' מצות ראי' ברגלים שהם מוחי' דאימא דוקא ולא בשבת שהוא בחי' מוחין דאבא.\n<b>אך</b> לע\"ל כתי' והי' מדי חדש בחדשו ומדי שבת בשבתו, ורגלי' לא נא' מפני שברגלים הי' גם בזמן בהמ\"ק ולע\"ל יהי' התחדשות שגם בר\"ח ובשבת יבואו לראות פני השכינה, מפני כי לע\"ל יהי' גילוי השמחה שהשמחה יהי' בשלימות וכמ\"ש ישמח הוי' במעשיו לע\"ל ישמח אותיות משיח היינו כשישכיל עבדי ירום ונשא וגבה מאד כו', ואז יהי' הגילוי בבחי' ראי' ע\"ד הראי' דרגלי' גם בר\"ח ובשבת, דכמו שעכשיו אומרים בשבת ויתענגו מטובך היינו שע\"י בחי' הטוב מאיר האור דשמש הוי' כנ\"ל, א\"כ לע\"ל שיהי' הוי' אחד שש' הוי' דז\"א יתעלה להיות במדרגת ש' הוי' דלעילא ז\"ת דע\"י, יהי' הגילוי למטה ג\"כ יותר ע\"י בחי' טוב היותר גבוה, והיינו בחי' מה רב טובך אשר צפנת ליריאך, צפנת בגימ' כתר, וגם אשר צפנת ליריאך למפרע בס\"ת אותיות כתר, והיינו ב' הבחי' שבכתר ע\"י וא\"א, ובחי' רב טובך הוא בחי' יסוד דעת\"י המקשר ומחבר גילוי אוא\"ס ממש באצי', יאיר גילוי זה בבי\"ע כו', ע' בלק\"ת בביאור ע\"פ כי ההרים ימושו בפי' וברית שלומי לא תמוט. ולכן לע\"ל כשיתגלה בחי' פנימיות ע\"י יהי' גילוי זה באבא, שגם אבא יאיר בגילוי בשבת כמו אימא ביו\"ט, וא\"כ אדרבה פנימיות אבא הוא פנימיות עתיק כנודע, לכן מדי שבת בשבתו יבואו להשתחוות כו'. וכמו\"כ בר\"ח בחי' חדשו של חדש, חדש בחי' דבור בחי' מל', וחדש אשתו ילדה, והיינו בחי' חכ' תתאה אשר יש מעלה בחכ' תתאה משום נעוץ סופן בתחלתן ותחלתן בסופן, ולכן בזאת יתהלל המתהלל כו' בזאת דוקא בחי' חכ' תתאה, ועי\"ז השכל וידוע אותי בחי' עצמיות אוא\"ס שלמעלה מבחי' הנרמז בשם ואות כו' (וי\"ל שזהו בחי' קוש\"י או עוד יותר גבוה היינו מה דלא אתרמיז בשום אות וקוץ כו'), אשר ע\"י שישכיל עבדי לע\"ל בבחי' מאד בלי גבול נחלה בלי מצרים יהי' גילוי בחי' זו, ולכן גם בר\"ח יבוא כל בשר להשתחוות כו'."],[2000580155,"<b>ופי'</b> יבוא כל בשר כו', הנה בפי' בשר יש בו כמה פי', הא' כמשארז\"ל בילקוט א\"ר אלעזר כל מי שנעשה כבשר בעוה\"ז זוכה לראות פני שכינה, והיינו כמארז\"ל בפ\"ק דסוטה ד\"ה סע\"א בשר כתי' בי' ונרפא אדם לא כתי' בי' ונרפא, ופי' אדם הוא קשה, אבל בשר הוא רך ועניו כו', ולכן בשר כתי' בי' ונרפא כו' שנכנע מהיסורי' כמו שפירש\"י ז\"ל שקרוב להתרפאות כו', והיינו בחי' סור מרע כו', דבאמת כדי שיוכל להיות מלך ביפיו תחזינה עיניך כתי' לעיל מיני' (ישעי' ל\"ג) ועוצם עיניו מראות ברע, פי' מי שעוצם עיניו מראות ברע דהיינו בחי' סור מרע מלך ביפיו תחזינה היינו בחי' יראה פני אלקי' כו'. ועוי\"ל בשר עדמ\"ש ואחרי עורי נקפה זאת ומבשרי אחזה אלוה, (באיוב י\"ט ך\"ו), וארז\"ל במד\"ר ר\"פ וירא שקאי על אברהם בענין המילה דהיינו אחר שהעביר עור הערלה שהוא מסתיר ומעלים לגמרי כידוע אז מבשרי אחזה אלוק' כו', דהיינו ע\"י בחי' בריתך שחתמת בבשרינו, שע\"י נטירת הברית עי\"ז יזכה לראות פני השכינה כו'. ועוי\"ל בשר, שאפי' כל בשר יבואו להשתחוות, והענין הוא דלע\"ל נא' (ביואל ג' א') והי' אחרי כן אשפוך את רוחי על כל בשר, דהנה כתי' לא ידון רוחי באדם בשגם הוא בשר שבתחלת הבריאה נברא האדם במעלה עליונה שידון רוחי באדם אך ע\"י שהוא בשר כו' שנמשך אחר תאוות הגוף לכן לא ידון רוחי, ופי' ידון ל' נדן ונרתק שהגוף לא יהי' נדן ונרתק לבחי' רוח כו'. אך לע\"ל נא' והסירותי את לב האבן מבשרכם ונתתי לכם לב בשר, כי הנה יש פי' בבשר ע\"ד מ\"ש כל הבקר לעולה שקאי על המלאכי' שנק' בשם בקר והיינו בחי' בשר שהוא רשפי אש ותשוקה נפלאה אליו ית', ולע\"ל יהי' בחי' בשר ע\"ד כל הבקר לעולה כו', ולכן ארז\"ל משה מן התורה מנין שנא' בשגם הוא בשר בשגם גימ' משה והיינו שהוא בחי' בשר ע\"ד כל הבקר כו' (ולכן כשהי' בהר ק\"ך יום לחם לא אכל כו' שהגוף שלו הי' ניזון מרוחניות ע\"ד המלאכי' כו'). וזהו אשפוך את רוחי על כל בשר, הנה ל' שפיכה הוא ל' ריבוי דהיינו ריבוי השפעת בחי' הרוח בחי' רוח הקדש וגילוי אלי', וזהו יבא כל בשר כו' להשתחוות לפני, פי' השתחווא' כולל ב' בחי' העלאה והמשכה כי ההשתחוואה הוא ביטול והעלאה מלמטלמ\"ע, אך כמו למשל בענין ההשתחוואה הנה האדם מרכין ראשו שמרמז לבחי' המשכה, כך עד\"ז יובן למעלה שע\"י ההשתחווא' גורם המשכה, וזהו להשתחוות לפני אמר הוי' שיומשך ע\"י ההשתחווא' שהוא בבחי' לפני המשכת תוס' אורות בשם הוי', וזהו אמר הוי' כו'.\n<b>וזהו</b> שא' בילקוט בעוה\"ז הייתם עולי' לרגל שלש פעמי' בשנה שנא' שלש פעמי' בשנה יראה כל זכורך, אבל לע\"ל והי' מדי חדש בחדשו ומדי שבת בשבתו יבא כל בשר כו' להיות כי יהי' גילוי השמחה דישמח ה' במעשיו, וישמח ישראל בעושיו כו'."],[2000580156,"<h3>ועשו לי מקדש</h3>\n<b></b><b>בס\"ד. (ש\"פ תרומה, ל\"ב).</b>\nתרומה\n<b>ועשו</b> לי מקדש ושכנתי בתוכם, הנה ארז\"ל במד\"ר פ' ויקרא פ\"ב כל מקום שנא' לי אינו זז לא בעוה\"ז ולא בעוה\"ב וחשיב המקדש שנא' ועשו לי מקדש, הקרבנות להקריב לי, ישראל וארשתיך לי, והיינו כי באצי' יש חו\"ג, ולכן מצד מדת הגבורה יקרא שתתעכב ותמנע ההשפעה שלא יומשך לעולם, אבל בע\"ק לית שמאלא לכן משם נמשך לעולם, וזהו כל מקום שנא' לי שרומז לע\"ק אינו זז לעולם לפי שלית שמאלא בהאי עתיקא. וצ\"ל הלא עכשיו ליכא מקדש וקרבנות, ובמתנות כהונה שם פי' הגם שכעת ליכא בהמ\"ק וקרבנות מ\"מ כל הני דחשיב כולם עומדי' עדיין, וצ\"ל זה.\n<b>והענין</b> יובן ע\"פ משנ\"ת בלק\"ת פ' עקב בד\"ה ולהבין שורש טעם, מנ\"ל דברכת הארץ בזמה\"ז דאורייתא הלא הארץ אינה תח\"י ישראל, והיינו כי הארץ העליונה ברוחניות ניתנה לאברהם ולזרעו אחריו עד עולם, וזהו שנק' ארץ כנען ל' הכנעה ול' סוחר ותגר כמ\"ש אשר גו' כנעניה נכבדי ארץ, ופי' ל' סוחר שיש בזה שני בחי' משיכה וכסף, משיכה הוא בחי' העלאות מלמטלמ\"ע ע\"י שיתבונן שנשמה שנתת בי אתה בראת ואתה יצרת ואתה עתיד ליטלה ממני ולהחזירה לי לע\"ל, ואי לזאת גם עכשיו ימאוס בחיי נפשו להיות בטל ונכלל ביחודו ית', וז\"ע משיכה בחי' העלאה מטורי דפרודא לבחי' יחוד עליון, וכסף הוא אור האהבה עליונה שנמשך ע\"י העלאה זו שז\"ע בחי' כסף מל' נכסוף נכספתי ל' כיסוף ואהבה, וז\"ע ת' עלמין דכסופין דירתין צדיקייא לע\"ל שהם מבחי' תענוג עליון, שכ\"ז הוא בחי' ארץ כנען ל' סוחר ותגר. וא\"כ ישנה בחי' ארץ כנען ברוחניות גם עכשיו. וזהו כי לי כל הארץ, כי דור הולך ודור בא, פי' ע\"ס נק' דור דור, אבל הארץ לעולם עומדת בחי' מל', ע' בז\"ג פ' בראשית עמוד קנ\"ג וע' קע\"ג, ובזח\"ג בר\"מ פנחס דרי\"ו ע\"ב, ובפ' עקב"],[2000580157,"בר\"מ דרע\"ג א'. ובמד\"ר פי' דור הולך על המלכיות שאינה נוגעת בחברתה כו'. והיינו שכ\"מ שנא' לי אינו זז.\n<b>וכמ\"כ</b> י\"ל בענין בהמק\"ד, כי מקדש העליון שנק' מקדש אד' מחובר למקדש התחתון, וכמו בענין כעיר שחוברה לה יחדיו כו', ירושלי' שלמעלה מחובר לירושמ\"ט. וזהו שאינו זז שגם עכשיו יש בחי' בהמק\"ד, וכענין היריעות והקרשי' שיש בחי' זו בנפש כמ\"ש בלק\"ת בד\"ה נשא, ועד\"ז בחי' אהל ומשכן זהו תושב\"כ ותושבע\"פ, וזהו אדם כי יקריב מכם ולכאו' הי' צ\"ל אדם מכם כי יקריב, אך הענין הוא דאדם היינו מחדומ\"ע של התורה שהם במקום האהל והמשכן כי יקריב מכם היינו העלאת נה\"ב בתפלה כו', וזהו אדם כי יקריב מכם. וענין מזבח החיצון והפנימי' ז\"ע חיצוניות הלב ופנימיות הלב, גם בבהכנ\"ס מאיר הארה מבחי' בהמק\"ד שלכן נק' מקדש מעט וזהו אינו זז כו' לפי שנא' ועשו לי מקדש.\nב) <b>והנה</b> ענין ושכנתי בתוכם, הנה כתי' כי בועלייך עושייך וארז\"ל אין האשה כורתת ברית אלא למי שעשאה כלי, וז\"ע מקדש אד' כוננו ידיך בחי' באר חפרוה שרי', נמצא זהו מה שיהי' האדם בבחי' באר מים חיים שה\"ע אליך ה' נפשי אשא, וז\"ע חפרוה שרי' במחוקק גימ' רמ\"ח שעי\"ז נעשה החקיקה בנפש. וזהו שארז\"ל כתובות דס\"ב ע\"ב בבן רבי כשהעבירוה קמי' אמר אכנוס והדר איזל, א\"ל רבי בני מדעת קונך יש בך, תחלה אמר תביאמו ותטעמו בהר נחלתך מכון לשבתך כו' ואח\"כ אמר ועשו לי מקדש, מוכח דהמקדש ושכנתי בתוכם זהו כענין יחוד חו\"כ, והיינו ענין הלוחות שהיו בארון, שה\"ע המשכת אור התורה בישראל, אך לפמש\"נ לעיל דהאוהל והמקדש עצמו זהו עכשיו בחי' תורה, א\"כ איך נא' דהיחוד זהו ג\"כ תורה, וצ\"ל דהנשואין והיחוד ז\"ע פנימיות התורה שיתגלה לע\"ל, וא\"כ גם עכשיו"],[2000580158,"זהו ענין אגדות וכמ\"ש בזהר בענין ואגידה שהוא בחי' ההשפעה מן הגימ\"ל לדלי\"ת שמשפיע לו בחי' יו\"ד, ועי\"ז נעשה מן ד' ה\"א. ונמצא כי הלכות ואגדות זהו ענין אירוסין ונשואין שיש בבחי' התורה, הלכות שבתורה זה\"ע אוהל ומקדש שבתורה שזהו כמו אירוסין טבעת קדושין בחי' מקיף לבד, אבל נשואין יחוד זהו בחי' אגדות. גם בעבודה בנש\"י יש ב' בחי', שז\"ע עיני כל אליך ישברו, ואח\"כ נעשית כלה בה\"א כו'.\n<b>ולהבין</b> ענין ושכנתי בתוכם צ\"ל ענין השראת השכינה שהי' במקדש, שאנו אומרי' ואין אנו יכולי' לעלות ולראות ולהשתחוות לפניך, וצ\"ל מהו ולהשתחוות לפניך, כי הנה ענין ההשתחוואה בפנימיות ז\"ע בטל רצונך מפני רצונו והשתחוואה זו היו מקבלי' במקדש ע\"י גילוי שכינה, פי' שכינה מה ששוכן בתחתונים בבחי' גילוי, ועי\"ז היו הנשמות נכללי' ומתבטלי' כנר בפני האבוקה, שהרי השכינה היא מקור הנשמות ברא כרעא דאבוה, והנה כשיורדת המל' בבריאה נק' שכינה ששוכן בהיכל קד\"ק דבריאה, והיינו כשנעשית עתיק לבריאה ונק' אז מלך יחיד, והר\"ז כענין המשכת האבוקה שעי\"ז מתבטלי' הנשמות כנר בפני האבוקה, ולכן בבהמ\"ק כשהאיר בחי' זו בקדש הקדשים הי' ענין ההשתחוואה בחי' הביטול של הנשמות כו'.\n<b>ועוד</b> יובן ענין ההשתחוואה ממשנ\"ת בלק\"ת בד\"ה שובה הראשון שיש השתחוואה ברוחניות שכופף ומבטל שכלו לדבר הנשפע והוא בלעו\"ז, וכמו\"כ נשמע לענין השתחוואה בתפלה היינו שכופף ומבטל שכלו אליו ית', וגם בטל רצונך. ועוד יובן ענין השתחוואה ע\"ד מ\"ש יבוא כל בשר להשתחוות, בשר הוא בחי' יסוד האש ע\"ד פני שור וע\"ד בשרפי' נא' לחמי לאשי. וההשתחוואה זהו בחי' ביטול שלמעלה מרשפי אש וא\"כ זהו כענין שנא' ואחר האש קול דממה דקה תמן קאתי מלכא, וכענין בת אבי שהיא מבחי' מוחין דאבא שלמעלה מבחי' בת אמי מוחין דאימא, וזהו שארז\"ל במד\"ר פ' וירא פנ\"ו אר\"י הכל בזכות השתחוואה אברהם לא חזר מהר המורי' אלא בזכות השתחוואה, התורה לא ניתנה אלא בזכות השתחוואה שנא'"],[2000580159,"והשתחויתם מרחוק, וז\"ע יפה שיחתן של עבדי אבות מתורתן של בנים, מפני שהי' בבחי' הביטול ע\"ד שנא' באליעזר ויקוד וישתחו, ובספר פנים יפות ס\"פ משפטי' שההשתחוואה בפישוט ידי' ורגלי' זהו כענין התפשטו' כח הגשמי' הנפרדי', וי\"ל כי העמידה בציור אדם הראש גבוה, אבל בהשתחוואה הראש והגוף והרגלי' שוים, וא\"כ זהו בחי' ביטול לבחי' ששם חכמה ועשי' שוין, והיינו בחי' כי לא אדם הוא כו'.\nג) <b>ואפ\"ל</b> ע\"ד שנת' ע\"פ מאמר הזהר ע\"פ אלה תולדות נח נח לשון מנוחה, ענין עה\"ח ועה\"ד, שמבחי' עה\"ד אף כמו שהוא למעלה דהיינו בז\"א מהחזה ולמטה ששם נסתיימו המוחין דאו\"א, אזי נמשך רשפי אש בחי' חו\"ג המגולים, אבל עה\"ח הוא בחי' חו\"ג המכוסי' ביסוד אימא, כענין הביטול דקול דממה דקה, שז\"ע שמו\"ע, ונת' שם שורש ב' בחי' אלו שמצד הק\"ו שייך עליות מלמטלמ\"ע רצו\"ש, אבל מצד העיגול הגדול שלמעלה מהקו הוא אוא\"ס המקיף ד' עולמות בשוה נמשך הביטול לגמרי בחי' חכ' כח מ\"ה, כמו משה ונחנו מ\"ה כבד פה, וז\"ע ההשתחוואה שלכן ההשתחוואה בפישוט ידי' ורגלי' מורה כי חב\"ד חג\"ת נה\"י שוין, וכמשנ\"ת במ\"א בענין האופנים שאין בהם ציור קומה, ואפ\"ל שז\"ע אדם ובהמה תושיע ה' שע\"י שהאדם הוא בחי' ציור קומה בצלמינו כדמותינו ועושה א\"ע כבהמה שבבהמה הראש והגוף שוין, עי\"ז תושיע הוי'. ועוי\"ל ענין ההשתחוואה ע\"ד שיש דחילו ורחימו ורחימו ודחילו, ע\"כ יראה עילאה שגבוה מעה\"ד מזה נמשך ההשתחוואה, וזהו בחי' עבד שלמעלה מבחי' בן בחי' משה עבדי, ולכן השתחוואה זו הי' נמשך בבהמ\"ק כמ\"ש בענין השמים כסאי והארץ כו' איזה בית אשר ע\"י תומ\"צ ממשיכי' בחי' נר\"נ, אך בית זהו מקיף דחי' יחידה בחי' בכל מאדך, ומזה נמשך הכריעות וההשתחוואות דשמו\"ע, ולכן בהמק\"ד הנק' בית ששם האיר בחי' ח\"י היינו ענין מלך יחיד ע\"כ מזה נמשך בחי' ההשתחוואה בנפש ביטול דח\"י שלמעלה מן השכל, ע\"ד אחת היא יונתי שמקבלת מבחי' יחיד כו'. ועוד נת' כה\"ג בענין יהודא אתה יודך אחיך כי ראובן שמעון לוי זהו ק\"ש ואמת ויציב, אבל יהודה הודאה וביטול לגמרי לבחי' סוכ\"ע זה\"ע שמו\"ע וכענין הביטול דחו\"ב שגבוה מאהוי\"ר, וז\"ע יהודה אתה בחי' היכל קדה\"ק שמו\"ע שהוא בג\"ר שלמעלה מהיכל האהבה וז\"ע ההשתחוואה, וכענין שנת' בדרוש ל\"ג בעומר ההפרש בין ברכה להודאה, אשר ברוך הוא מבחי' חכ' אבל לגבי עת\"י אין שייך שום השגה כ\"א הודאה וביטול לגמרי, וזהו כענין מל\"ת לגבי מ\"ע שהם ג\"כ כענין הודאה לגבי ברכה כי מ\"ע ז\"ע קום ועשה כעין ברכה, ול\"ת מבחי' שא\"א להמשיך שם בכלי כ\"א ע\"י הודאה וז\"ע הל\"ת, ולכן בבהמק\"ד"],[2000580160,"שהאיר בחי' עת\"י דבריאה ששרשו מעת\"י דאצי' עי\"ז נמשך ההשתחוואה, וכמ\"ש לע\"ל והי' ביום ההוא יתקע בשופר גדול כו' והשתחוו כו' כי ע\"י שופר גדול מאיר מפנימיות ע\"י ומזה יומשך ההשתחוואה והביטול כו' ומעין זה הוא תפלת נעילה דיוהכ\"פ.\nד) <b>והנה</b> בתו\"א ד\"ה והנה אנחנו מאלמי' אלומי' נת' שיש בענין ההשתחוואה ב' בחי', וע' בד\"ה יביאו לבוש מל' שהכריעות וההשתחוואות דשמו\"ע הן כריעות הראש שהוא המשכת בחי' חכ' עילאה ונמשך דרך חוט השדרה ח\"י חוליות ח\"י ברכאן דצלותא עד שנמשך בבחי' ירכין במודי' ושים שלום המשכת השפע מח\"ע בח\"ת, ובד\"ה מאלמי' הנ\"ל פי' ב' בחי' בהשתחוואה, הא' בחי' ביטול שבטל ומשתחווה ע\"ד וצבא השמים לך משתחוים שהם מתבטלי', הב' ההמשכה שמרכין ראשו וממשיכו למטה, ובאמת הא בהא תלי' שע\"י הביטול גורם ההמשכה, וז\"ע ותשתחוין לאלומתי והיינו שע\"י הביטול גרמו להמשיך השפע מהדעת ומכח\"ב בבחי' יוסף בחי' יסוד כו', וזהו ברוך ה' המבורך לע\"ו דא אפיקו דברכאן, ונה\"י חדשים נמשכי' מהכתר. ועד\"ז יובן ענין ההשתחוואה בבהמק\"ד שע\"י ההשתחוואה וביטול זה גרמו ההמשכה מלמעלה מבחי' ח\"ע, וז\"ע יחוד עליון דושכנתי בתוכם המשכת אור התורה בכנס\"י וזהו שאנו אומרים ואין אנו יכולי' כו' ולהשתחוות כו' שע\"י שאין ההשתחוואה והביטול ממילא לא נמשך האור והשפע מלמעלה, וז\"ע ונהר יחרב ויבש. ובאו\"ת מהמגיד נ\"ע ברמזי אגדות בענין מארז\"ל לא הכל בקימה ולא הכל בהשתחוואה מלך בקימה שרים בהשתחוואה פי' ג\"כ דהשתחוואה הוא המשכה מלמעלמ\"ט, וכן במ\"מ בענין ותשתחוין לאלומתי כולהי ספירן נגדין בי' כדי לאשפעה בכנס\"י, וכן פי' בענין אחד עשר כוכבי' שהם י\"ב גבולי אלכסון חוץ מהמיוחד ליסוד והם משתחווין לי פי' נגדין בי', וז\"ע השתחוו להוי' בהדרת קודש ר\"ת קבלה ואומרי' זה בשבת, ובחול אומרי' הריעו לה' כל הארץ ר\"ת הלכה, כי ההשתחוואה יש בה שני בחי' כנ\"ל וזה מאיר בשבת שע\"י הביטול בא ההמשכה כנ\"ל.\nה) <b>ולהבין</b> איך נמשך זה ע\"י בהמק\"ד, י\"ל מ\"ש הרמב\"ן ר\"פ תרומה שענין המשכן שיהי' הכבוד ששכן בהר סיני כמ\"ש וישכון כבוד ה' על הר סיני, שיהי' שוכן במשכן בנסתר, כי במ\"ת הי' בגילוי, ועל כל דבור פרחה נשמתן דאית רצון ואית רצון, אית רצון הנמשך מהבינה והדעת ע\"ד נודע בשערי' בעלה"],[2000580161,"לכל חד לפום מה דמשער בליבי', ואית רצון שלמעלה מהשכל שהוא בחי' כתר ונק' א\"א בחי' יחידה, ורצון זה נמשך לישראל ע\"י מ\"ת שהדיבור הוא המשכה ממהו\"ע ית' לנש\"י, וז\"ע פב\"פ דיבר ה' עמכם כי במ\"ת נמשך לכאו\"א בחי' ש' הוי' בפנים שלכם, והאיר שורש הנשמה הנק' מזלי' בתוך הנשמה שבגוף, והיינו בחי' חכ' וכתר שהם בחי' מקיפי' ח\"י שבנשמה האירו בפנימיות היינו בנר\"ן, והנה כמו בנשמה יש נר\"נ אור פנימי, וח\"י מקיפי', כמ\"כ למעלה ז\"ע ממכ\"ע בחי' נר\"נ, וסוכ\"ע בחי' חכ' וכתר, ולכן במ\"ת גילוי סוכ\"ע בחי' כתר וח\"ע היינו בחי' כבוד עילאה בממכ\"ע בחי' כבוד תתאה, עי\"ז הי' הגילוי בנפש גילוי בחי' מזלי' בנר\"ן, וזהו שפרחה נשמתן, כי מזל הנשמה זהו כענין הנשמה יתירה שמאיר בשבת שהיא מבחי' רצון העליון והיינו ע\"י גילוי סוכ\"ע בשבת בחי' חכ' וכתר, וז\"ע סעודתא דע\"ק, ועד\"ז יובן בהמשכן מבחי' ונועדתי לך שמה למע' מבחי' ונודעתי בחי' נודע בשערי', לכן מזה נמשך ההשתחוואה והביטול בחי' שלמעלה מהשכל כו'.\n<b>והנה</b> מה שגילוי זה שבמ\"ת הי' בגילוי ובבהמק\"ד הי' בהסתר זהו ע\"ד מ\"ש רז\"ל במד\"ר במדבר פ\"א יפה הוא הצניעות שנא' והצנע לכת, וא\"כ הוא כענין עלמא דאתכסי' ועלמא דאתגלי' כי הר סיני הוא מל', והמשכן בינה. והנה פסוק וכבוד הוי' מלא את המשכן נא' ב\"פ ס\"פ פקודי, והענין כמ\"ש כי על כל כבוד חופה שיש ב' בחי' כבוד כבוד תתאה וכבוד עילאה, וז\"ע מלא כל הארץ כבודו היינו כבוד תתאה, וכתי' ברוך כבוד ה' ממקומו מבחי' כבוד עילאה ומבחי' איה מקום כבודו שהוא חכ' וכתר, וב' בחי' כבוד זהו כענין אל דיעות ה' שמלמטלמ\"ע הוא דעת תחתון שלמטה היש ונתהוה מאין, ומלמעלמ\"ט הוא בהיפוך שלמטה הוא אין וכולא קמי' כלא חשיב, וז\"ע ב\"פ וכבוד ה' מלא את המשכן, ע\"ד פקודי המשכן משכן העדות כו'. והנה גם בחי' כבוד תתאה שהאיר במשכן אינו ע\"ד שארז\"ל ברכות דמ\"ג סע\"ב אסור לאדם שיהלך בקומה זקופה שנא' מלא כל הארץ כבודו, שבכל הארץ השראה זו היא בבחי' מקיף, דאל\"כ איך מלא כה\"כ והכתי' וכבודי לאחר לא אתן דפי' הרמ\"ז כבודי ע\"ס דמל' שהם לבוש אל הפנימי', אלא רק ע\"ד אור מקיף, ועד\"ז ארז\"ל ללמדך שאין מקום פנוי מן השכינה אפי' סנה, ואדמו\"ר נ\"ע פי' ולכבודי בראתיו הוא כתר מל', ובבהמ\"ק ובמשכן הי' הכבוד מלא בפנימיות ע\"ד המחשבה מאירה במוח בגילוי וברגל בהעלם. נמצא נת' שבבהמ\"ק ובמשכן הי' שורה כבוד עילאה וכבוד תתאה שה\"ע אל דיעות כו' שמשם שורש ביטול היש וביטול אמיתי, וכבר מבואר לעיל שכבוד עילאה הוא בחי' ח\"ע ז\"ע בחי' סוכ\"ע בחי' ח\"י מקיף דנשמה שז\"ע למ\"ד מ\"ם דצלם, שגילוי המקיף של הנשמה גבוה מגילוי אלי', ובמ\"ת ודאי האיר המקיף בפנימי שז\"ע פרחה נשמתן, לכן מב' בחי' כבוד שהאיר במשכן נמשך ב' בחי' ביטול, הא' ביטול היש הנמשך מכבוד תתאה ע\"ד בכל נפשך שנמשך"],[2000580162,"מבשכמל\"ו, ועיקר ביטול זה לנה\"ב ששרשה מחיות המרכבה הנושאות את הכבוד, ומכבוד עילאה נמשך ביטול אמיתי לנה\"א בחי' השתחוואה פנימית, וכענין ב' בחי' כלה, ובחי' זו עכשיו ז\"ע שמו\"ע כריעות והשתחוואות ומסיים שים שלום דפי' השלום הוא חיבור ב' הדיעות שיהי' דעת עליון של המשפיע מאיר ונמשך גם בדעת [תחתון] של נש\"י, וזהו שלום שמקשר ומחבר ב' הפכים ב' בחי' כבוד הנ\"ל. וע\"פ הקבלה שים שלום המשכת הטפה, פי' המשכת הדעת, שלכן ח\"י ברכאן נגד ח\"י חוליות כו'.\nו) <b>אך</b> כדי להיות וכבוד הוי' מלא צ\"ל תחלה יריעות המשכן וכמ\"ש נוטה שמים כיריעה, ובחי' מקיף זה רומז לבחי' אי' מקום כבודו שבחי' אי' הוא המקור של כבודו, אי\"ה ג\"ר כח\"ב, כי היריעות הם מעשה המצות שהם המשכת מקיפים. והענין כי מצוה ל' צוותא וחיבור שבהם חיבור המאציל א\"ס ב\"ה שיאיר בע\"ס דאצי', וכמו\"כ עשר יריעות המשכן כי רש\"י ז\"ל פי' ע\"פ עלי פלשת התרועעי, התחברי, ובשורש ישע פי' יריעה ל' ריעות או רועה, והיינו כענין ריעי' האהובים מדות שלמעלה מהשכל, שאין שם התחלקות, גם המל' נק' יריעה והיינו שמחברת אצי' עם בי\"ע ונעשית עתיק לבי\"ע, וזהו נוטה שמי' כיריעה, וגם ע\"ס נק' עשר יריעות כי ע\"ס זהו להיות התחברות אין סוף לבי\"ע, וז\"ע עשר יריעות המשכן ג\"כ. וגם לפי' נוטה שמים זהו בחי' סוכ\"ע כיריעה, הרי סוכ\"ע ג\"כ התחברות א\"ס לעולמות שמצד עצמותו אינו מגדר עלמין כלל, לא בבחי' ממלא ולא בבחי' סובב, לכן המשכת סוכ\"ע זהו כיריעה. ועוי\"ל יריעה שדוחה הרע מלשון אל ירע לבבך, ובערת הרע, שז\"ע קיום מל\"ת שז\"ע שחורה אני דקאי על קיום מל\"ת ועי\"ז ונאוה כיריעות שלמה. ועוי\"ל כיריעה ע\"ש מ\"ש בלק\"ת בד\"ה כי כאשר השמים החדשים דפי' השמים כסאי שמים בחי' כתר וממנו נמשך הפרסא שבין אצי' לבי\"ע ע\"ד שהמשל נמשך מעומק השכל, והנה כמו\"כ נק' בהמק\"ד כסא כבוד מרום מראשון מקום מקדשינו, לכן זהו ע\"י היריעות, נמצא היריעות י\"ל כמו הפרסא שבו וע\"י נמשך הכבוד להאיר בהיכל קדק\"ד דבריאה יצי', וכמ\"כ באצי' יש כמה פרסות הא' בכתר, הב' בין בינה לז\"א שז\"ע מי ברא אלה מבטן מי יצא הקרח, ובפרדס כ' יריעה נק' ת\"ת היינו כי מת\"ת דאו\"א נעשה כתר לז\"א שז\"ע הפרסא שבין בינה לז\"א, וממנו שורש הפרסא שבין אצי' לבי\"ע. גם כי במשכן חיבור ב' בחי' כבוד כנ\"ל וכתי' כי על כל כבוד חופה שקודם היחוד צ\"ל חופה, וז\"ע יריעות המשכן, וי\"ל כי חופה זהו שם אל הכולל ב' הדיעות המחברן יחד, וז\"ע שבני גרשון נשאו היריעות לקשר ולחבר מדות דז\"א בא\"א, וזהו נוטה שמים כיריעה בחי' תשובה, כי היריעות הם"],[2000580163,"הרצון שלמעלה מהשכל להפך הטבע, ופי' אהל מועד שההמשכה צ\"ל ע\"י אוהל ומקיף בתחלה שזהו ע\"י המצות כו'.\n<b>וכלליות</b> כל המצות נק' בשם צדקה כמ\"ש וצדקה תהי' לנו כי נשמור לעשות את כל המצוה הזאת, ולכן ע\"י הצדקה ממשיכי' כמו בחי' היריעות שע\"י נמשך ב' בחי' כבוד הנ\"ל, ולכן הגם כי כבוד חכמי' ינחלו, מ\"מ יכולי' הבעלי עסק ג\"כ להמשיך בחי' זו כמ\"ש פזר נתן לאביוני' קרנו תרום בכבוד, פי' ע\"י הצדקה שמפזר לאביונים ע\"י נמשך בחי' רוממות קרן, והיינו כי קרן הוא בחי' מל' כמ\"ש במ\"א בענין ובא לו לקרן, ורוממות קרן היינו בחי' שורש המל' כמו כח אד', או מל' דא\"ס, וה\"ז כענין המקיף דיריעות, ועי\"ז נמשך בכבוד ב' בחי' כבוד כבוד עילאה וכבוד תתאה שבבהמ\"ק, שגם עכשיו ברוחניות יאיר בחי' זו."],[2000580164,"<h3>ולבני אהרן תעשה כותנות</h3>\n<b></b><b>בס\"ד. (ש\"פ תצוה, ל\"ב). תצוה פך\"ח מ\"ם מ\"ב.</b>\nתצוה\n<b>ולבני</b> אהרן תעשה כתנות ועשית להם אבנטי' ומגבעות וגו' ועשה להם מכנסי בד וגו' והיינו שזהו ד' בגדי' שכל כהן צריך ללבוש אותם, והם ד' בגדי לבן, ומוסיף עליו כה\"ג חושן ואפוד ומעיל וציץ שהם ד' בגדי זהב כמ\"ש במשנה ספ\"ז"]]});
